local function fetchLibrary(url)
	local ok, result = pcall(function()
		local source
		local httpRequest = request or http_request or (syn and syn.request)
		if httpRequest then
			local response = httpRequest({ Url = url, Method = "GET" })
			source = response and response.Success and response.Body
		end
		source = source or game:HttpGet(url)
		return loadstring(source)()
	end)
	if ok and result then return result end
	warn("Zenith: falha ao carregar " .. url .. " -> " .. tostring(result))
	return nil
end
local function loadOuroborosShim()
	local Library = fetchLibrary("https://raw.githubusercontent.com/sixfourshi/Games/refs/heads/main/fip?cb=" .. tostring(os.time()))
	if type(Library) ~= "table" or type(Library.CreateWindow) ~= "function" then return nil end
	pcall(function() Library:SetDefaultTheme("Rose") end)
	local function applyPurpleTheme()
		local function isPurple(color)
			local hue, saturation = Color3.toHSV(color)
			return saturation > 0.25 and hue > 0.69 and hue < 0.86
		end
		local function findRegistry(source, depth)
			for _, value in pairs(source) do
				if type(value) == "table" then
					if rawget(value, "Rose") ~= nil then return value end
					if depth > 0 then
						local found = findRegistry(value, depth - 1)
						if found then return found end
					end
				end
			end
		end
		local function shift(value, depth)
			if typeof(value) == "Color3" then
				local hue, saturation, brightness = Color3.toHSV(value)
				if saturation > 0.25 then return Color3.fromHSV(0.76, saturation, brightness) end
				return value
			end
			if type(value) == "table" and depth > 0 then
				local copy = {}
				for key, inner in pairs(value) do copy[key] = shift(inner, depth - 1) end
				return copy
			end
			return value
		end
		local function purpleScore(theme)
			local score = 0
			if type(theme) ~= "table" then return 0 end
			for _, value in pairs(theme) do
				if typeof(value) == "Color3" and isPurple(value) then score = score + 1 end
			end
			return score
		end
		local found, registry = pcall(findRegistry, Library, 2)
		if found and registry then
			local bestName, bestScore = nil, 0
			for name, theme in pairs(registry) do
				local score = purpleScore(theme)
				if score > bestScore then bestName, bestScore = name, score end
			end
			if bestName and Library:SetDefaultTheme(bestName) ~= false then return end
			if type(registry.Rose) == "table" then
				registry.Zenith = shift(registry.Rose, 3)
				Library:SetDefaultTheme("Zenith")
				return
			end
		end
		for _, name in ipairs({ "Purple", "Violet", "Amethyst", "Grape", "Lavender", "Orchid", "Plum" }) do
			if pcall(function() Library:SetDefaultTheme(name) end) then return end
		end
	end
	pcall(applyPurpleTheme)
	local Shim = { isOuroboros = true }
	local modalGui = nil
	local function askText(title, placeholder, initial, onSubmit)
		local okAsk = pcall(function()
			local playerGui = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
			if not (modalGui and modalGui.Parent) then
				modalGui = Instance.new("ScreenGui")
