			box.Text = initial or ""
			box.ClearTextOnFocus = false
			Instance.new("UICorner", box).CornerRadius = UDim.new(0, 8)
			local function makeBtn(text, x, color)
				local button = Instance.new("TextButton")
				button.Parent = frame
				button.Position = UDim2.new(x, x == 0 and 12 or 4, 1, -46)
				button.Size = UDim2.new(0.5, -16, 0, 34)
				button.BackgroundColor3 = color
				button.BorderSizePixel = 0
				button.Font = Enum.Font.GothamBold
				button.TextSize = 13
				button.TextColor3 = Color3.new(1, 1, 1)
				button.Text = text
				Instance.new("UICorner", button).CornerRadius = UDim.new(0, 8)
				return button
			end
			local okButton = makeBtn("OK", 0, Color3.fromRGB(255, 105, 150))
			local cancelButton = makeBtn("Cancelar", 0.5, Color3.fromRGB(48, 50, 70))
			okButton.Activated:Connect(function()
				local text = box.Text
				frame:Destroy()
				pcall(onSubmit, text)
			end)
			cancelButton.Activated:Connect(function() frame:Destroy() end)
		end)
		return okAsk
	end
	local function callAny(object, names, ...)
		for _, name in ipairs(names) do
			if type(object) == "table" and type(object[name]) == "function" then
				return pcall(object[name], object, ...)
			end
		end
		return false
	end
	local function parseColor(text)
		local hex = tostring(text):match("^%s*#?(%x%x%x%x%x%x)%s*$")
		if hex then
			return Color3.fromRGB(tonumber(hex:sub(1, 2), 16), tonumber(hex:sub(3, 4), 16), tonumber(hex:sub(5, 6), 16))
		end
		local r, g, b = tostring(text):match("(%d+)%D+(%d+)%D+(%d+)")
		if r then return Color3.fromRGB(math.min(255, tonumber(r)), math.min(255, tonumber(g)), math.min(255, tonumber(b))) end
		return nil
	end
	local function wrapTab(tab)
		local state = { group = nil, count = 0 }
		local function newGroup(title)
			state.count = state.count + 1
			local left = state.count % 2 == 1
			local group
			local ok, result = pcall(function()
				local info = { Name = title or "Geral", Icon = "layers" }
				return left and tab:AddLeftGroupbox(info) or tab:AddRightGroupbox(info)
			end)
			if ok then
				group = result
			else
				local ok2, result2 = pcall(function()
					local info = { Name = title or "Geral" }
					return left and tab:AddLeftGroupbox(info) or tab:AddRightGroupbox(info)
				end)
				group = ok2 and result2 or nil
			end
			state.group = group
			return group
		end
		local function group()
			return state.group or newGroup("Geral")
		end
		local wrapped = {}
		function wrapped.Section(_, options)
			newGroup(options and options.Title or "Geral")
			return {}
		end
		function wrapped.Paragraph(_, options)
			local title, desc = tostring(options.Title or ""), tostring(options.Desc or "")
			local target = group()
			if not target then return nil end
			local ok = pcall(function() return target:CreateParagraph({ Name = title, Title = title, Content = desc, Desc = desc }) end)
			if ok then return {} end
			ok = pcall(function() return target:CreateLabel({ Name = title .. (desc ~= "" and (" - " .. desc) or ""), Text = title .. " " .. desc }) end)
			if ok then return {} end
			pcall(function() return target:CreateLabel(title .. (desc ~= "" and (" - " .. desc) or "")) end)
			return {}
		end
		function wrapped.Button(_, options)
			local target = group()
			if not target then return nil end
			target:CreateButton({
				Name = tostring(options.Title),
				Description = options.Desc,
				Callback = function()
					if options.Callback then options.Callback() end
				end,
			})
			return {}
		end
		function wrapped.Toggle(_, options)
			local target = group()
			if not target then return nil end
			local current = options.Default == true
			local suppress = false
			local native
			native = target:CreateToggle({
				Name = tostring(options.Title),
				Description = options.Desc,
				CurrentValue = current,
				Callback = function(value)
					if suppress then return end
					current = value == true
					if options.Callback then options.Callback(current) end
				end,
			})
			local control = {}
			function control:Set(value)
				value = value == true
				if value == current then return end
				current = value
				suppress = true
				callAny(native, { "Set", "SetValue", "SetState" }, value)
				suppress = false
				if options.Callback then options.Callback(value) end
			end
			return control
		end
		function wrapped.Slider(_, options)
			local target = group()
			if not target then return nil end
			local info = options.Value or {}
			local suppress = false
			local native
			native = target:CreateSlider({
				Name = tostring(options.Title),
				Description = options.Desc,
				Range = { info.Min or 0, info.Max or 100 },
				Increment = options.Step or 1,
				CurrentValue = info.Default or info.Min or 0,
				Callback = function(value)
					if suppress then return end
					if options.Callback then options.Callback(value) end
				end,
			})
			local control = {}
			function control:Set(value)
				suppress = true
				callAny(native, { "Set", "SetValue" }, value)
				suppress = false
				if options.Callback then options.Callback(value) end
			end
			return control
		end
		function wrapped.Dropdown(_, options)
			local target = group()
			if not target then return nil end
			local suppress = false
			local native
			native = target:CreateDropdown({
				Name = tostring(options.Title),
				Description = options.Desc,
				Options = options.Values or {},
				CurrentOption = options.Value,
				AllowNone = false,
				Callback = function(option)
					if suppress then return end
					if options.Callback then options.Callback(option) end
				end,
			})
			local control = {}
			function control:Select(option)
				suppress = true
				callAny(native, { "Set", "SetOption", "Select", "SetValue" }, option)
				suppress = false
				if options.Callback then options.Callback(option) end
			end
			function control:Refresh(values)
				callAny(native, { "Refresh", "SetOptions", "UpdateOptions", "SetValues" }, values)
			end
			return control
		end
		function wrapped.Input(_, options)
			local target = group()
			if not target then return nil end
			local title = tostring(options.Title)
			local ok = pcall(function()
				target:CreateInput({
					Name = title,
					Description = options.Desc,
					PlaceholderText = options.Placeholder or "",
					CurrentValue = "",
					RemoveTextAfterFocusLost = false,
					Callback = function(text)
						if options.Callback then options.Callback(tostring(text or "")) end
					end,
				})
			end)
			if not ok then
				local stored = ""
				target:CreateButton({
					Name = title .. " (toque para digitar)",
					Callback = function()
						askText(title, options.Placeholder, stored, function(text)
							stored = text
							if options.Callback then options.Callback(text) end
						end)
					end,
				})
			end
			return {}
		end
		function wrapped.Colorpicker(_, options)
			local target = group()
			if not target then return nil end
			local current = options.Default or Color3.new(1, 1, 1)
			local title = tostring(options.Title)
			local suppress = false
			local native
			local function build(methodName)
				return pcall(function()
					native = target[methodName](target, {
						Name = title,
						Description = options.Desc,
						Color = current,
						CurrentValue = current,
						Default = current,
						Callback = function(color)
							if suppress then return end
							current = color
							if options.Callback then options.Callback(color) end
						end,
					})
				end)
			end
			local ok = build("CreateColorPicker")
			if not ok then ok = build("CreateColorpicker") end
			if not ok then
				target:CreateButton({
					Name = title .. " (R,G,B ou #HEX)",
					Callback = function()
						askText(title, "255,0,0  ou  #FF0000", "", function(text)
							local color = parseColor(text)
							if color then
								current = color
								if options.Callback then options.Callback(color) end
							end
						end)
					end,
				})
			end
			local control = {}
			function control:Set(color)
				current = color
				suppress = true
				callAny(native, { "Set", "SetValue", "SetColor" }, color)
				suppress = false
			end
			return control
		end
		return wrapped
	end
	function Shim:AddTheme() end
	function Shim:Notify(options)
		pcall(function()
			Library:Notify({
				Title = options.Title or "Zenith",
				Content = options.Content or "",
				Type = "Info",
				Duration = options.Duration or 3,
			})
		end)
	end
	function Shim:CreateWindow()
		local native = Library:CreateWindow({
			Name = "Zenith",
			LoadingSubtitle = "by Potent",
			ToggleUIKeybind = "RightShift",
			ConfigurationSaving = { Enabled = false, FolderName = "TCSHubMini", FileName = "ui" },
			ToggleButton = { Platform = "Both" },
		})
		local window = {}
		function window:Tab(options)
			local tab
			local ok, result = pcall(function() return native:CreateTab({ Name = options.Title, Icon = options.Icon }) end)
			if ok then
				tab = result
			else
				tab = native:CreateTab({ Name = options.Title })
			end
			return wrapTab(tab)
		end
		function window:Divider() end
		function window:Tag() return { SetTitle = function() end } end
		function window:EditOpenButton() end
		function window:CreateTopbarButton() end
		function window:SetToggleKey(key)
			pcall(function() native:SetKeybind(key and key.Name or "RightShift") end)
		end
		function window:Destroy()
			pcall(function() native:Destroy() end)
			if modalGui then pcall(function() modalGui:Destroy() end) end
		end
		return window
	end
	return Shim
end
