local function safeConnect(signal, name, callback)
	local errorCount = 0
	local connection
	connection = signal:Connect(function(...)
		local ok, err = pcall(callback, ...)
		if ok then return end
		errorCount = errorCount + 1
		if errorCount == 1 then
			warn("Zenith: erro em " .. name .. " -> " .. tostring(err))
		end
		if errorCount >= 20 then
			connection:Disconnect()
			warn("Zenith: " .. name .. " desligado por erros repetidos")
		end
	end)
	return connection
end
