local saveConfig, loadConfig, deleteConfigFile
do
	local httpService = game:GetService("HttpService")
	local CONFIG_FOLDER = "TCSHubMini"
	local CONFIG_FILE = CONFIG_FOLDER .. "/config.json"
	local SKIP_KEYS = {
		ballEspEnabled = true, autoKickEnabled = true,
		multiReachEnabled = true, goToBallEnabled = true, reachVisualEnabled = true,
		autoCatchEnabled = true, intelEnabled = true, diveEnabled = true, haloEnabled = true,
		skinEnabled = true, skinRainbow = true, worldClockOn = true, fpsBoostOn = true, fovOn = true,
		stretchOn = true, skyPreset = true, grassPreset = true, auraName = true,
		ballSkinEnabled = true, ballRainbow = true, ballTrailOn = true, ballLightOn = true, ballSoundEnabled = true,
	}
	function saveConfig()
		if not (writefile and makefolder and isfolder) then
			return false, "executor sem suporte a arquivos"
		end
		local data = {}
		for key, value in pairs(config) do
			if not SKIP_KEYS[key] then
				local kind = typeof(value)
				if kind == "Color3" then
					data[key] = { __color = { value.R, value.G, value.B } }
				elseif kind == "number" or kind == "string" or kind == "boolean" then
					data[key] = value
				end
			end
		end
		return pcall(function()
			if not isfolder(CONFIG_FOLDER) then makefolder(CONFIG_FOLDER) end
			writefile(CONFIG_FILE, httpService:JSONEncode(data))
		end)
	end
	function loadConfig()
		if not (readfile and isfile) then return false end
		local ok, data = pcall(function()
			if not isfile(CONFIG_FILE) then return nil end
			return httpService:JSONDecode(readfile(CONFIG_FILE))
		end)
		if not ok or type(data) ~= "table" then return false end
		for key, value in pairs(data) do
			local current = config[key]
			if current ~= nil and not SKIP_KEYS[key] then
				if type(value) == "table" and value.__color and typeof(current) == "Color3" then
					config[key] = Color3.new(value.__color[1], value.__color[2], value.__color[3])
				elseif typeof(current) == type(value) then
					config[key] = value
				end
			end
		end
		return true
	end
	function deleteConfigFile()
		if not (delfile and isfile) then return false end
		return pcall(function()
			if isfile(CONFIG_FILE) then delfile(CONFIG_FILE) end
		end)
	end
end
