local cleanupTasks = {}
local function registerCleanup(fn) table.insert(cleanupTasks, fn) end
local scriptDestroyed = false
local function destroyEverything()
	if scriptDestroyed then return end
	scriptDestroyed = true
	if config.autoSave then pcall(saveConfig) end
	for _, fn in ipairs(cleanupTasks) do pcall(fn) end
	if environment.TCSHubMiniDestroy == destroyEverything then
		environment.TCSHubMiniDestroy = nil
	end
end
