local function normalizeOption(option)
	if type(option) == "table" then
		return option.Title or option.Name or option[1]
	end
	return option
end
local gameActionUntil = 0
local function isGameActionActive()
	return config.toolGuard and os.clock() < gameActionUntil
end
do
	local ACTION_PRIORITIES = {}
	for _, priorityName in ipairs({ "Action", "Action2", "Action3", "Action4" }) do
		local ok, item = pcall(function() return Enum.AnimationPriority[priorityName] end)
		if ok and item then ACTION_PRIORITIES[item] = true end
	end
	local IGNORED_KEYS = {
		[Enum.KeyCode.W] = true, [Enum.KeyCode.A] = true, [Enum.KeyCode.S] = true, [Enum.KeyCode.D] = true,
		[Enum.KeyCode.Space] = true, [Enum.KeyCode.Up] = true, [Enum.KeyCode.Down] = true,
		[Enum.KeyCode.Left] = true, [Enum.KeyCode.Right] = true,
		[Enum.KeyCode.Insert] = true, [Enum.KeyCode.End] = true, [Enum.KeyCode.RightShift] = true,
	}
	local function markGameAction(duration)
		gameActionUntil = math.max(gameActionUntil, os.clock() + duration)
	end
	local animatorConnection = nil
	local toolConnection = nil
	local function watchCharacter(character)
		if animatorConnection then animatorConnection:Disconnect() end
		if toolConnection then toolConnection:Disconnect() end
		animatorConnection, toolConnection = nil, nil
		toolConnection = character.ChildAdded:Connect(function(child)
			if child:IsA("Tool") then markGameAction(1) end
		end)
		task.spawn(function()
			local humanoid = character:WaitForChild("Humanoid", 5)
			local animator = humanoid and (humanoid:FindFirstChildOfClass("Animator") or humanoid:WaitForChild("Animator", 3))
			if not animator or character ~= localPlayer.Character then return end
			animatorConnection = animator.AnimationPlayed:Connect(function(track)
				if ACTION_PRIORITIES[track.Priority] and not track.Looped then
					markGameAction(math.clamp(track.Length, 0.3, 1.5))
				end
			end)
		end)
	end
	if localPlayer.Character then watchCharacter(localPlayer.Character) end
	local characterWatchConnection = localPlayer.CharacterAdded:Connect(watchCharacter)
	local hookedGameButtons = setmetatable({}, { __mode = "k" })
	local gameButtonConnections = {}
	local scanningGameButtons = false
	local function scanGameButtons()
		if scanningGameButtons then return end
		scanningGameButtons = true
		pcall(function()
			local gui = localPlayer:FindFirstChildOfClass("PlayerGui")
			if not gui then return end
			for index, descendant in ipairs(gui:GetDescendants()) do
				if (descendant:IsA("TextButton") or descendant:IsA("ImageButton"))
					and not hookedGameButtons[descendant]
					and not descendant:FindFirstAncestor("TCSHubMiniGui")
					and not descendant:FindFirstAncestor("TouchGui") then
					hookedGameButtons[descendant] = true
					table.insert(gameButtonConnections, descendant.InputBegan:Connect(function(input)
						if input.UserInputType == Enum.UserInputType.Touch
							or input.UserInputType == Enum.UserInputType.MouseButton1 then
							markGameAction(0.8)
						end
					end))
				end
				if index % 200 == 0 then task.wait() end
			end
		end)
		scanningGameButtons = false
	end
	task.spawn(function()
		while not scriptDestroyed do
			scanGameButtons()
			task.wait(15)
		end
	end)
	local keyConnection = userInputService.InputBegan:Connect(function(input, processed)
		if processed or input.UserInputType ~= Enum.UserInputType.Keyboard then return end
		if IGNORED_KEYS[input.KeyCode] then return end
		markGameAction(0.8)
	end)
	registerCleanup(function()
		characterWatchConnection:Disconnect()
		keyConnection:Disconnect()
		if animatorConnection then animatorConnection:Disconnect() end
		if toolConnection then toolConnection:Disconnect() end
		for _, connection in ipairs(gameButtonConnections) do
			connection:Disconnect()
		end
	end)
end
Loader.set(0.38, "Procurando a bola...")
local cachedBall, findBall, getBallSource
do
	local BALL_KNOWN_PATHS = {
		{ "TPS" },
		{ "WorkspaceStadiumMap1", "TPS" },
	}
	local BALL_SEARCH_NAMES = { "TPS", "Ball", "SoccerBall", "Football", "Bola" }
	local BALL_NAME_SET = {}
	for _, name in ipairs(BALL_SEARCH_NAMES) do
		BALL_NAME_SET[name] = true
	end
	local BALL_FIND_INTERVAL = 0.03
	local BALL_MISS_INTERVAL = 0.25
	local NATIVE_SEARCH_INTERVAL = 1
	local scannedBall = nil
	local customBall = nil
	local customName = ""
	local ballSource = "nenhuma"
	local lastFindTime = 0
	local lastNativeSearch = 0
	local lastMapScan = 0
	local mapBalls = setmetatable({}, { __mode = "k" })
	local lastCustomSearch = 0
	local structuralBalls = setmetatable({}, { __mode = "k" })
	local nameBalls = setmetatable({}, { __mode = "k" })
	local function resolveBallPart(instance)
		if not instance then return nil end
		if instance:IsA("BasePart") then return instance end
		if instance:IsA("Model") then
			return instance.PrimaryPart or instance:FindFirstChildWhichIsA("BasePart", true)
		end
		return nil
	end
	local function looksLikeBall(part)
		local size = part.Size
		return size.X >= 0.5 and size.X <= 8 and size.Y <= 8 and size.Z <= 8
	end
	local function findBallByKnownPath()
		for _, path in ipairs(BALL_KNOWN_PATHS) do
			local current = workspace
			for _, name in ipairs(path) do
				current = current and current:FindFirstChild(name)
			end
			local part = resolveBallPart(current)
			if part then
				return part, table.concat(path, ".")
			end
		end
		return nil
	end
	local function findCustomBall()
		if config.ballName == "" then return nil end
		if customName ~= config.ballName then
			customBall = nil
			customName = config.ballName
			lastCustomSearch = 0
		end
		if customBall and customBall.Parent then return customBall end
		local now = os.clock()
		if now - lastCustomSearch < NATIVE_SEARCH_INTERVAL then return nil end
		lastCustomSearch = now
		local part = resolveBallPart(workspace:FindFirstChild(config.ballName, true))
		if part and looksLikeBall(part) then customBall = part end
		return customBall
	end
	local function findByNativeNames()
		local now = os.clock()
		if now - lastNativeSearch < NATIVE_SEARCH_INTERVAL then return nil end
		lastNativeSearch = now
		for _, name in ipairs(BALL_SEARCH_NAMES) do
			local part = resolveBallPart(workspace:FindFirstChild(name, true))
			if part and looksLikeBall(part) then return part end
		end
		return nil
	end
	local function isStructuralBall(part)
		if part.Anchored then return false end
		local size = part.Size
		local biggest = math.max(size.X, size.Y, size.Z)
		local smallest = math.min(size.X, size.Y, size.Z)
		if biggest > 8 or smallest < 0.8 or biggest / smallest > 1.3 then return false end
		local isRound = (part:IsA("Part") and part.Shape == Enum.PartType.Ball)
			or part:IsA("MeshPart") or part:FindFirstChildOfClass("SpecialMesh") ~= nil
		if not isRound then return false end
		local model = part:FindFirstAncestorOfClass("Model")
		if model and model:FindFirstChildOfClass("Humanoid") then return false end
		if part:FindFirstAncestorOfClass("Accessory") or part:FindFirstAncestorOfClass("Tool") then return false end
		return true
	end
	local function nearestStructuralBall()
		local character = localPlayer.Character
		local hrp = character and character:FindFirstChild("HumanoidRootPart")
		local best, bestDistance = nil, math.huge
		for part in pairs(structuralBalls) do
			if part.Parent and not part.Anchored then
				local distance = hrp and (part.Position - hrp.Position).Magnitude or 0
				if distance < bestDistance then
					best, bestDistance = part, distance
				end
			end
		end
		return best
	end
	function findBall()
		local now = os.clock()
		if cachedBall and cachedBall.Parent then
			if now - lastFindTime < BALL_FIND_INTERVAL then return cachedBall end
		elseif now - lastFindTime < BALL_MISS_INTERVAL then
			return nil
		end
		lastFindTime = now
		local ball = findCustomBall()
		if ball then
			ballSource = "nome informado (" .. config.ballName .. ")"
		else
			local character = localPlayer.Character
			local hrp = character and character:FindFirstChild("HumanoidRootPart")
			local origin = hrp and hrp.Position
			local best, bestScore, bestSource = nil, math.huge, "nenhuma"
			local function consider(part, source)
				if not (part and part.Parent) or not part:IsDescendantOf(workspace) then return end
				local score = origin and (part.Position - origin).Magnitude or 0
				if part.Anchored then score = score + 500 end
				if score < bestScore then best, bestScore, bestSource = part, score, source end
			end
			local known, path = findBallByKnownPath()
			consider(known, known and ("caminho " .. path) or "")
			if now - lastMapScan > 1 then
				lastMapScan = now
				table.clear(mapBalls)
				for _, child in ipairs(workspace:GetChildren()) do
					if child:IsA("Folder") or child:IsA("Model") then
						local part = resolveBallPart(child:FindFirstChild("TPS"))
						if part then mapBalls[part] = child.Name end
					end
				end
			end
			for part, mapName in pairs(mapBalls) do consider(part, "mapa " .. mapName) end
			consider(scannedBall, "varredura inicial / bola nova")
			for part in pairs(nameBalls) do consider(part, "busca por nome") end
			if not best then consider(findByNativeNames(), "busca por nome") end
			if not best then
				for part in pairs(structuralBalls) do consider(part, "esfera solta (deteccao automatica)") end
			end
			ball, ballSource = best, bestSource
		end
		cachedBall = ball
		return ball
	end
	function getBallSource()
		return ballSource
	end
	local function considerBall(instance)
		if not instance:IsA("BasePart") then return end
		local lowered = string.lower(instance.Name)
		if BALL_NAME_SET[instance.Name] and looksLikeBall(instance) then
			scannedBall = instance
			nameBalls[instance] = true
		elseif (lowered:find("ball", 1, true) or lowered:find("bola", 1, true) or lowered:find("tps", 1, true))
			and not instance.Anchored and looksLikeBall(instance)
			and not instance:FindFirstAncestorOfClass("Tool") and not instance:FindFirstAncestorOfClass("Accessory") then
			nameBalls[instance] = true
		elseif isStructuralBall(instance) then
			structuralBalls[instance] = true
		end
	end
	local ballAddedConnection = workspace.DescendantAdded:Connect(considerBall)
	local ballRemovingConnection = workspace.DescendantRemoving:Connect(function(instance)
		if instance == cachedBall then cachedBall = nil end
		if instance == scannedBall then scannedBall = nil end
	end)
	task.spawn(function()
		for index, descendant in ipairs(workspace:GetDescendants()) do
			if scriptDestroyed then return end
			considerBall(descendant)
			if index % 400 == 0 then task.wait() end
		end
	end)
	registerCleanup(function()
		ballAddedConnection:Disconnect()
		ballRemovingConnection:Disconnect()
	end)
end
local REACH_MODES, REACH_ACTIVATIONS, REACH_METHODS, getReachParts, applyMultiReach, surfaceDistance
local testReachTouch, getReachStats
local getReachCalibration, getReachRange, resetReachCalibration
do
	REACH_MODES = { "Corpo todo", "Pes", "Mais proximo" }
	REACH_ACTIVATIONS = { "Sempre", "Ao chutar" }
	REACH_METHODS = { "Toque duplo", "Toque", "Segurar toque" }
	local KICK_ACTIVE_TIME = 0.7
	local KICK_BUTTON_TEXTS = { "chute", "passe", "longo", "shoot", "pass", "long" }
	local FOOT_PART_NAMES = {
		["Left Leg"] = true, ["Right Leg"] = true,
		["LeftFoot"] = true, ["RightFoot"] = true,
		["LeftLowerLeg"] = true, ["RightLowerLeg"] = true,
	}
	local reachLastTouch = setmetatable({}, { __mode = "k" })
	local kickButtonConnections = {}
	local hookedKickButtons = {}
	local lastKickPress = 0
	local lastKickScan = 0
	local multiReachConnection = nil
	local reachSpoofParts = setmetatable({}, { __mode = "k" })
	local reachHookTarget = nil
	local reachHookInstalled = false
	local function installReachHook()
		if reachHookInstalled then return end
		if not (hookmetamethod and newcclosure and getnamecallmethod and checkcaller) then return end
		reachHookInstalled = true
		local originalReachIndex
		originalReachIndex = hookmetamethod(game, "__index", newcclosure(function(self, key)
			if key == "Position" and reachHookTarget and reachSpoofParts[self] and not checkcaller() then
				return reachHookTarget.Position
			end
			return originalReachIndex(self, key)
		end))
		local originalReachNamecall
		originalReachNamecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
			local method = getnamecallmethod()
			if method == "GetPartBoundsInBox" and reachHookTarget and not checkcaller() then
				local result = originalReachNamecall(self, ...)
				if #result == 0 then
					local _, _, params = ...
					if typeof(params) == "OverlapParams" and params.FilterDescendantsInstances
						and table.find(params.FilterDescendantsInstances, reachHookTarget) then
						return { reachHookTarget }
					end
				end
				return result
			end
			return originalReachNamecall(self, ...)
		end))
	end
	local calibration = { maxHit = 0, samples = 0, pending = nil }
	function getReachCalibration()
		return calibration.samples, calibration.maxHit
	end
	function resetReachCalibration()
		calibration.maxHit = 0
		calibration.samples = 0
		calibration.pending = nil
	end
	function getReachRange()
		if config.reachAuto and calibration.samples >= 3 then
			return math.min(config.reachDetectRange, math.max(calibration.maxHit + 1.5, 3))
		end
		return config.reachDetectRange
	end
	local function resolveCalibration()
		local pending = calibration.pending
		if not pending then return end
		local elapsed = tick() - pending.time
		if elapsed < 0.12 then return end
		local ball = pending.ball
		if ball and ball.Parent then
			local now = ball.AssemblyLinearVelocity
			local change = Vector3.new(now.X - pending.velocity.X, 0, now.Z - pending.velocity.Z).Magnitude
			if change > 5 then
				calibration.samples += 1
				if pending.distance > calibration.maxHit then calibration.maxHit = pending.distance end
				calibration.pending = nil
				return
			end
		end
		if elapsed >= 0.35 then calibration.pending = nil end
	end
	function surfaceDistance(part, point, radius)
		local localPoint = part.CFrame:PointToObjectSpace(point)
		local half = part.Size / 2
		local clamped = Vector3.new(
			math.clamp(localPoint.X, -half.X, half.X),
			math.clamp(localPoint.Y, -half.Y, half.Y),
			math.clamp(localPoint.Z, -half.Z, half.Z)
		)
		return (point - part.CFrame:PointToWorldSpace(clamped)).Magnitude - radius
	end
	local reachPartsBuffer = {}
	local bodyPartsCache = {}
	local bodyPartsCharacter = nil
	local bodyPartsTime = 0
	local function getBodyParts(character)
		local now = os.clock()
		if character ~= bodyPartsCharacter or now - bodyPartsTime > 0.5 then
			table.clear(bodyPartsCache)
			for _, child in ipairs(character:GetChildren()) do
				if child:IsA("BasePart") then table.insert(bodyPartsCache, child) end
			end
			bodyPartsCharacter = character
			bodyPartsTime = now
		end
		return bodyPartsCache
	end
	function getReachParts(character, ball)
		local radius = ball.Size.X / 2
		local currentPosition = ball.Position
		local predictedPosition = currentPosition + ball.AssemblyLinearVelocity * config.reachLead
		local parts = reachPartsBuffer
		table.clear(parts)
		local nearestPart, nearestDistance = nil, math.huge
		for _, part in ipairs(getBodyParts(character)) do
			if config.reachMode ~= "Pes" or FOOT_PART_NAMES[part.Name] then
				local distance = math.min(
					surfaceDistance(part, currentPosition, radius),
					surfaceDistance(part, predictedPosition, radius)
				)
				if distance < nearestDistance then
					nearestPart = part
					nearestDistance = distance
				end
				if distance <= getReachRange() then
					table.insert(parts, part)
				end
			end
		end
		if config.reachMode == "Mais proximo" then
			table.clear(parts)
			if nearestPart and nearestDistance <= getReachRange() then
				parts[1] = nearestPart
			end
			return parts, nearestDistance
		end
		return parts, nearestDistance
	end
	local function scanKickButtons()
		lastKickScan = tick()
		local reachPlayerGui = localPlayer:FindFirstChildOfClass("PlayerGui")
		if not reachPlayerGui then return end
		for _, descendant in ipairs(reachPlayerGui:GetDescendants()) do
			if (descendant:IsA("TextButton") or descendant:IsA("TextLabel")) and not descendant:FindFirstAncestor("TCSHubMiniGui") then
				local text = descendant.Text:lower():match("^%s*(.-)%s*$")
				if table.find(KICK_BUTTON_TEXTS, text) then
					local button = descendant:IsA("GuiButton") and descendant or descendant:FindFirstAncestorWhichIsA("GuiButton")
					if button and not hookedKickButtons[button] then
						hookedKickButtons[button] = true
						table.insert(kickButtonConnections, button.InputBegan:Connect(function(input)
							if input.UserInputType == Enum.UserInputType.Touch
								or input.UserInputType == Enum.UserInputType.MouseButton1 then
								lastKickPress = tick()
							end
						end))
					end
				end
			end
		end
	end
	local function disconnectKickButtons()
		for _, connection in ipairs(kickButtonConnections) do
			connection:Disconnect()
		end
		table.clear(kickButtonConnections)
		table.clear(hookedKickButtons)
	end
	local function isReachActive()
		if config.reachActivation ~= "Ao chutar" then return true end
		return tick() - lastKickPress <= KICK_ACTIVE_TIME
	end
	local reachStats = { count = 0, last = 0 }
	local reachBudgetStart, reachBudgetUsed = 0, 0
	local holdingTouch = setmetatable({}, { __mode = "k" })
	function getReachStats()
		return reachStats.count, reachStats.last
	end
	local function fireReachTouch(ball, part)
		if not firetouchinterest then return end
		local method = config.reachMethod
		if not calibration.pending then
			calibration.pending = {
				time = tick(), ball = ball, velocity = ball.AssemblyLinearVelocity,
				distance = math.max(0, surfaceDistance(part, ball.Position, ball.Size.X / 2)),
			}
		end
		if method == "Segurar toque" and holdingTouch[part] then return end
		pcall(function()
			firetouchinterest(ball, part, 0)
			if method == "Toque duplo" then firetouchinterest(part, ball, 0) end
		end)
		if method == "Segurar toque" then
			if not holdingTouch[part] then
				holdingTouch[part] = true
				task.delay(0.12, function()
					holdingTouch[part] = nil
					pcall(function() firetouchinterest(ball, part, 1) end)
				end)
			end
		else
			pcall(function()
				firetouchinterest(ball, part, 1)
				if method == "Toque duplo" then firetouchinterest(part, ball, 1) end
			end)
		end
		reachStats.count = reachStats.count + 1
		reachStats.last = tick()
	end
	function testReachTouch()
		local character = localPlayer.Character
		local ball = findBall()
		if not (character and ball) then return false, "Personagem ou bola nao encontrados" end
		if not firetouchinterest then
			return false, "Seu executor nao tem firetouchinterest (o reach nao funciona nele)"
		end
		local sent = 0
		for _, part in ipairs(getBodyParts(character)) do
			fireReachTouch(ball, part)
			sent = sent + 1
		end
		return true, "Toque enviado com " .. sent .. " partes. Se a bola nao reagiu, o jogo valida o alcance no servidor."
	end
	function applyMultiReach(state)
		if multiReachConnection then
			multiReachConnection:Disconnect()
			multiReachConnection = nil
		end
		disconnectKickButtons()
		reachHookTarget = nil
		if not state then return end
		if not firetouchinterest then
			warn("Zenith: seu executor nao tem firetouchinterest; o reach nao vai funcionar")
			pcall(function()
				WindUI:Notify({ Title = "Reach", Content = "Seu executor nao tem firetouchinterest: o reach nao funciona nele.", Duration = 6 })
			end)
		end
		installReachHook()
		multiReachConnection = safeConnect(runService.Heartbeat, "multiReachConnection", function()
			if scriptDestroyed then return end
			if config.reachActivation == "Ao chutar" and tick() - lastKickScan > 5 then
				scanKickButtons()
			end
			if not isReachActive() then return end
			local character = localPlayer.Character
			if not character then return end
			local reachHumanoid = character:FindFirstChildOfClass("Humanoid")
			if reachHumanoid and (reachHumanoid.Health <= 0 or reachHumanoid.Sit) then return end
			local ball = findBall()
			if not ball or not ball.Parent then return end
			resolveCalibration()
			local now = tick()
