					local velocity = ball.AssemblyLinearVelocity
					if velocity.Magnitude > 6 and toBall.Magnitude > 6 and velocity:Dot(toBall) > 0 then
						reachHookTarget = nil
						return
					end
				end
			end
			local parts = getReachParts(character, ball)
			if #parts > 0 then
				reachHookTarget = ball
				table.clear(reachSpoofParts)
				for _, part in ipairs(parts) do reachSpoofParts[part] = true end
			else
				reachHookTarget = nil
			end
			for _, part in ipairs(parts) do
				if now - (reachLastTouch[part] or 0) >= config.reachInterval then
					if maxPerSecond > 0 and reachBudgetUsed >= maxPerSecond then break end
					reachLastTouch[part] = now
					reachBudgetUsed = reachBudgetUsed + 1
					fireReachTouch(ball, part)
				end
			end
		end)
	end
	registerCleanup(function()
		if multiReachConnection then multiReachConnection:Disconnect() end
		disconnectKickButtons()
		reachHookTarget = nil
	end)
end
Loader.set(0.46, "Preparando reach...")
local REACH_STYLES, FLAT_ROTATION, createVisualPart
do
	REACH_STYLES = { "Escudo", "Wireframe", "Anel no chao", "Radar", "Linha", "Completo" }
	local RING_SEGMENTS = 40
	local PATH_SEGMENTS = 120
	local PATH_STEP = 0.03
	local MAX_CONTACTS = 16
	local MAX_HIGHLIGHTS = 6
	local BURST_TIME = 0.45
	FLAT_ROTATION = CFrame.Angles(0, 0, math.rad(90))
	local visualFolder = Instance.new("Folder")
	visualFolder.Name = "TCSHubMiniVisual"
	visualFolder.Parent = workspace.CurrentCamera or workspace
	function createVisualPart(shape, size, material)
		local part = Instance.new("Part")
		part.Shape = shape
		part.Size = size
		part.Material = material
		part.Anchored = true
		part.CanCollide = false
		part.CanQuery = false
		part.CanTouch = false
		part.CastShadow = false
		part.Transparency = 1
		part.Parent = visualFolder
		return part
	end
	local function createSegmentPool(count)
		local pool = {}
		for index = 1, count do
			pool[index] = createVisualPart(Enum.PartType.Cylinder, Vector3.new(0.5, 0.1, 0.1), Enum.Material.Neon)
		end
		return pool
	end
	local reachShield = createVisualPart(Enum.PartType.Ball, Vector3.one, Enum.Material.ForceField)
	local reachDisc = createVisualPart(Enum.PartType.Cylinder, Vector3.new(0.12, 1, 1), Enum.Material.Neon)
	local reachRipple = createVisualPart(Enum.PartType.Cylinder, Vector3.new(0.14, 1, 1), Enum.Material.Neon)
	local reachBurst = createVisualPart(Enum.PartType.Cylinder, Vector3.new(0.16, 1, 1), Enum.Material.Neon)
	local ringSegments = createSegmentPool(RING_SEGMENTS * 3)
	local pathSegments = createSegmentPool(PATH_SEGMENTS)
	local contactSegments = createSegmentPool(MAX_CONTACTS)
	local cubeJoints = {}
	for index = 1, 8 do
		cubeJoints[index] = createVisualPart(Enum.PartType.Ball, Vector3.one, Enum.Material.Neon)
	end
	local cubeSigns = {}
	for sx = -1, 1, 2 do
		for sy = -1, 1, 2 do
			for sz = -1, 1, 2 do
				cubeSigns[#cubeSigns + 1] = Vector3.new(sx, sy, sz)
			end
		end
	end
	local cubeBoxCache = { character = nil, stamp = -10, horizontal = 2, vertical = 3, offset = Vector3.zero }
	local cubeYaw = Vector3.new(0, 0, -1)
	local guideGlow = createVisualPart(Enum.PartType.Cylinder, Vector3.new(1, 0.1, 0.1), Enum.Material.Neon)
	local guideLine = createVisualPart(Enum.PartType.Cylinder, Vector3.new(1, 0.1, 0.1), Enum.Material.Neon)
	local reachSweep = createVisualPart(Enum.PartType.Block, Vector3.new(1, 0.1, 0.25), Enum.Material.Neon)
	local reachSweepTip = createVisualPart(Enum.PartType.Ball, Vector3.one * 0.5, Enum.Material.Neon)
	local sweepTrail = Instance.new("Trail")
	do
		local topAttachment = Instance.new("Attachment")
		topAttachment.Position = Vector3.new(0, 0.35, 0)
		topAttachment.Parent = reachSweepTip
		local bottomAttachment = Instance.new("Attachment")
		bottomAttachment.Position = Vector3.new(0, -0.35, 0)
		bottomAttachment.Parent = reachSweepTip
		sweepTrail.Attachment0 = topAttachment
		sweepTrail.Attachment1 = bottomAttachment
		sweepTrail.Lifetime = 0.7
		sweepTrail.LightEmission = 1
		sweepTrail.FaceCamera = true
		sweepTrail.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.2),
			NumberSequenceKeypoint.new(1, 1),
		})
		sweepTrail.Enabled = false
		sweepTrail.Parent = reachSweepTip
	end
	local reachTicks = {}
	for index = 1, 4 do
		reachTicks[index] = createVisualPart(Enum.PartType.Block, Vector3.new(0.2, 0.3, 1.1), Enum.Material.Neon)
	end
	local reachEntry = createVisualPart(Enum.PartType.Ball, Vector3.one * 0.9, Enum.Material.Neon)
	local function createHighlight()
		local ok, highlight = pcall(function()
			local object = Instance.new("Highlight")
			object.Enabled = false
			object.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
			object.FillTransparency = 0.45
			object.OutlineTransparency = 0.1
			object.Parent = visualFolder
			return object
		end)
		return ok and highlight or nil
	end
	local partHighlights = {}
	for _ = 1, MAX_HIGHLIGHTS do
		local highlight = createHighlight()
		if highlight then table.insert(partHighlights, highlight) end
	end
	local ballHighlight = createHighlight()
	local function createBillboard(width, height)
		local billboard = Instance.new("BillboardGui")
		billboard.Size = UDim2.fromOffset(width, height)
		billboard.AlwaysOnTop = true
		billboard.Enabled = false
		billboard.Parent = visualFolder
		local label = Instance.new("TextLabel")
		label.BackgroundTransparency = 1
		label.Size = UDim2.fromScale(1, 1)
		label.Font = Enum.Font.GothamBold
		label.TextSize = 16
		label.TextColor3 = Color3.new(1, 1, 1)
		label.TextStrokeTransparency = 0.3
		label.Text = ""
		label.Parent = billboard
		return billboard, label
	end
	local distanceBillboard, distanceLabel = createBillboard(200, 24)
	local entryBillboard, entryLabel = createBillboard(90, 22)
	entryBillboard.Adornee = reachEntry
	local panelGui = Instance.new("ScreenGui")
	panelGui.Name = "TCSHubMiniPanel"
	panelGui.ResetOnSpawn = false
	panelGui.DisplayOrder = -1
	panelGui.Enabled = false
	panelGui.Parent = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:WaitForChild("PlayerGui")
	local panelLabel = Instance.new("TextLabel")
	panelLabel.Position = UDim2.fromOffset(20, 110)
	panelLabel.Size = UDim2.fromOffset(260, 112)
	panelLabel.BackgroundColor3 = Color3.fromRGB(14, 16, 26)
	panelLabel.BackgroundTransparency = 0.2
	panelLabel.BorderSizePixel = 0
	panelLabel.Font = Enum.Font.GothamBold
	panelLabel.TextSize = 13
	panelLabel.TextColor3 = Color3.new(1, 1, 1)
	panelLabel.TextXAlignment = Enum.TextXAlignment.Left
	panelLabel.TextYAlignment = Enum.TextYAlignment.Top
	panelLabel.Text = ""
	panelLabel.Parent = panelGui
	local panelCorner = Instance.new("UICorner")
	panelCorner.CornerRadius = UDim.new(0, 8)
	panelCorner.Parent = panelLabel
	local panelStroke = Instance.new("UIStroke")
	panelStroke.Color = ACCENT
	panelStroke.Thickness = 1.2
	panelStroke.Transparency = 0.35
	panelStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	panelStroke.Parent = panelLabel
	local panelPadding = Instance.new("UIPadding")
	panelPadding.PaddingLeft = UDim.new(0, 8)
	panelPadding.PaddingTop = UDim.new(0, 6)
	panelPadding.Parent = panelLabel
	local reachRayCharacter = nil
	local reachRayParams = RaycastParams.new()
	reachRayParams.FilterType = Enum.RaycastFilterType.Exclude
	local reachSmoothColor = config.reachVisualColor
	local reachWasInReach = false
	local reachBurstStart = -10
	local visibleNow = {}
	local visibleBefore = {}
	local function hideObject(object)
		if object:IsA("BasePart") then
			if object.Transparency ~= 1 then object.Transparency = 1 end
		elseif object:IsA("BillboardGui") or object:IsA("Highlight") then
			if object.Enabled then object.Enabled = false end
		end
	end
	local function endFrame()
		for object in pairs(visibleBefore) do
			if not visibleNow[object] then hideObject(object) end
		end
		visibleBefore, visibleNow = visibleNow, visibleBefore
		table.clear(visibleNow)
	end
	local function placeSegment(part, fromPos, toPos, thickness, color, transparency)
		local length = (toPos - fromPos).Magnitude
		if length < 0.02 then return end
		part.Size = Vector3.new(length + 0.02, thickness, thickness)
		part.CFrame = CFrame.lookAt(fromPos:Lerp(toPos, 0.5), toPos) * CFrame.Angles(0, math.rad(90), 0)
		part.Color = color
		part.Transparency = transparency
		visibleNow[part] = true
	end
	local function drawRing3D(startIndex, center, axisA, axisB, radius, color, transparency, thickness, dashPhase)
		local previous = center + axisA * radius
		for segment = 1, RING_SEGMENTS do
			local angle = segment / RING_SEGMENTS * math.pi * 2
			local nextPoint = center + (axisA * math.cos(angle) + axisB * math.sin(angle)) * radius
			if not (dashPhase and (segment + dashPhase) % 2 == 0) then
				placeSegment(ringSegments[startIndex + segment - 1], previous, nextPoint, thickness, color, transparency)
			end
			previous = nextPoint
		end
	end
	local pathPoints = {}
	local function simulatePath(ball, groundY)
		local velocity = ball.AssemblyLinearVelocity
		if velocity.Magnitude < 3 then return 0 end
		local gravity = workspace.Gravity * config.gkGravity
		local floorY = groundY + ball.Size.Y / 2
		local position = ball.Position
		local bounce = config.reachBounce
		local count = 0
		for index = 1, PATH_SEGMENTS do
			velocity = velocity - Vector3.new(0, gravity * PATH_STEP, 0)
			position = position + velocity * PATH_STEP
			if position.Y < floorY then
				position = Vector3.new(position.X, floorY, position.Z)
				if velocity.Y < 0 then
					velocity = Vector3.new(velocity.X * 0.97, -velocity.Y * bounce, velocity.Z * 0.97)
				end
			end
			pathPoints[index] = position
			count = index
			if position.Y <= floorY + 0.05 and velocity.Magnitude < 2 then break end
		end
		return count
	end
	local function findEntry(character, hrp, ball, count)
		local radius = ball.Size.X / 2
		local range = getReachRange()
		for index = 1, count do
			local point = pathPoints[index]
			if (point - hrp.Position).Magnitude - radius - 5 <= range then
				for _, part in ipairs(character:GetChildren()) do
					if part:IsA("BasePart") and surfaceDistance(part, point, radius) <= range then
						return point, index * PATH_STEP
					end
				end
			end
		end
		return nil
	end
	local reachVisualConnection = safeConnect(runService.RenderStepped, "reachVisual", function(dt)
		if scriptDestroyed then return end
		if not config.reachVisualEnabled then
			if next(visibleBefore) ~= nil then
				for object in pairs(visibleBefore) do
					hideObject(object)
				end
				table.clear(visibleBefore)
				sweepTrail.Enabled = false
				panelGui.Enabled = false
			end
			reachWasInReach = false
			return
		end
		local ball = findBall()
		local character = localPlayer.Character
		local hrp = character and character:FindFirstChild("HumanoidRootPart")
		if not (ball and ball.Parent and hrp) then
			reachWasInReach = false
			sweepTrail.Enabled = false
			panelGui.Enabled = false
			endFrame()
			return
		end
		local parts, nearestDistance = getReachParts(character, ball)
		local inReach = #parts > 0
		local now = os.clock()
		if inReach and not reachWasInReach then reachBurstStart = now end
		reachWasInReach = inReach
		local idleColor = config.reachVisualColor
		local targetColor = config.reachInRangeColor
		if not inReach then
			local farness = math.clamp((nearestDistance - getReachRange()) / math.max(getReachRange() * 1.5, 1), 0, 1)
			targetColor = idleColor:Lerp(config.reachInRangeColor, (1 - farness) * 0.6)
		end
		reachSmoothColor = reachSmoothColor:Lerp(targetColor, math.clamp(dt * 12, 0, 1))
		local color = reachSmoothColor
		local style = config.reachVisualStyle
		local thickness = config.reachThickness
		local ballRadius = ball.Size.X / 2
		local radius = getReachRange() + ballRadius
		local center = ball.Position
		local volumeCenter = center
		local playerCentered = config.reachVisualCenter ~= "Bola"
		if playerCentered then volumeCenter = hrp.Position end
		local burstProgress = math.clamp((now - reachBurstStart) / BURST_TIME, 0, 1)
		local bursting = burstProgress < 1
		local dashPhase = (not inReach) and math.floor(now * 5) or nil
		local showShield = style == "Escudo" or style == "Completo"
		local showWire = style == "Wireframe"
		local showRing = style == "Anel no chao" or style == "Completo"
		local showRadar = style == "Radar"
		local showLine = style == "Linha" or style == "Completo"
		local needsPath = config.reachShowPath or config.reachShowEntry
		local needsGround = showRing or showRadar or needsPath
		local groundY = volumeCenter.Y - (playerCentered and 3 or ballRadius)
		if needsGround then
			if reachRayCharacter ~= character then
				reachRayCharacter = character
				reachRayParams.FilterDescendantsInstances = { character }
			end
			local result = workspace:Raycast(volumeCenter, Vector3.new(0, -20, 0), reachRayParams)
			if result then groundY = result.Position.Y + 0.05 end
		end
		if showShield then
			local flash = bursting and (1 - burstProgress) * 0.25 or 0
			reachShield.Size = Vector3.one * radius * 2
			reachShield.CFrame = CFrame.new(volumeCenter)
			reachShield.Color = color
			reachShield.Transparency = math.clamp(0.55 + math.sin(now * 3) * 0.05 - flash, 0, 1)
			visibleNow[reachShield] = true
		end
		if showWire then
			local transparency = inReach and 0.05 or 0.2
			local edge = thickness * 2
			local halfX, halfY, halfZ, cubeCenter = radius, radius, radius, center
			local lookVector = Vector3.new(0, 0, -1)
			if hrp then
				local flat = Vector3.new(hrp.CFrame.LookVector.X, 0, hrp.CFrame.LookVector.Z)
				if flat.Magnitude > 0.01 then cubeYaw = flat.Unit end
			end
			lookVector = cubeYaw
			if config.reachCubeCenter ~= "Bola" and hrp then
				if cubeBoxCache.character ~= character or now - cubeBoxCache.stamp > 1 then
					cubeBoxCache.character = character
					cubeBoxCache.stamp = now
					if hrp.CFrame.UpVector.Y > 0.9 then
						local ok, boxCFrame, boxSize = pcall(character.GetBoundingBox, character)
						if ok and boxSize then
							cubeBoxCache.horizontal = math.max(boxSize.X, boxSize.Z) / 2
							cubeBoxCache.vertical = boxSize.Y / 2
							cubeBoxCache.offset = boxCFrame.Position - hrp.Position
						end
					end
				end
				halfX = cubeBoxCache.horizontal + radius
				halfZ = halfX
				halfY = cubeBoxCache.vertical + radius
				cubeCenter = hrp.Position + cubeBoxCache.offset
			end
			local basis = CFrame.lookAt(cubeCenter, cubeCenter + lookVector)
			local corners = table.create(8)
			for index = 1, 8 do
				local sign = cubeSigns[index]
				corners[index] = (basis * CFrame.new(sign.X * halfX, sign.Y * halfY, sign.Z * halfZ)).Position
				local joint = cubeJoints[index]
				joint.Size = Vector3.one * edge
				joint.CFrame = CFrame.new(corners[index])
				joint.Color = color
				joint.Transparency = transparency
				visibleNow[joint] = true
			end
			local edgeIndex = 0
			for a = 1, 7 do
				for b = a + 1, 8 do
					local diff = cubeSigns[a] - cubeSigns[b]
					local axes = (diff.X ~= 0 and 1 or 0) + (diff.Y ~= 0 and 1 or 0) + (diff.Z ~= 0 and 1 or 0)
					if axes == 1 then
						edgeIndex += 1
						placeSegment(ringSegments[edgeIndex], corners[a], corners[b], edge, color, transparency)
					end
				end
			end
		end
		if showRing or showRadar then
			local groundCenter = Vector3.new(volumeCenter.X, groundY + 0.06, volumeCenter.Z)
			reachDisc.Size = Vector3.new(0.12, radius * 2, radius * 2)
			reachDisc.CFrame = CFrame.new(volumeCenter.X, groundY, volumeCenter.Z) * FLAT_ROTATION
			reachDisc.Color = color
			reachDisc.Transparency = showRadar and 0.88 or (inReach and 0.7 or 0.85)
			visibleNow[reachDisc] = true
			drawRing3D(1, groundCenter, Vector3.xAxis, Vector3.zAxis, radius, color, inReach and 0 or 0.15, thickness, dashPhase)
			if bursting then
				local burstSize = radius * 2 * (0.5 + 0.9 * burstProgress)
				reachBurst.Size = Vector3.new(0.16, burstSize, burstSize)
				reachBurst.CFrame = CFrame.new(volumeCenter.X, groundY + 0.03, volumeCenter.Z) * FLAT_ROTATION
				reachBurst.Color = color
				reachBurst.Transparency = 0.2 + 0.8 * burstProgress
				visibleNow[reachBurst] = true
			end
			if showRing then
				local pulse = (now * 0.8) % 1
				local rippleSize = radius * 2 * (0.15 + 0.85 * pulse)
				reachRipple.Size = Vector3.new(0.14, rippleSize, rippleSize)
				reachRipple.CFrame = CFrame.new(volumeCenter.X, groundY + 0.02, volumeCenter.Z) * FLAT_ROTATION
				reachRipple.Color = color
				reachRipple.Transparency = 0.4 + 0.6 * pulse
				visibleNow[reachRipple] = true
			end
			if showRadar then
				drawRing3D(1 + RING_SEGMENTS, groundCenter, Vector3.xAxis, Vector3.zAxis, radius * 0.66, color, 0.45, thickness * 0.7)
				drawRing3D(1 + RING_SEGMENTS * 2, groundCenter, Vector3.xAxis, Vector3.zAxis, radius * 0.33, color, 0.55, thickness * 0.7)
				local angle = now * 2.6
				local direction = Vector3.new(math.cos(angle), 0, math.sin(angle))
				local barCenter = groundCenter + direction * (radius / 2)
				reachSweep.Size = Vector3.new(radius, 0.1, 0.25)
				reachSweep.CFrame = CFrame.lookAt(barCenter, barCenter + direction) * CFrame.Angles(0, math.rad(90), 0)
				reachSweep.Color = color
				reachSweep.Transparency = 0.2
				visibleNow[reachSweep] = true
				reachSweepTip.CFrame = CFrame.new(groundCenter + direction * radius)
				reachSweepTip.Color = color
				reachSweepTip.Transparency = 0
				visibleNow[reachSweepTip] = true
				sweepTrail.Color = ColorSequence.new(color)
				for index, tickPart in ipairs(reachTicks) do
					local tickAngle = (index - 1) * math.pi / 2
					local tickDirection = Vector3.new(math.cos(tickAngle), 0, math.sin(tickAngle))
					tickPart.CFrame = CFrame.lookAt(groundCenter + tickDirection * radius, groundCenter + tickDirection * (radius + 1))
					tickPart.Color = color
					tickPart.Transparency = 0.1
					visibleNow[tickPart] = true
				end
			end
		end
		local wantsTrail = showRadar
		if sweepTrail.Enabled ~= wantsTrail then sweepTrail.Enabled = wantsTrail end
		if config.reachShowContacts then
			for index, part in ipairs(parts) do
				if index > MAX_CONTACTS then break end
				placeSegment(contactSegments[index], part.Position, center, thickness * 0.5, color, 0.35)
			end
		end
		if config.reachHighlight then
			for index, highlight in ipairs(partHighlights) do
				local part = parts[index]
				if part then
					highlight.Adornee = part
					highlight.FillColor = color
					highlight.OutlineColor = color
					highlight.Enabled = true
					visibleNow[highlight] = true
				end
			end
			if ballHighlight and inReach then
				ballHighlight.Adornee = ball
				ballHighlight.FillColor = color
				ballHighlight.OutlineColor = color
				ballHighlight.Enabled = true
				visibleNow[ballHighlight] = true
			end
		end
		local entryTime = nil
		if needsPath then
			local pointCount = simulatePath(ball, groundY)
			if config.reachShowPath and pointCount > 0 then
				local previous = center
				for index = 1, pointCount do
					local point = pathPoints[index]
					local fade = index / pointCount
					placeSegment(pathSegments[index], previous, point, thickness * (1 - 0.5 * fade), color, 0.1 + 0.75 * fade)
					previous = point
				end
			end
			if config.reachShowEntry and not inReach and pointCount > 0 then
				local entryPoint, time = findEntry(character, hrp, ball, pointCount)
				if entryPoint then
					entryTime = time
					reachEntry.CFrame = CFrame.new(entryPoint)
					reachEntry.Color = config.reachInRangeColor
					reachEntry.Transparency = 0.15 + math.sin(now * 8) * 0.1
					visibleNow[reachEntry] = true
					entryLabel.Text = string.format("%.2fs", time)
					entryLabel.TextColor3 = config.reachInRangeColor
					entryBillboard.StudsOffset = Vector3.new(0, 1.2, 0)
					entryBillboard.Enabled = true
					visibleNow[entryBillboard] = true
				end
			end
		end
		if showLine then
			placeSegment(guideGlow, hrp.Position, center, thickness * 3, color:Lerp(Color3.new(0, 0, 0), 0.6), 0.6)
			placeSegment(guideLine, hrp.Position, center, thickness, color, 0.1)
		end
		local distance = (hrp.Position - center).Magnitude
		if config.reachShowDistance then
			distanceLabel.Text = string.format("%.1f", distance) .. (inReach and ("  NO ALCANCE x" .. #parts) or "")
			distanceLabel.TextColor3 = color
			distanceBillboard.Adornee = ball
			distanceBillboard.StudsOffset = Vector3.new(0, ballRadius + 1.5, 0)
			distanceBillboard.Enabled = true
			visibleNow[distanceBillboard] = true
		end
		local showPanel = config.reachShowPanel
		if panelGui.Enabled ~= showPanel then panelGui.Enabled = showPanel end
		if showPanel then
			local touchCount, lastTouch = getReachStats()
			local touchText = touchCount == 0 and "nenhum" or string.format("%d (ha %.1fs)", touchCount, tick() - lastTouch)
			panelLabel.TextColor3 = color
			panelLabel.Text = table.concat({
				"REACH  " .. config.reachMode .. "  [" .. config.reachMethod .. "]",
				string.format("Dist %.1f   Partes %d", distance, #parts),
				string.format("Bola %.0f studs/s", ball.AssemblyLinearVelocity.Magnitude),
				inReach and "DENTRO DO ALCANCE"
					or (entryTime and string.format("Entra no alcance em %.2fs", entryTime) or "Fora do alcance"),
				"Toques enviados: " .. touchText,
				(function()
					local samples, maxHit = getReachCalibration()
					if samples == 0 then return "Servidor: aprendendo..." end
					return string.format("Servidor aceitou ate %.1f studs (%d)", maxHit, samples)
				end)(),
			}, "\n")
		end
		endFrame()
	end)
	registerCleanup(function()
		reachVisualConnection:Disconnect()
		visualFolder:Destroy()
		panelGui:Destroy()
	end)
end
local espFolder = Instance.new("Folder")
espFolder.Name = "TCSHubMiniESP"
espFolder.Parent = workspace.CurrentCamera or workspace
local espHighlight = nil
pcall(function()
	local highlight = Instance.new("Highlight")
	highlight.Enabled = false
	highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
	highlight.FillTransparency = 0.75
	highlight.OutlineTransparency = 0
	highlight.Parent = espFolder
	espHighlight = highlight
end)
local espBillboard = Instance.new("BillboardGui")
espBillboard.Size = UDim2.fromOffset(150, 24)
espBillboard.AlwaysOnTop = true
espBillboard.Enabled = false
espBillboard.Parent = espFolder
local espLabel = Instance.new("TextLabel")
espLabel.BackgroundTransparency = 1
espLabel.Size = UDim2.fromScale(1, 1)
espLabel.Font = Enum.Font.GothamBold
espLabel.TextSize = 15
espLabel.TextStrokeTransparency = 0.3
espLabel.Text = ""
espLabel.Parent = espBillboard
local function createTracerPoint()
	local part = Instance.new("Part")
	part.Anchored = true
	part.CanCollide = false
	part.CanQuery = false
	part.CanTouch = false
	part.CastShadow = false
	part.Transparency = 1
	part.Size = Vector3.new(0.2, 0.2, 0.2)
	part.Parent = espFolder
	local attachment = Instance.new("Attachment")
	attachment.Parent = part
	return part, attachment
end
local tracerStart, tracerStartAttachment = createTracerPoint()
local tracerEnd, tracerEndAttachment = createTracerPoint()
local espBeam = Instance.new("Beam")
espBeam.Attachment0 = tracerStartAttachment
espBeam.Attachment1 = tracerEndAttachment
espBeam.Width0 = 0.12
espBeam.Width1 = 0.12
espBeam.LightEmission = 1
espBeam.FaceCamera = true
espBeam.Segments = 1
