local espVisible = false
local lastEspText = 0
local function hideBallEsp()
	if espHighlight and espHighlight.Enabled then espHighlight.Enabled = false end
	espBillboard.Enabled = false
	espBeam.Enabled = false
	espVisible = false
end
local ballEspConnection = safeConnect(runService.RenderStepped, "ballEsp", function()
	if scriptDestroyed then return end
	if not config.ballEspEnabled then
		if espVisible then hideBallEsp() end
		return
	end
	local ball = findBall()
	if not ball then
		if espVisible then hideBallEsp() end
		return
	end
	espVisible = true
	local color = config.ballEspColor
	local character = localPlayer.Character
	local hrp = character and character:FindFirstChild("HumanoidRootPart")
	if espHighlight then
		espHighlight.Adornee = ball
		espHighlight.FillColor = color
		espHighlight.OutlineColor = color
		espHighlight.Enabled = true
	end
	if config.ballEspLabel then
		espBillboard.Adornee = ball
		espBillboard.StudsOffset = Vector3.new(0, ball.Size.Y / 2 + 1.5, 0)
		espBillboard.Enabled = true
		espLabel.TextColor3 = color
		local now = os.clock()
		if now - lastEspText > 0.1 then
			lastEspText = now
			local distance = hrp and (hrp.Position - ball.Position).Magnitude or 0
			espLabel.Text = string.format("BOLA %.0f", distance)
		end
	else
		espBillboard.Enabled = false
	end
	if config.ballEspTracer and hrp then
		tracerStart.CFrame = hrp.CFrame
		tracerEnd.CFrame = ball.CFrame
		espBeam.Color = ColorSequence.new(color)
		espBeam.Enabled = true
	else
		espBeam.Enabled = false
	end
end)
registerCleanup(function()
	ballEspConnection:Disconnect()
	espFolder:Destroy()
end)
local GOAL_NAME_HINTS = { "goal", "gol", "trave", "arco" }
local GOAL_SKIP_NAME_HINTS = { "gold", "golf", "golem", "magnet", "arcade", "search", "marco", "parco" }
local lastGoalRefresh = 0
local cachedGoals = {}
local function looksLikeGoal(instance)
	if not instance:IsA("BasePart") and not instance:IsA("Model") then return false end
	local name = instance.Name:lower()
	for _, skip in ipairs(GOAL_SKIP_NAME_HINTS) do
		if name:find(skip, 1, true) then return false end
	end
	for _, hint in ipairs(GOAL_NAME_HINTS) do
		if name:find(hint, 1, true) then return true end
	end
	return false
end
local function refreshGoals()
	lastGoalRefresh = os.clock()
	table.clear(cachedGoals)
	for _, descendant in ipairs(workspace:GetDescendants()) do
		if looksLikeGoal(descendant) then
			table.insert(cachedGoals, descendant)
		end
	end
end
local function getGoalPosition(instance)
	if instance:IsA("BasePart") then return instance.Position end
	if instance:IsA("Model") then
		local ok, cframe = pcall(function() return instance:GetPivot() end)
		if ok then return cframe.Position end
	end
	return nil
end
local function getEnemyGoal()
	if #cachedGoals == 0 or os.clock() - lastGoalRefresh > 30 then refreshGoals() end
	if #cachedGoals == 0 then return nil end
	local character = localPlayer.Character
	local hrp = character and character:FindFirstChild("HumanoidRootPart")
	if not hrp then return cachedGoals[1] end
	local best, bestDist = nil, -1
	for _, goal in ipairs(cachedGoals) do
		local pos = getGoalPosition(goal)
		if pos then
			local dist = (pos - hrp.Position).Magnitude
			if dist > bestDist then
				best = goal
				bestDist = dist
			end
		end
	end
	return best
end
