local function makeDraggable(guiObject)
	local dragging, dragInput, startPointer, startPosition = false, nil, nil, nil
	local state = { moved = false }
	guiObject.InputBegan:Connect(function(input)
		if input.UserInputType ~= Enum.UserInputType.MouseButton1
			and input.UserInputType ~= Enum.UserInputType.Touch then
			return
		end
		dragging = true
		dragInput = input
		startPointer = input.Position
		startPosition = guiObject.Position
		state.moved = false
	end)
	local changedConnection = userInputService.InputChanged:Connect(function(input)
		if not dragging then return end
		if input.UserInputType ~= Enum.UserInputType.MouseMovement and input ~= dragInput then return end
		local delta = input.Position - startPointer
		if delta.Magnitude > 8 then state.moved = true end
		if not state.moved then return end
		guiObject.Position = UDim2.new(
			startPosition.X.Scale, startPosition.X.Offset + delta.X,
			startPosition.Y.Scale, startPosition.Y.Offset + delta.Y
		)
	end)
	local endedConnection = userInputService.InputEnded:Connect(function(input)
		if input == dragInput or input.UserInputType == Enum.UserInputType.MouseButton1 then
			dragging = false
		end
	end)
	registerCleanup(function()
		changedConnection:Disconnect()
		endedConnection:Disconnect()
	end)
	return state
end
