local followControls = nil
local function getControls()
	if followControls then return followControls end
	local playerScripts = localPlayer:FindFirstChild("PlayerScripts")
	local playerModule = playerScripts and playerScripts:FindFirstChild("PlayerModule")
	if not playerModule then return nil end
	if setthreadidentity then pcall(setthreadidentity, 2) end
	local ok, controls = pcall(function()
		return require(playerModule):GetControls()
	end)
	if setthreadidentity then pcall(setthreadidentity, 8) end
	if ok then followControls = controls end
	return followControls
end
local function hasManualInput(humanoid)
	local controls = getControls()
	if controls then
		local ok, moveVector = pcall(function() return controls:GetMoveVector() end)
		if ok and moveVector then
			return moveVector.Magnitude > 0.05
		end
	end
	if humanoid.MoveDirection.Magnitude > 0.15 then return true end
	return userInputService:IsKeyDown(Enum.KeyCode.W)
		or userInputService:IsKeyDown(Enum.KeyCode.A)
		or userInputService:IsKeyDown(Enum.KeyCode.S)
		or userInputService:IsKeyDown(Enum.KeyCode.D)
end
local followResumeAt = 0
local followConnection = safeConnect(runService.RenderStepped, "followConnection", function()
	if scriptDestroyed or not config.goToBallEnabled then return end
	local character = localPlayer.Character
	local humanoid = character and character:FindFirstChild("Humanoid")
	local hrp = character and character:FindFirstChild("HumanoidRootPart")
	if not (humanoid and hrp) then return end
	local nowClock = os.clock()
	if hasManualInput(humanoid) then
		followResumeAt = nowClock + 0.35
		return
	end
	if nowClock < followResumeAt then return end
	local ball = findBall()
	if not ball then return end
	local ballPosition = ball.Position
	local offset = ballPosition - hrp.Position
	local flatOffset = Vector3.new(offset.X, 0, offset.Z)
	if flatOffset.Magnitude > config.followStopDistance and flatOffset.Magnitude < 400 then
		humanoid:Move(flatOffset.Unit, false)
		hrp.CFrame = CFrame.lookAt(hrp.Position, Vector3.new(ballPosition.X, hrp.Position.Y, ballPosition.Z))
	else
		humanoid:Move(Vector3.zero, false)
	end
end)
registerCleanup(function() followConnection:Disconnect() end)
local KICK_TYPE_NAMES, KICK_TARGET_NAMES, applyAutoKick
do
	local KICK_TYPES = {
		["Chute"] = { "chute", "shoot" },
		["Passe"] = { "passe", "pass" },
		["Longo"] = { "longo", "long" },
	}
	KICK_TYPE_NAMES = { "Chute", "Passe", "Longo" }
	KICK_TARGET_NAMES = { "Automatico", "Gol Azul", "Gol Verde" }
	local KICK_GOALS = {
		["Gol Azul"] = Vector3.new(-32.18, -28.94, -203.58),
		["Gol Verde"] = Vector3.new(-19, -28.94, 386.3),
	}
	local CLICK_SIGNALS = { "MouseButton1Down", "Activated", "MouseButton1Click", "TouchTap", "MouseButton1Up" }
	local KICK_TURN_THRESHOLD = math.rad(8)
	local KICK_RESCAN_TIME = 15
	local kickGuiService = game:GetService("GuiService")
	local kickInputManager = game:GetService("VirtualInputManager")
	local kickButtons = {}
	local kickScanning = false
	local lastKickScan = 0
	local lastKick = 0
	local kickBusy = false
	local autoKickConnection = nil
	local function scanKickButtons()
		if kickScanning then return end
		kickScanning = true
		lastKickScan = tick()
		local ok, err = pcall(function()
			local found = {}
			for index, descendant in ipairs(playerGui:GetDescendants()) do
				if descendant.Parent
					and (descendant:IsA("TextButton") or descendant:IsA("TextLabel"))
					and not descendant:IsDescendantOf(hubGui) then
					local text = descendant.Text:lower():match("^%s*(.-)%s*$")
					for typeName, aliases in pairs(KICK_TYPES) do
						if table.find(aliases, text) then
							local button = descendant:IsA("GuiButton") and descendant or descendant:FindFirstAncestorWhichIsA("GuiButton")
							if button then found[typeName] = button end
						end
					end
				end
				if index % 150 == 0 then task.wait() end
			end
			kickButtons = found
		end)
		kickScanning = false
		if not ok then
			warn("Zenith: erro ao escanear botoes de chute -> " .. tostring(err))
		end
	end
	local function hasClickConnections(button)
		for _, signalName in ipairs(CLICK_SIGNALS) do
			local ok, connections = pcall(getconnections, button[signalName])
			if ok and #connections > 0 then return true end
		end
		return false
	end
	local function fireSignals(button, signalNames)
		for _, signalName in ipairs(signalNames) do
			pcall(function() firesignal(button[signalName]) end)
		end
	end
	local function pressAndHold(button, holdTime)
		if hasClickConnections(button) then
			fireSignals(button, { "MouseButton1Down" })
			task.wait(holdTime)
			fireSignals(button, { "MouseButton1Up", "Activated", "MouseButton1Click", "TouchTap" })
			return
		end
		pcall(function()
			local inset = kickGuiService:GetGuiInset()
			local center = button.AbsolutePosition + button.AbsoluteSize / 2 + inset
			kickInputManager:SendMouseButtonEvent(center.X, center.Y, 0, true, game, 0)
			task.wait(holdTime)
			kickInputManager:SendMouseButtonEvent(center.X, center.Y, 0, false, game, 0)
		end)
	end
	local function flatDirection(fromPosition, toPosition)
		local delta = toPosition - fromPosition
		return Vector3.new(delta.X, 0, delta.Z)
	end
	local function nearKnownGoals(hrp)
		for _, position in pairs(KICK_GOALS) do
			if (position - hrp.Position).Magnitude < 450 then return true end
		end
		return false
	end
	local function resolveGoalPosition(hrp)
		if workspace:FindFirstChild("WorkspaceStadiumMap1") and nearKnownGoals(hrp) then
			local chosen = KICK_GOALS[config.kickTarget]
			if chosen then return chosen end
			local look = hrp.CFrame.LookVector
			local lookFlat = Vector3.new(look.X, 0, look.Z)
			local best, bestScore = nil, -2
			local farthest, farthestDistance = nil, -1
			for _, position in pairs(KICK_GOALS) do
				local toGoal = flatDirection(hrp.Position, position)
				if toGoal.Magnitude > 1 and lookFlat.Magnitude > 0.1 then
					local score = lookFlat.Unit:Dot(toGoal.Unit)
					if score > bestScore then
						best, bestScore = position, score
					end
				end
				if toGoal.Magnitude > farthestDistance then
					farthest, farthestDistance = position, toGoal.Magnitude
				end
			end
			if best and bestScore > 0.2 then return best end
			return farthest
		end
		local goal = getEnemyGoal()
		return goal and getGoalPosition(goal)
	end
	local function aimAtGoal(hrp)
		local goalPosition = resolveGoalPosition(hrp)
		if not goalPosition then return end
		local direction = flatDirection(hrp.Position, goalPosition)
		local look = hrp.CFrame.LookVector
		local lookFlat = Vector3.new(look.X, 0, look.Z)
		if direction.Magnitude < 1 or lookFlat.Magnitude < 0.01 then return end
		local angle = math.acos(math.clamp(lookFlat.Unit:Dot(direction.Unit), -1, 1))
		if angle < KICK_TURN_THRESHOLD then return end
		hrp.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + direction)
	end
	local function performKick(ball)
		kickBusy = true
		pcall(function()
			local character = localPlayer.Character
			local hrp = character and character:FindFirstChild("HumanoidRootPart")
			if not hrp then return end
			if config.aimGoalEnabled then
				aimAtGoal(hrp)
				task.wait()
			end
			local button = kickButtons[config.kickType]
			if button and button.Parent then
				pressAndHold(button, config.kickHoldTime)
			else
				firetouchinterest(hrp, ball, 0)
				firetouchinterest(hrp, ball, 1)
			end
		end)
		kickBusy = false
	end
	function applyAutoKick(state)
		if autoKickConnection then
			autoKickConnection:Disconnect()
			autoKickConnection = nil
		end
		if not state then return end
		task.spawn(scanKickButtons)
		autoKickConnection = safeConnect(runService.Heartbeat, "autoKickConnection", function()
			if scriptDestroyed or kickBusy then return end
			local character = localPlayer.Character
			local hrp = character and character:FindFirstChild("HumanoidRootPart")
			if not hrp then return end
			local ball = findBall()
			if not ball then return end
			if (hrp.Position - ball.Position).Magnitude > config.autoKickRange then return end
			local now = tick()
			if now - lastKick < config.kickCooldown then return end
			if not kickScanning and now - lastKickScan > KICK_RESCAN_TIME then
				task.spawn(scanKickButtons)
			end
			lastKick = now
			task.spawn(performKick, ball)
		end)
	end
	registerCleanup(function()
		if autoKickConnection then autoKickConnection:Disconnect() end
	end)
	local assistConnection = nil
	local assistState = {
		history = {}, lastKickAt = 0, lastBall = nil, lockUntil = 0, lockDir = nil,
		lastDebug = 0, windowUntil = 0, faceUntil = 0, logged = {},
	}
	local assistButtonConnections = {}
	local assistInputConnection = nil
	local MOVE_KEYS = {
		[Enum.KeyCode.W] = true, [Enum.KeyCode.A] = true, [Enum.KeyCode.S] = true, [Enum.KeyCode.D] = true,
		[Enum.KeyCode.Up] = true, [Enum.KeyCode.Down] = true, [Enum.KeyCode.Left] = true, [Enum.KeyCode.Right] = true,
		[Enum.KeyCode.Space] = true, [Enum.KeyCode.Thumbstick1] = true, [Enum.KeyCode.Unknown] = true,
	}
	local assistHooked = false
	local KICK_REMOTE_HINTS = { "kick", "shoot", "chut", "pass", "ball", "power", "strike", "hit" }
	local function goalDirection(hrp, fromPosition)
		local goal = resolveGoalPosition(hrp)
		if not goal then return nil end
		local delta = Vector3.new(goal.X - fromPosition.X, 0, goal.Z - fromPosition.Z)
		if delta.Magnitude < 1 then return nil end
		return delta.Unit, goal
	end
	local function rewriteKickArgs(remote, args)
		local character = localPlayer.Character
		local hrp = character and character:FindFirstChild("HumanoidRootPart")
		if not hrp then return false end
		local now = tick()
		local nameLower = remote.Name:lower()
		local hinted = false
		for _, hint in ipairs(KICK_REMOTE_HINTS) do
			if nameLower:find(hint, 1, true) then hinted = true break end
		end
		local ball = findBall()
		local near = ball and (ball.Position - hrp.Position).Magnitude <= 22
		if not (now < assistState.windowUntil or (hinted and near)) then return false end
		local direction, goal = goalDirection(hrp, ball and ball.Position or hrp.Position)
		if not direction then return false end
		local strength = math.clamp(config.silentAimStrength or 1, 0, 1)
		local changed = false
		local types = {}
		for index = 1, args.n do
			local value = args[index]
			local kind = typeof(value)
			types[#types + 1] = kind
			if kind == "Vector3" and value.Magnitude > 0.8 and value.Magnitude < 1.25 then
				local flat = Vector3.new(value.X, 0, value.Z)
				local base = flat.Magnitude > 0.01 and flat.Unit or direction
				local mixed = base:Lerp(direction, strength)
				if mixed.Magnitude > 0.01 then
					mixed = mixed.Unit
					local horizontal = math.sqrt(math.max(0, 1 - value.Y * value.Y))
					args[index] = Vector3.new(mixed.X * horizontal, value.Y, mixed.Z * horizontal)
					changed = true
				end
			elseif kind == "CFrame" and (value.Position - hrp.Position).Magnitude < 40 then
				args[index] = CFrame.lookAt(value.Position, value.Position + direction)
				changed = true
			end
		end
		if not assistState.logged[remote.Name] then
			assistState.logged[remote.Name] = true
			warn("[SilentAim] remote:", remote.Name, "| args:", table.concat(types, ","), "| alterado:", tostring(changed))
		end
		return changed
	end
	local function installAssistHook()
		if assistHooked then return end
		assistHooked = true
		local original
		original = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
			local method = getnamecallmethod()
			if (method == "FireServer" or method == "InvokeServer")
				and config.silentAimEnabled and not checkcaller() then
				local args = table.pack(...)
				local ok, changed = pcall(rewriteKickArgs, self, args)
				setnamecallmethod(method)
				if ok and changed then
					return original(self, table.unpack(args, 1, args.n))
				end
			end
			return original(self, ...)
		end))
	end
	local function hookAssistButtons()
		for _, connection in ipairs(assistButtonConnections) do connection:Disconnect() end
		table.clear(assistButtonConnections)
		scanKickButtons()
		for _, button in pairs(kickButtons) do
			table.insert(assistButtonConnections, button.InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.Touch
					or input.UserInputType == Enum.UserInputType.MouseButton1 then
					local now = tick()
					assistState.windowUntil = now + 1
					assistState.faceUntil = now + 0.45
					assistState.heldButton = button
					assistState.heldReleased = false
				end
			end))
			table.insert(assistButtonConnections, button.InputEnded:Connect(function()
				local now = tick()
				assistState.heldButton = nil
				assistState.windowUntil = now + 0.6
				assistState.faceUntil = now + 0.35
				assistState.pendingUntil = now + 0.8
			end))
		end
	end
	local angleBar = nil
	local function ensureAngleBar()
		if angleBar and angleBar.frame.Parent then return angleBar end
		local frame = Instance.new("Frame")
		frame.Name = "PerfectAngleBar"
		frame.AnchorPoint = Vector2.new(0, 0.5)
		frame.Position = UDim2.new(0, 16, 0.8, 0)
		frame.Size = UDim2.fromOffset(22, 190)
		frame.BackgroundColor3 = Color3.fromRGB(14, 16, 26)
		frame.BackgroundTransparency = 0.15
		frame.BorderSizePixel = 0
		frame.Visible = false
		frame.Parent = hubGui
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(0, 8)
		corner.Parent = frame
		local stroke = Instance.new("UIStroke")
		stroke.Color = ACCENT
		stroke.Thickness = 1.5
		stroke.Parent = frame
		local zone = Instance.new("Frame")
		zone.Name = "Zone"
		zone.AnchorPoint = Vector2.new(0.5, 0)
		zone.Position = UDim2.new(0.5, 0, 0.1, 0)
		zone.Size = UDim2.new(1, -6, 0.16, 0)
		zone.BackgroundColor3 = Color3.fromRGB(70, 255, 140)
		zone.BackgroundTransparency = 0.35
		zone.BorderSizePixel = 0
		zone.Parent = frame
		local zoneCorner = Instance.new("UICorner")
		zoneCorner.CornerRadius = UDim.new(0, 5)
		zoneCorner.Parent = zone
		local marker = Instance.new("Frame")
		marker.Name = "Marker"
		marker.AnchorPoint = Vector2.new(0.5, 0.5)
		marker.Size = UDim2.new(1, 8, 0, 4)
		marker.Position = UDim2.new(0.5, 0, 0.9, 0)
		marker.BackgroundColor3 = Color3.new(1, 1, 1)
		marker.BorderSizePixel = 0
		marker.Parent = frame
		local label = Instance.new("TextLabel")
		label.AnchorPoint = Vector2.new(0, 0.5)
		label.Position = UDim2.new(1, 8, 0.5, 0)
		label.Size = UDim2.fromOffset(110, 20)
		label.BackgroundTransparency = 1
		label.Font = Enum.Font.GothamBold
		label.TextSize = 12
		label.TextColor3 = Color3.fromRGB(70, 255, 140)
		label.TextTransparency = 1
		label.TextXAlignment = Enum.TextXAlignment.Left
		label.Text = "PERFECT ANGLE"
		label.Parent = frame
		angleBar = { frame = frame, zone = zone, marker = marker, label = label, flashUntil = 0 }
		return angleBar
	end
	local function updateAngleBar(now)
		if not config.perfectAngleEnabled then
			if angleBar and angleBar.frame.Parent then angleBar.frame.Visible = false end
			return
		end
		local bar = ensureAngleBar()
		bar.frame.Visible = true
		local height = math.clamp((config.perfectAngleTarget or 80) / 100, 0, 1)
		bar.zone.Position = UDim2.new(0.5, 0, math.clamp(1 - height - 0.08, 0, 0.84), 0)
		if now < bar.flashUntil then
			bar.marker.Position = UDim2.new(0.5, 0, bar.zone.Position.Y.Scale + 0.08, 0)
			bar.label.TextTransparency = 0
		else
			local live = assistState.heldButton and assistState.barFraction
			if live then
				bar.marker.Position = UDim2.new(0.5, 0, 0.95 - live * 0.9, 0)
			else
				local wave = (math.sin(now * 3.2) + 1) / 2
				bar.marker.Position = UDim2.new(0.5, 0, 0.05 + wave * 0.9, 0)
			end
			bar.label.TextTransparency = 1
		end
	end
	local lastAngleSide = 1
	local function pickAngleSide(goal, lateral)
		local choice = config.perfectAngleSide
		if choice == "Esquerdo" then return -1 end
		if choice == "Direito" then return 1 end
		local nearestSide, nearestDistance = nil, 45
		for _, player in ipairs(players:GetPlayers()) do
			if player ~= localPlayer then
				local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
				if root then
					local away = root.Position - goal
					local flatDistance = Vector3.new(away.X, 0, away.Z).Magnitude
					if flatDistance < nearestDistance then
						nearestDistance = flatDistance
						nearestSide = away:Dot(lateral) >= 0 and -1 or 1
					end
				end
			end
		end
		if nearestSide then return nearestSide end
		lastAngleSide = -lastAngleSide
		return lastAngleSide
	end
	local gameBar = { bar = nil, fill = nil, lastScan = 0 }
	local function scanGameBar(hrp)
		gameBar.lastScan = tick()
		local camera = workspace.CurrentCamera
		if not camera then return end
		local screen, onScreen = camera:WorldToViewportPoint(hrp.Position)
		if not onScreen then return end
		local inset = kickGuiService:GetGuiInset()
		local best, bestDistance = nil, 380
		for _, object in ipairs(playerGui:GetDescendants()) do
			if object:IsA("GuiObject") and object.Visible and not object:IsDescendantOf(hubGui) then
				local size = object.AbsoluteSize
				if size.X <= 40 and size.Y >= 70 and size.Y >= size.X * 3 then
					local center = object.AbsolutePosition + size / 2 + inset
					local distanceToPlayer = (Vector2.new(screen.X, screen.Y) - center).Magnitude
					if distanceToPlayer < bestDistance then
						best, bestDistance = object, distanceToPlayer
					end
				end
			end
		end
		gameBar.bar, gameBar.fill = best, nil
		if not best then return end
		local fillHeight = -1
		for _, child in ipairs(best:GetDescendants()) do
			if child:IsA("GuiObject") and child.AbsoluteSize.Y <= best.AbsoluteSize.Y + 1 and child.AbsoluteSize.Y > fillHeight then
				gameBar.fill, fillHeight = child, child.AbsoluteSize.Y
			end
		end
	end
	local function readGameBar(hrp)
		local bar = gameBar.bar
		if not (bar and bar.Parent and bar.Visible) then
			if tick() - gameBar.lastScan > 1.5 then scanGameBar(hrp) end
			bar = gameBar.bar
			if not bar then return nil end
		end
		local fill = gameBar.fill
		if not (fill and fill.Parent) then return nil end
		local total = bar.AbsoluteSize.Y
		if total <= 0 then return nil end
		return math.clamp(fill.AbsoluteSize.Y / total, 0, 1)
	end
	local function angleBarTick(hrp, now)
		if not config.perfectAngleEnabled then return end
		local button = assistState.heldButton
		if not button or assistState.heldReleased then return end
		local fraction = readGameBar(hrp)
		assistState.barFraction = fraction
		if not fraction then return end
		if fraction * 100 < (config.perfectAngleTarget or 80) then return end
		assistState.heldReleased = true
		assistState.pendingUntil = now + 0.8
		assistState.windowUntil = now + 1
		if hasClickConnections(button) then
			fireSignals(button, { "MouseButton1Up", "Activated", "MouseButton1Click", "TouchTap" })
		else
			pcall(function()
				local inset = kickGuiService:GetGuiInset()
				local center = button.AbsolutePosition + button.AbsoluteSize / 2 + inset
				kickInputManager:SendMouseButtonEvent(center.X, center.Y, 0, false, game, 0)
			end)
		end
	end
	function applyBallAssist()
		if assistConnection then
			assistConnection:Disconnect()
			assistConnection = nil
		end
		table.clear(assistState.history)
		assistState.lockUntil = 0
		for _, connection in ipairs(assistButtonConnections) do connection:Disconnect() end
		table.clear(assistButtonConnections)
		if assistInputConnection then
			assistInputConnection:Disconnect()
			assistInputConnection = nil
		end
		updateAngleBar(tick())
		if not (config.silentAimEnabled or config.ballControlEnabled or config.perfectAngleEnabled) then return end
		if config.ballControlEnabled then
			assistInputConnection = userInputService.InputBegan:Connect(function(input, processed)
				local kind = input.UserInputType
				local skillKey = kind == Enum.UserInputType.Keyboard and not MOVE_KEYS[input.KeyCode]
				local gamepadKey = kind == Enum.UserInputType.Gamepad1 and not MOVE_KEYS[input.KeyCode]
				local screenPress = processed and (kind == Enum.UserInputType.Touch or kind == Enum.UserInputType.MouseButton1)
				if skillKey or gamepadKey or screenPress then
					assistState.controlPausedUntil = tick() + (config.ballControlPause or 0.9)
				end
			end)
		end
		if config.silentAimEnabled then installAssistHook() end
		if config.silentAimEnabled or config.perfectAngleEnabled then task.spawn(hookAssistButtons) end
		assistConnection = safeConnect(runService.Heartbeat, "ballAssistConnection", function(dt)
			if scriptDestroyed then return end
			local character = localPlayer.Character
			local hrp = character and character:FindFirstChild("HumanoidRootPart")
			local assistHumanoid = character and character:FindFirstChildOfClass("Humanoid")
			if assistHumanoid and assistHumanoid.Health <= 0 then return end
			local ball = findBall()
			if hrp then angleBarTick(hrp, tick()) end
			if not (hrp and ball and ball.Parent) then
				table.clear(assistState.history)
				updateAngleBar(tick())
				return
			end
			local now = tick()
			if ball ~= assistState.lastBall then
				assistState.lastBall = ball
				table.clear(assistState.history)
			end
			local velocity = ball.AssemblyLinearVelocity
			local flat = Vector3.new(velocity.X, 0, velocity.Z)
			local history = assistState.history
			table.insert(history, { t = now, v = flat })
			while #history > 0 and now - history[1].t > 0.3 do table.remove(history, 1) end
			local distance = (ball.Position - hrp.Position).Magnitude
			updateAngleBar(now)
			if config.silentAimEnabled and now < assistState.faceUntil and distance <= 25 then
				local faceDirection = goalDirection(hrp, hrp.Position)
				if faceDirection then
					hrp.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + faceDirection)
				end
			end
			local floorSpeed = flat.Magnitude
			for _, entry in ipairs(history) do
				if entry.v.Magnitude < floorSpeed then floorSpeed = entry.v.Magnitude end
			end
			if config.silentAimEnabled then
				local jump = flat.Magnitude - floorSpeed
				local kicked = distance <= 24 and flat.Magnitude > 14 and jump > 8
				if not kicked and now < (assistState.pendingUntil or 0) and distance <= 25 then
					kicked = true
					assistState.pendingUntil = 0
				end
				if kicked and now - assistState.lastKickAt > 0.5 then
					assistState.lastKickAt = now
					assistState.windowUntil = now + 0.5
					assistState.lockUntil = now + 1.6
					assistState.lockSpeed = math.max(flat.Magnitude, config.silentAimSpeed or 110)
					assistState.lockStartY = ball.Position.Y
					assistState.lockLateral = nil
					if config.perfectAngleEnabled then
						local goal = resolveGoalPosition(hrp)
						if goal then
							local toGoal = Vector3.new(goal.X - ball.Position.X, 0, goal.Z - ball.Position.Z)
							if toGoal.Magnitude > 1 then
								local lateral = Vector3.new(-toGoal.Unit.Z, 0, toGoal.Unit.X)
								assistState.lockLateral = lateral * pickAngleSide(goal, lateral)
								if angleBar then angleBar.flashUntil = now + 1.4 end
							end
						end
					end
					if now - assistState.lastDebug > 1 then
						assistState.lastDebug = now
						local owner = "?"
						pcall(function() owner = tostring(isnetworkowner(ball)) end)
						warn("[SilentAim] chute detectado | dono da bola:", owner, "| velocidade:", math.floor(flat.Magnitude), "| distancia:", math.floor(distance))
					end
				end
				if now < assistState.lockUntil then
					local direction, goal = goalDirection(hrp, ball.Position)
					if direction then
						local speed = assistState.lockSpeed or 110
						local lateral = assistState.lockLateral
						if config.perfectAngleEnabled and lateral and goal then
							local target = Vector3.new(
								goal.X + lateral.X * (config.perfectAngleOffset or 11),
								(assistState.lockStartY or ball.Position.Y) + (config.perfectAngleHeight or 7),
								goal.Z + lateral.Z * (config.perfectAngleOffset or 11)
							)
							local toTarget = target - ball.Position
							local flatDistance = Vector3.new(toTarget.X, 0, toTarget.Z).Magnitude
							if flatDistance < 5 then
								assistState.lockUntil = 0
								return
							end
							ball.AssemblyLinearVelocity = toTarget.Unit * speed
						else
							ball.AssemblyLinearVelocity = Vector3.new(direction.X * speed, 0, direction.Z * speed)
						end
						return
					end
				end
			end
			if not config.ballControlEnabled then return end
			if now - assistState.lastKickAt < 0.8 then return end
			if now < (assistState.controlPausedUntil or 0) then
				assistState.lastControlVel = nil
				return
			end
			if distance > (config.ballControlRange or 9) then return end
			local expected = assistState.lastControlVel
			if expected and (flat - Vector3.new(expected.X, 0, expected.Z)).Magnitude > 16 then
				assistState.controlPausedUntil = now + (config.ballControlPause or 0.9)
				assistState.lastControlVel = nil
				return
			end
			if flat.Magnitude > 60 then return end
			local hrpVelocity = hrp.AssemblyLinearVelocity
			local moveFlat = Vector3.new(hrpVelocity.X, 0, hrpVelocity.Z)
			local look = hrp.CFrame.LookVector
			local heading = moveFlat.Magnitude > 2 and moveFlat.Unit or Vector3.new(look.X, 0, look.Z)
			if heading.Magnitude < 0.1 then return end
			heading = heading.Unit
			local gain = config.ballControlStrength or 6
			local lead = 2.8 + math.min(moveFlat.Magnitude, 24) * 0.06
			local target = hrp.Position + heading * lead
			local toTarget = Vector3.new(target.X - ball.Position.X, 0, target.Z - ball.Position.Z)
			local wanted = moveFlat + toTarget * (gain + 2)
			local newFlat = flat:Lerp(wanted, math.clamp(dt * (gain + 8), 0, 1))
			local newY = velocity.Y
			if math.abs(newY) < 18 and ball.Position.Y - hrp.Position.Y < 1 then
				newY = newY * 0.55
			end
			ball.AssemblyLinearVelocity = Vector3.new(newFlat.X, newY, newFlat.Z)
			assistState.lastControlVel = Vector3.new(newFlat.X, newY, newFlat.Z)
		end)
	end
	registerCleanup(function()
		if assistConnection then assistConnection:Disconnect() end
		for _, connection in ipairs(assistButtonConnections) do connection:Disconnect() end
		if angleBar then angleBar.frame:Destroy() end
		if assistInputConnection then assistInputConnection:Disconnect() end
	end)
end
do
	local CAPE_STYLES = {
		["Zenith"] = { color = Color3.fromRGB(16, 20, 44), color2 = Color3.fromRGB(4, 5, 14), trim = Color3.fromRGB(255, 190, 60), material = Enum.Material.Fabric, emblem = Color3.fromRGB(255, 205, 90), glow = true },
		["Classica"] = { color = Color3.fromRGB(205, 25, 40), color2 = Color3.fromRGB(95, 6, 20), trim = Color3.fromRGB(255, 208, 80), material = Enum.Material.Fabric, emblem = Color3.fromRGB(255, 225, 110) },
		["Preta Real"] = { color = Color3.fromRGB(34, 34, 46), color2 = Color3.fromRGB(6, 6, 10), trim = Color3.fromRGB(255, 208, 80), material = Enum.Material.Fabric, emblem = Color3.fromRGB(255, 225, 110) },
		["Azul Real"] = { color = Color3.fromRGB(45, 100, 240), color2 = Color3.fromRGB(12, 26, 115), trim = Color3.fromRGB(240, 245, 255), material = Enum.Material.Fabric, emblem = Color3.fromRGB(255, 255, 255) },
		["Branca"] = { color = Color3.fromRGB(252, 252, 255), color2 = Color3.fromRGB(180, 192, 222), trim = Color3.fromRGB(255, 208, 80), material = Enum.Material.Fabric, emblem = Color3.fromRGB(190, 135, 20) },
		["Dourada"] = { color = Color3.fromRGB(255, 218, 90), color2 = Color3.fromRGB(180, 110, 15), trim = Color3.fromRGB(255, 250, 205), material = Enum.Material.Metal, emblem = Color3.fromRGB(110, 60, 0), glow = true },
