	local CAPE_QUALITY = {
		["Baixa"] = { columns = 3, segments = 7 },
		["Media"] = { columns = 5, segments = 9 },
		["Alta"] = { columns = 7, segments = 11 },
	}
	local CAPE_QUALITY_NAMES = { "Baixa", "Media", "Alta" }
	local SPARKLE_TEXTURE = "rbxasset://textures/particles/sparkles_main.dds"
	local capeFolder = nil
	local capeParts = {}
	local capeState = {}
	local capeBase = {}
	local capeExtras = {}
	local capeConnection = nil
	local capeCharacterConnection = nil
	local function clearStaleCapes()
		for _, container in ipairs({ workspace.CurrentCamera, workspace }) do
			if container then
				for _, child in ipairs(container:GetChildren()) do
					if child.Name == "TCSHubMiniCape" and child ~= capeFolder then child:Destroy() end
				end
			end
		end
	end
	local function clearCape()
		if capeConnection then
			capeConnection:Disconnect()
			capeConnection = nil
		end
		if capeFolder then
			capeFolder:Destroy()
			capeFolder = nil
		end
		table.clear(capeParts)
		table.clear(capeState)
		table.clear(capeBase)
		table.clear(capeExtras)
	end
	local function getTorso(character)
		return character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso")
	end
	local function newCapePart(size, color, material)
		local part = Instance.new("Part")
		part.Anchored = true
		part.CanCollide = false
		part.CanTouch = false
		part.CanQuery = false
		part.CastShadow = false
		part.Massless = true
		part.TopSurface = Enum.SurfaceType.Smooth
		part.BottomSurface = Enum.SurfaceType.Smooth
		part.Size = size
		part.Color = color
		part.Material = material
		part.Parent = capeFolder
		return part
	end
	local function addEmblem(part, style)
		local gui = Instance.new("SurfaceGui")
		gui.Face = Enum.NormalId.Back
		gui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud
		gui.PixelsPerStud = 90
		gui.Parent = part
		local ring = Instance.new("Frame")
		ring.Size = UDim2.fromScale(1, 1)
		ring.BackgroundColor3 = style.trim
		ring.BorderSizePixel = 0
		ring.Parent = gui
		local ringCorner = Instance.new("UICorner")
		ringCorner.CornerRadius = UDim.new(0.5, 0)
		ringCorner.Parent = ring
		local core = Instance.new("Frame")
		core.AnchorPoint = Vector2.new(0.5, 0.5)
		core.Position = UDim2.fromScale(0.5, 0.5)
		core.Size = UDim2.fromScale(0.82, 0.82)
		core.BackgroundColor3 = style.color2
		core.BorderSizePixel = 0
		core.Parent = ring
		local coreCorner = Instance.new("UICorner")
		coreCorner.CornerRadius = UDim.new(0.5, 0)
		coreCorner.Parent = core
		local gradient = Instance.new("UIGradient")
		gradient.Color = ColorSequence.new(style.color, style.color2)
		gradient.Rotation = 90
		gradient.Parent = core
		local label = Instance.new("TextLabel")
		label.AnchorPoint = Vector2.new(0.5, 0.5)
		label.Position = UDim2.fromScale(0.5, 0.5)
		label.Size = UDim2.fromScale(0.7, 0.4)
		label.BackgroundTransparency = 1
		label.Font = Enum.Font.GothamBlack
		label.Text = "Z"
		label.TextScaled = true
		label.TextColor3 = style.emblem
		label.Parent = core
	end
	local function buildCape(character)
		clearCape()
		clearStaleCapes()
		if not config.capeEnabled then return end
		local torso = getTorso(character)
		if not torso then return end
		local style = CAPE_STYLES[config.capeStyle] or CAPE_STYLES["Classica"]
		if config.capeStyle == "Personalizada" then
			style = {
				color = config.capeColor, color2 = config.capeColor2, trim = config.capeTrim,
				emblem = config.capeTrim, material = Enum.Material.Fabric, glow = true,
			}
		end
		local quality = CAPE_QUALITY[config.capeQuality] or CAPE_QUALITY["Media"]
		local columns, segments = quality.columns, quality.segments
		local center = (columns + 1) / 2
		local half = math.max((columns - 1) / 2, 1)
		local length = config.capeLength or 3.6
		local totalWidth = math.clamp(torso.Size.X * 1.1, 1.8, 3.2) * (config.capeWidth or 1)
		local columnWidth = totalWidth / columns
		local shapeName = config.capeShape or "Pontas"
		local function lengthFactor(column)
			local columnNorm = (column - center) / half
			if shapeName == "Pontas" then return (column % 2 == 1) and 1.1 or 0.8 end
			if shapeName == "Arredondada" then return 1 - 0.3 * columnNorm * columnNorm end
			if shapeName == "V" then return 1.14 - 0.36 * math.abs(columnNorm) end
			return 1
		end
		capeFolder = Instance.new("Folder")
		capeFolder.Name = "TCSHubMiniCape"
		capeFolder.Parent = workspace.CurrentCamera or workspace
		local allParts = {}
		for column = 1, columns do
			capeParts[column] = {}
			capeState[column] = {}
			capeBase[column] = {}
			local norm = (column - center) / half
			local segmentHeight = length * lengthFactor(column) / segments
			for index = 1, segments do
				local weight = index / segments
				local thickness = 0.07 + ((index % 2 == 0) and 0.03 or 0) + ((column % 2 == 0) and 0.015 or 0)
				local size = Vector3.new(columnWidth * (1 + weight * 0.45) + 0.03, segmentHeight + 0.02, thickness)
				local color = style.color:Lerp(style.color2, math.clamp(weight * 0.7 + math.abs(norm) * 0.16, 0, 1))
				if config.capeEdge ~= false and not style.rainbow and math.abs(norm) < 0.2 then
					color = color:Lerp(style.trim, 0.3)
				end
				local segment = newCapePart(size, color, style.material)
				segment.Transparency = 1
				capeParts[column][index] = segment
				capeState[column][index] = { pitch = 0, roll = 0, vp = 0, vr = 0 }
				capeBase[column][index] = color
				allParts[#allParts + 1] = segment
			end
		end
		capeExtras.edges = {}
		if config.capeEdge ~= false then
			for _, column in ipairs({ 1, columns }) do
				capeExtras.edges[column] = {}
				for index = 1, segments do
					local source = capeParts[column][index]
					local edge = newCapePart(
						Vector3.new(0.08, source.Size.Y, source.Size.Z + 0.025), style.trim,
						style.glow and Enum.Material.Neon or Enum.Material.SmoothPlastic
					)
					edge.Transparency = 1
					capeExtras.edges[column][index] = edge
					allParts[#allParts + 1] = edge
				end
			end
		end
		local leftClasp = newCapePart(Vector3.new(0.24, 0.24, 0.24), style.trim, Enum.Material.Metal)
		local rightClasp = newCapePart(Vector3.new(0.24, 0.24, 0.24), style.trim, Enum.Material.Metal)
		capeExtras.leftClasp, capeExtras.rightClasp, capeExtras.hems, capeExtras.emitters = leftClasp, rightClasp, {}, {}
		leftClasp.Transparency, rightClasp.Transparency = 1, 1
		allParts[#allParts + 1] = leftClasp
		allParts[#allParts + 1] = rightClasp
		if config.capeCollar ~= false then
			local collar = newCapePart(
				Vector3.new(totalWidth + 0.2, 0.22, 0.26), style.trim,
				style.glow and Enum.Material.Neon or Enum.Material.Metal
			)
			collar.Transparency = 1
			capeExtras.collar = collar
			allParts[#allParts + 1] = collar
			capeExtras.shoulders = {}
			for side = 1, 2 do
				local pad = newCapePart(Vector3.new(0.62, 0.62, 0.62), style.trim, Enum.Material.Metal)
				pad.Shape = Enum.PartType.Ball
				pad.Transparency = 1
				capeExtras.shoulders[side] = pad
				allParts[#allParts + 1] = pad
			end
		end
		for column = 1, columns do
			local lastSegment = capeParts[column][segments]
			local hem = newCapePart(
				Vector3.new(lastSegment.Size.X, 0.1, lastSegment.Size.Z + 0.03),
				style.trim, style.glow and Enum.Material.Neon or Enum.Material.Metal
			)
			hem.Transparency = 1
			capeExtras.hems[column] = hem
			allParts[#allParts + 1] = hem
			if style.glow then
				local emitter = Instance.new("ParticleEmitter")
				emitter.Texture = SPARKLE_TEXTURE
				emitter.Rate = 0
				emitter.Lifetime = NumberRange.new(0.5, 1.1)
				emitter.Speed = NumberRange.new(0.4, 1.6)
				emitter.SpreadAngle = Vector2.new(180, 180)
				emitter.LightEmission = 1
				emitter.Color = ColorSequence.new(style.trim, style.color)
				emitter.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.5), NumberSequenceKeypoint.new(1, 0) })
				emitter.Parent = hem
				capeExtras.emitters[column] = emitter
				if column == math.ceil(center) then
					local left = Instance.new("Attachment")
					left.Position = Vector3.new(-hem.Size.X / 2, 0, 0)
					left.Parent = hem
					local rightAttachment = Instance.new("Attachment")
					rightAttachment.Position = Vector3.new(hem.Size.X / 2, 0, 0)
					rightAttachment.Parent = hem
					local trail = Instance.new("Trail")
					trail.Attachment0 = left
					trail.Attachment1 = rightAttachment
					trail.Lifetime = 0.55
					trail.LightEmission = 1
					trail.FaceCamera = true
					trail.Color = ColorSequence.new(style.trim, style.color)
					trail.Transparency = NumberSequence.new({
						NumberSequenceKeypoint.new(0, 0.4), NumberSequenceKeypoint.new(1, 1),
					})
					trail.Parent = hem
				end
			end
		end
		local fxInfo = CAPE_FX[config.capeStyle] or {}
		local preset = FX_PRESETS[fxInfo.fx]
		if preset then
			local fxColor = ColorSequence.new(style.trim, style.color)
			for column = 1, columns do
				if column % 2 == 1 then
					for _, index in ipairs({ 3, math.ceil(segments * 0.7) }) do
						local host = capeParts[column][index]
						local emitter = Instance.new("ParticleEmitter")
						emitter.Texture = SPARKLE_TEXTURE
						emitter.Rate = preset.rate
						emitter.Lifetime = NumberRange.new(preset.life[1], preset.life[2])
						emitter.Speed = NumberRange.new(preset.speed[1], preset.speed[2])
						emitter.SpreadAngle = Vector2.new(180, 180)
						emitter.Acceleration = preset.accel
						emitter.LightEmission = 1
						emitter.Rotation = NumberRange.new(0, 360)
						emitter.RotSpeed = NumberRange.new(-120, 120)
						emitter.Color = fxColor
						emitter.Size = NumberSequence.new({
							NumberSequenceKeypoint.new(0, preset.size), NumberSequenceKeypoint.new(1, 0),
						})
						emitter.Parent = host
					end
				end
			end
		end
		if style.glow then
			local light = Instance.new("PointLight")
			light.Color = style.trim
			light.Range = 9
			light.Brightness = 0.7
			light.Parent = capeParts[math.ceil(center)][1]
			capeExtras.light = light
		end
		local carrierIndex = math.max(2, math.floor(segments * 0.3))
		if config.capeEmblem ~= false then
			local emblemSize = totalWidth * 0.4
			local emblem = newCapePart(Vector3.new(emblemSize, emblemSize, 0.04), style.color, Enum.Material.SmoothPlastic)
			emblem.Transparency = 1
			addEmblem(emblem, style)
			capeExtras.emblem = emblem
		end
		local startedAt = os.clock()
		local last = startedAt
		local smoothSpeed = 0
		local faded = false
		local previousVelocity = Vector3.zero
		capeConnection = safeConnect(runService.RenderStepped, "capeConnection", function()
			local now = os.clock()
			local dt = math.clamp(now - last, 0.001, 0.033)
			last = now
			local root = getTorso(character)
			local rootPart = character:FindFirstChild("HumanoidRootPart")
			if not (root and root.Parent and rootPart) then return end
			local humanoid = character:FindFirstChildOfClass("Humanoid")
			local alive = not humanoid or humanoid.Health > 0
			local wantedParent = alive and (workspace.CurrentCamera or workspace) or nil
			if capeFolder and capeFolder.Parent ~= wantedParent then capeFolder.Parent = wantedParent end
			if not alive then return end
			local velocity = rootPart.AssemblyLinearVelocity
			local horizontal = Vector3.new(velocity.X, 0, velocity.Z)
			local look = rootPart.CFrame.LookVector
			local runSpeed = horizontal:Dot(look)
			local sideSpeed = horizontal:Dot(rootPart.CFrame.RightVector)
			local yawRate = rootPart.AssemblyAngularVelocity.Y
			local acceleration = (horizontal - previousVelocity) / dt
			previousVelocity = horizontal
			local pushBack = math.clamp(acceleration:Dot(look) * 0.0016, -0.25, 0.3)
			smoothSpeed = smoothSpeed + (horizontal.Magnitude - smoothSpeed) * math.clamp(dt * 6, 0, 1)
			local fall = math.clamp(-velocity.Y * 0.01, -0.3, 0.55)
			local sway = config.capeSway or 1
			local topY = root.Size.Y / 2
			local backZ = root.Size.Z / 2 + 0.1
			leftClasp.CFrame = root.CFrame * CFrame.new(-(root.Size.X / 2 - 0.2), topY - 0.14, backZ) * CFrame.Angles(0.78, 0.78, 0)
			rightClasp.CFrame = root.CFrame * CFrame.new(root.Size.X / 2 - 0.2, topY - 0.14, backZ) * CFrame.Angles(0.78, 0.78, 0)
			local anchor = root.CFrame * CFrame.new(0, topY - 0.22, root.Size.Z / 2 + 0.1)
			if capeExtras.collar then
				capeExtras.collar.CFrame = anchor * CFrame.new(0, 0.1, -0.02)
				for side, pad in ipairs(capeExtras.shoulders) do
					local sign = side == 1 and -1 or 1
					pad.CFrame = root.CFrame * CFrame.new(sign * (root.Size.X / 2 + 0.12), topY - 0.1, 0.02)
				end
			end
			local rainbow = style.rainbow
			local hue = (now * 0.15) % 1
			local total = 0.14 + math.clamp(runSpeed * 0.021, -0.07, 0.95) + math.max(0, fall) + pushBack
			local flare = 0.05 + math.clamp(smoothSpeed * 0.006, 0, 0.14)
			local rollBase = -math.clamp(sideSpeed * 0.012, -0.4, 0.4)
			local turn = -math.clamp(yawRate * 0.05, -0.4, 0.4)
			local gust = 0.02 + 0.03 * math.min(smoothSpeed / 20, 1)
			for column = 1, columns do
				local norm = (column - center) / half
				local cursor = anchor * CFrame.new((column - center) * columnWidth, 0, 0)
				local previousState = nil
				for index = 1, segments do
					local weight = index / segments
					local state = capeState[column][index]
					local wave = math.sin(now * 3.4 + index * 0.55 + norm * 1.3) * gust * sway
						+ math.sin(now * 7.1 + index * 0.9 + norm * 2.1) * gust * 0.35 * sway
						+ math.sin(now * 9 - index * 0.75 + norm * 2.4) * math.min(smoothSpeed / 24, 1) * 0.045 * sway * weight
					local pitchTarget = -(total * (0.5 + weight) / segments) + wave
					pitchTarget = math.min(pitchTarget, index <= 3 and -0.004 or 0.03)
					local rollTarget = (rollBase / segments) * 2.2 + (turn * weight) / segments * 3
						+ norm * flare * (0.5 + weight) / segments * 2
					local stiffness = (88 - index * 4.5) * (1.15 - sway * 0.15)
					local damping = 2 * math.sqrt(stiffness) * 0.5
					local couple = previousState and 6 or 0
					local accelP = stiffness * (pitchTarget - state.pitch) - damping * state.vp
						+ (previousState and (previousState.vp - state.vp) * couple or 0)
					local accelR = stiffness * (rollTarget - state.roll) - damping * state.vr
						+ (previousState and (previousState.vr - state.vr) * couple or 0)
					state.vp = state.vp + accelP * dt
					state.vr = state.vr + accelR * dt
					state.pitch = math.clamp(state.pitch + state.vp * dt, -0.6, 0.35)
					state.roll = math.clamp(state.roll + state.vr * dt, -0.45, 0.45)
					previousState = state
					cursor = cursor * CFrame.Angles(state.pitch, 0, state.roll)
					local segment = capeParts[column][index]
					segment.CFrame = cursor * CFrame.new(0, -segment.Size.Y / 2, 0)
					cursor = cursor * CFrame.new(0, -(segment.Size.Y - 0.02), 0)
					if rainbow then
						local shade = (hue + weight * 0.35 * rainbow + (column - 1) * 0.03) % 1
						segment.Color = Color3.fromHSV(shade, 0.75, 1)
					elseif fxInfo.shimmer then
						local band = math.sin(weight * 7 - now * (fxInfo.shimmerSpeed or 3.2) + norm * 1.5)
						local amount = math.max(0, band) ^ 4 * 0.55
						if fxInfo.pulse then amount = amount + (math.sin(now * 2 + weight * 2) + 1) * 0.07 end
						segment.Color = capeBase[column][index]:Lerp(style.trim, math.clamp(amount, 0, 1))
					end
					local edge = capeExtras.edges[column] and capeExtras.edges[column][index]
					if edge then
						local sign = column == 1 and -1 or 1
						edge.CFrame = segment.CFrame * CFrame.new(sign * (segment.Size.X / 2 + 0.02), 0, 0)
					end
					if index == segments then
						local hem = capeExtras.hems[column]
						hem.CFrame = segment.CFrame * CFrame.new(0, -segment.Size.Y / 2 + 0.04, 0)
						local emitter = capeExtras.emitters[column]
						if emitter then emitter.Rate = math.clamp(smoothSpeed * 0.7, 0, 14) end
					end
				end
			end
			local emblem = capeExtras.emblem
			if emblem then
				local carrier = capeParts[math.ceil(center)][carrierIndex]
				emblem.CFrame = carrier.CFrame * CFrame.new(0, -0.1, carrier.Size.Z / 2 + 0.03)
			end
			local light = capeExtras.light
			if light and fxInfo.flicker then
				light.Brightness = 0.8 + math.sin(now * 17) * 0.25 + math.sin(now * 9.3) * 0.15
			end
			if not faded then
				local alpha = 1 - math.clamp((now - startedAt) / 0.7, 0, 1)
				for _, part in ipairs(allParts) do part.Transparency = alpha end
				if alpha <= 0 then faded = true end
				if emblem then emblem.Transparency = 1 end
			end
		end)
	end
	local function applyCape()
		if capeCharacterConnection then
			capeCharacterConnection:Disconnect()
			capeCharacterConnection = nil
		end
		clearCape()
		if not config.capeEnabled then return end
		local character = localPlayer.Character
		if character then task.spawn(buildCape, character) end
		capeCharacterConnection = localPlayer.CharacterAdded:Connect(function(newCharacter)
			task.wait(0.6)
			if config.capeEnabled then buildCape(newCharacter) end
		end)
	end
	QuickButtons.applyCape = applyCape
	QuickButtons.version = "2026.10.28 - so Ouroboros"
	QuickButtons.capeStyleNames = CAPE_STYLE_NAMES
	QuickButtons.capeQualityNames = CAPE_QUALITY_NAMES
	QuickButtons.capeShapeNames = { "Reta", "Pontas", "Arredondada", "V" }
	registerCleanup(function()
		if capeCharacterConnection then capeCharacterConnection:Disconnect() end
		clearCape()
	end)
end
Loader.set(0.62, "Carregando goleiro...")
local replicatedStorage, DIVE_MODE_NAMES, gkButtons, gkNotify, scanGkButtons
do
	replicatedStorage = game:GetService("ReplicatedStorage")
	local GK_ACTIONS = {
		["High Dive Left"] = { "high dive left", "esquerda alto" },
		["High Dive Right"] = { "high dive right", "direita alto" },
		["Dive Left"] = { "dive left", "esquerda baixo" },
		["Dive Right"] = { "dive right", "direita baixo" },
		["High Catch"] = { "high catch", "agarrar alto" },
		["Low Catch"] = { "low catch", "agarrar baixo" },
		["Reflex"] = { "reflex", "reflexo" },
		["Front Dive"] = { "front dive", "front", "frente" },
		["Rush"] = { "rush", "enfrentar" },
	}
	DIVE_MODE_NAMES = {
		"Auto", "Esquerda Alto", "Direita Alto", "Esquerda Baixo", "Direita Baixo",
		"Agarrar Alto", "Agarrar Baixo", "Reflexo", "Frente",
	}
	local DIVE_MODE_ACTIONS = {
		["Esquerda Alto"] = "High Dive Left",
		["Direita Alto"] = "High Dive Right",
		["Esquerda Baixo"] = "Dive Left",
		["Direita Baixo"] = "Dive Right",
		["Agarrar Alto"] = "High Catch",
		["Agarrar Baixo"] = "Low Catch",
		["Reflexo"] = "Reflex",
		["Frente"] = "Front Dive",
	}
	local RELEASE_BUTTON_TEXTS = {
		"soltar bola", "arremessar", "chute", "passe", "longo",
		"drop ball", "throw", "shoot", "pass", "long",
	}
	local CLICK_SIGNALS = { "Activated", "MouseButton1Click", "MouseButton1Down", "MouseButton1Up", "TouchTap" }
	local RELEASE_TIME = 1.5
	local SIDE_THRESHOLD = 2.5
	gkButtons = {}
	local hookedReleaseButtons = {}
	local releaseConnections = {}
	local catchRemote = nil
	local lastGkScan = 0
	local lastCatch = 0
	local catchHeld = false
	local catchTries = 0
	local lastIntel = 0
	local lastDive = 0
	local lastRemoteWarn = 0
	local releaseUntil = 0
	local gkActionUntil = 0
	local MAX_ANALYZE_DISTANCE = 120
	function gkNotify(content)
		pcall(function()
			WindUI:Notify({ Title = "GK", Content = content, Duration = 3 })
		end)
	end
	local function getButtonText(button)
		local text = ""
		pcall(function() text = button.Text end)
		if text == "" then
			local label = button:FindFirstChildWhichIsA("TextLabel", true)
			if label then text = label.Text end
		end
		return text:lower():match("^%s*(.-)%s*$")
	end
	local function matchesAnyGkAction(textLower)
		for _, aliases in pairs(GK_ACTIONS) do
			for _, alias in ipairs(aliases) do
				if textLower == alias or textLower:find(alias, 1, true) then return true end
			end
		end
		return false
	end
	local gkScanning = false
	local lastGkCount = -1
	function scanGkButtons()
		if gkScanning then return end
		gkScanning = true
		lastGkScan = tick()
		local ok, err = pcall(function()
			local found = {}
			local descendants = playerGui:GetDescendants()
			for index, descendant in ipairs(descendants) do
				if descendant.Parent
					and (descendant:IsA("TextButton") or descendant:IsA("ImageButton"))
					and not descendant:IsDescendantOf(hubGui) then
					local textLower = getButtonText(descendant)
					if matchesAnyGkAction(textLower) or descendant.Name:find("GK") then
						table.insert(found, { button = descendant, name = descendant.Name, text = textLower })
					end
					if table.find(RELEASE_BUTTON_TEXTS, textLower) and not hookedReleaseButtons[descendant] then
						hookedReleaseButtons[descendant] = true
						table.insert(releaseConnections, descendant.InputBegan:Connect(function(input)
							if input.UserInputType == Enum.UserInputType.Touch
								or input.UserInputType == Enum.UserInputType.MouseButton1 then
								releaseUntil = tick() + RELEASE_TIME
							end
						end))
					end
				end
				if index % 150 == 0 then task.wait() end
			end
			gkButtons = found
		end)
		gkScanning = false
		if not ok then
			warn("Zenith: erro ao escanear botoes GK -> " .. tostring(err))
			return
		end
		if #gkButtons ~= lastGkCount then
			lastGkCount = #gkButtons
			print("Zenith: botoes GK encontrados: " .. #gkButtons)
		end
	end
	local function requestGkScan()
		if gkScanning then return end
		if #gkButtons == 0 or tick() - lastGkScan > 15 then
			task.spawn(scanGkButtons)
		end
	end
	task.spawn(function()
		while not scriptDestroyed do
			if config.autoCatchEnabled or config.intelEnabled or config.diveEnabled then
				requestGkScan()
			end
			task.wait(1)
		end
	end)
	local function findGkButton(actionKey)
		local aliases = GK_ACTIONS[actionKey]
		if not aliases then return nil end
		for _, entry in ipairs(gkButtons) do
			if entry.button.Parent then
				for _, alias in ipairs(aliases) do
					if entry.text == alias then return entry.button end
				end
			end
		end
		for _, entry in ipairs(gkButtons) do
			if entry.button.Parent then
				for _, alias in ipairs(aliases) do
					if entry.text:find(alias, 1, true) then return entry.button end
				end
			end
		end
		return nil
	end
	local function clickGkButton(button)
		for _, signalName in ipairs(CLICK_SIGNALS) do
			pcall(function() firesignal(button[signalName]) end)
		end
	end
	local function pressGkAction(actionKey)
		local button = findGkButton(actionKey)
		if not button then
			print("Zenith: botao nao encontrado: " .. actionKey)
			if not gkScanning and tick() - lastGkScan > 3 then
				task.spawn(scanGkButtons)
			end
			return false
		end
		clickGkButton(button)
		return true
	end
	local function jump()
		local character = localPlayer.Character
		local humanoid = character and character:FindFirstChild("Humanoid")
		if not humanoid then return end
		pcall(function() humanoid.Jump = true end)
		pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end)
	end
	local function tryRemoteCatch(ball)
		if not (catchRemote and catchRemote.Parent) then
			catchRemote = replicatedStorage:FindFirstChild("CatchBall", true)
		end
		if not catchRemote then
			if tick() - lastRemoteWarn > 10 then
				lastRemoteWarn = tick()
				warn("Zenith: remote CatchBall nao encontrado, usando os botoes de agarrar")
			end
			return false
		end
		pcall(function()
			if catchRemote:IsA("RemoteEvent") then
				catchRemote:FireServer(ball)
			elseif catchRemote:IsA("RemoteFunction") then
				catchRemote:InvokeServer(ball)
			end
		end)
		return true
	end
	local function tryCatch(ball, hrp)
		if tryRemoteCatch(ball) then return end
		local high = ball.Position.Y - hrp.Position.Y > config.intelHeight
		pressGkAction(high and "High Catch" or "Low Catch")
	end
	local trackedBall = nil
	local smoothedVelocity = Vector3.zero
	local lastBallPosition = nil
	local lastTrackTime = 0
	local function updateBallTracker(ball)
		local now = tick()
		if ball ~= trackedBall then
			trackedBall = ball
			smoothedVelocity = ball.AssemblyLinearVelocity
			lastBallPosition = ball.Position
			lastTrackTime = now
			return
		end
		local dt = now - lastTrackTime
		if dt <= 0 then return end
		local measured = (ball.Position - lastBallPosition) / dt
		local blended = ball.AssemblyLinearVelocity:Lerp(measured, 0.35)
		smoothedVelocity = smoothedVelocity:Lerp(blended, 0.5)
		lastBallPosition = ball.Position
		lastTrackTime = now
	end
	local function analyzeBall(hrp, ball)
		local currentCamera = workspace.CurrentCamera
		if not currentCamera then return nil end
		local velocity = smoothedVelocity
		local velocityFlat = Vector3.new(velocity.X, 0, velocity.Z)
		if velocityFlat.Magnitude < 4 then return nil end
		local direction = velocityFlat.Unit
		local toPlayer = hrp.Position - ball.Position
		local timeToReach = Vector3.new(toPlayer.X, 0, toPlayer.Z):Dot(direction) / velocityFlat.Magnitude
		if timeToReach <= 0 or timeToReach > 2 then return nil end
		local gravity = workspace.Gravity * config.gkGravity
		local height = ball.Position.Y + velocity.Y * timeToReach - 0.5 * gravity * timeToReach * timeToReach
		height = math.max(height, hrp.Position.Y - 3 + ball.Size.Y / 2)
		local intercept = Vector3.new(
			ball.Position.X + velocity.X * timeToReach,
			height,
			ball.Position.Z + velocity.Z * timeToReach
		)
		local cameraRight = currentCamera.CFrame.RightVector
		local rightFlat = Vector3.new(cameraRight.X, 0, cameraRight.Z)
		if rightFlat.Magnitude < 0.1 then rightFlat = Vector3.xAxis end
		rightFlat = rightFlat.Unit
		local delta = intercept - hrp.Position
		return {
			velocity = velocity,
			distance = (ball.Position - hrp.Position).Magnitude,
			timeToReach = timeToReach,
			intercept = intercept,
			side = Vector3.new(delta.X, 0, delta.Z):Dot(rightFlat),
			height = delta.Y,
			miss = delta.Magnitude,
		}
	end
	local function executeIntelCatch(info)
		local isHigh = info.height > config.intelHeight
		local isSide = math.abs(info.side) >= SIDE_THRESHOLD
		if isSide then
			if isHigh then
				pressGkAction(info.side < 0 and "High Dive Left" or "High Dive Right")
			else
				pressGkAction("Low Catch")
			end
		elseif isHigh then
			if config.gkJumpOnHighCatch then
				task.spawn(jump)
				task.wait(0.05)
			end
			pressGkAction("High Catch")
		else
			pressGkAction("Low Catch")
		end
	end
	local function executeDive(info)
		local actionKey
		if config.diveMode ~= "Auto" then
			actionKey = DIVE_MODE_ACTIONS[config.diveMode]
		else
			local isHigh = info.height > config.intelHeight
			if config.diveReflex ~= false and info.distance <= 10 and info.velocity.Magnitude >= 40
				and info.timeToReach <= 0.22 and findGkButton("Reflex") then
				pressGkAction("Reflex")
				return
			end
			if config.diveCatchWhenStraight and math.abs(info.side) < config.diveMinSide then
				if isHigh and config.gkJumpOnHighCatch then
					task.spawn(jump)
					task.wait(0.05)
				end
				actionKey = isHigh and "High Catch" or "Low Catch"
			elseif isHigh then
				actionKey = info.side > 0 and "High Dive Right" or "High Dive Left"
			else
				actionKey = info.side > 0 and "Dive Right" or "Dive Left"
			end
		end
		if actionKey then pressGkAction(actionKey) end
	end
	local predictionMarker = createVisualPart(Enum.PartType.Ball, Vector3.one * 1.2, Enum.Material.Neon)
	predictionMarker.Color = Color3.fromRGB(255, 70, 70)
	local gkPing, gkPingTime = 0, 0
	local gkConnection = safeConnect(runService.Heartbeat, "gkConnection", function()
		if scriptDestroyed then return end
		if not (config.autoCatchEnabled or config.intelEnabled or config.diveEnabled) then
			if predictionMarker.Transparency ~= 1 then predictionMarker.Transparency = 1 end
			return
		end
		local character = localPlayer.Character
		local hrp = character and character:FindFirstChild("HumanoidRootPart")
		local gkHumanoid = character and character:FindFirstChildOfClass("Humanoid")
		local ball = findBall()
		if not (hrp and ball) or (gkHumanoid and gkHumanoid.Health <= 0) then
			if predictionMarker.Transparency ~= 1 then predictionMarker.Transparency = 1 end
			return
		end
		updateBallTracker(ball)
		local info = nil
		if (config.intelEnabled or config.diveEnabled)
			and (ball.Position - hrp.Position).Magnitude <= MAX_ANALYZE_DISTANCE then
			info = analyzeBall(hrp, ball)
		end
		if config.gkShowPrediction and info then
			predictionMarker.CFrame = CFrame.new(info.intercept)
			predictionMarker.Transparency = 0.3
		else
			if predictionMarker.Transparency ~= 1 then predictionMarker.Transparency = 1 end
		end
		local now = tick()
		if now < releaseUntil then return end
		local distance = (ball.Position - hrp.Position).Magnitude
		if now - gkPingTime > 0.5 then
			gkPingTime = now
			pcall(function() gkPing = math.min(localPlayer:GetNetworkPing(), 0.25) end)
		end
		local ping = gkPing
		if config.autoCatchEnabled then
			local speed = smoothedVelocity.Magnitude
			local range = config.autoCatchRange
			if config.autoCatchPredict ~= false then
				range = range + math.min(speed * ping * 0.6, 6)
			end
			local approaching = true
			if config.autoCatchPredict ~= false and speed > 6 then
				approaching = smoothedVelocity:Dot(hrp.Position - ball.Position) > 0
			end
			if distance > config.autoCatchRange + 2 then
				catchHeld = false
				catchTries = 0
			elseif distance <= range and (approaching or distance <= config.autoCatchRange * 0.5) then
				if not catchHeld and now - lastCatch >= config.autoCatchCooldown then
					lastCatch = now
					catchHeld = true
					catchTries = 1
					tryCatch(ball, hrp)
				elseif catchHeld and catchTries < (config.autoCatchRetries or 3)
					and now - lastCatch >= math.max(0.45, config.autoCatchCooldown)
					and speed > 8 then
					lastCatch = now
					catchTries = catchTries + 1
					tryCatch(ball, hrp)
				end
			end
		end
		if not info or info.miss > config.gkMaxMiss then return end
		if now < gkActionUntil then return end
		local wantsIntel = config.intelEnabled
			and now - lastIntel >= config.intelCooldown
			and info.distance <= config.intelRange
			and info.timeToReach <= config.intelLeadTime + ping
		local wantsDive = config.diveEnabled
			and not (config.diveBlockWhenIntel and config.intelEnabled)
			and now - lastDive >= config.diveCooldown
			and info.velocity.Magnitude >= config.diveMinSpeed
			and info.distance <= config.diveRange
			and info.timeToReach <= config.diveLeadTime + ping
		if wantsIntel then
			lastIntel = now
			gkActionUntil = now + 0.4
			task.spawn(executeIntelCatch, info)
		elseif wantsDive then
			lastDive = now
			gkActionUntil = now + 0.4
			task.spawn(executeDive, info)
		end
	end)
	local catchHitbox = createVisualPart(Enum.PartType.Ball, Vector3.one, Enum.Material.ForceField)
	local catchHitboxConnection = safeConnect(runService.RenderStepped, "catchHitboxConnection", function()
		local character = localPlayer.Character
		local hrp = character and character:FindFirstChild("HumanoidRootPart")
		if scriptDestroyed or not hrp or not config.autoCatchShowHitbox then
			if catchHitbox.Transparency ~= 1 then catchHitbox.Transparency = 1 end
			return
		end
		catchHitbox.Size = Vector3.one * config.autoCatchRange * 2
		catchHitbox.CFrame = CFrame.new(hrp.Position)
		catchHitbox.Color = Color3.fromRGB(0, 200, 255)
		catchHitbox.Transparency = 0.65
	end)
	registerCleanup(function()
		gkConnection:Disconnect()
		predictionMarker:Destroy()
		catchHitboxConnection:Disconnect()
		for _, connection in ipairs(releaseConnections) do
			connection:Disconnect()
		end
	end)
end
Loader.set(0.70, "Preparando auras...")
local AURAS, AURA_NAMES, setAuraColor, applyAura, scheduleAuraReapply, triggerAuraBurst
do
	local TEXTURE_FIRE = "rbxasset://textures/particles/fire_main.dds"
	local TEXTURE_SMOKE = "rbxasset://textures/particles/smoke_main.dds"
	local TEXTURE_SPARKLE = "rbxasset://textures/particles/sparkles_main.dds"
	local function fadeSequence(startValue, endValue)
		return NumberSequence.new({
			NumberSequenceKeypoint.new(0, startValue),
			NumberSequenceKeypoint.new(1, endValue),
		})
	end
	local function scaleNumberSequence(sequence, factor)
		local keypoints = {}
		for _, keypoint in ipairs(sequence.Keypoints) do
			table.insert(keypoints, NumberSequenceKeypoint.new(keypoint.Time, keypoint.Value * factor, keypoint.Envelope * factor))
		end
		return NumberSequence.new(keypoints)
	end
	local function coreGlowLayer(size)
		return {
			Texture = TEXTURE_SPARKLE, Rate = 5, Lifetime = NumberRange.new(0.9, 1.3),
			Speed = NumberRange.new(0, 0), SpreadAngle = Vector2.new(0, 0),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, size * 0.4),
				NumberSequenceKeypoint.new(0.4, size),
				NumberSequenceKeypoint.new(1, size * 1.3),
			}),
			LightEmission = 1,
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1),
				NumberSequenceKeypoint.new(0.3, 0.75),
				NumberSequenceKeypoint.new(1, 1),
			}),
			Rotation = NumberRange.new(0, 360), RotSpeed = NumberRange.new(-30, 30),
		}
	end
