	local function sparkEmitter(rate, lifetime, speed, spread, size, accel, rotSpeed)
		return {
			Texture = TEXTURE_SPARKLE, Rate = rate, Lifetime = NumberRange.new(lifetime[1], lifetime[2]),
			Speed = NumberRange.new(speed[1], speed[2]), SpreadAngle = Vector2.new(spread, spread),
			Size = fadeSequence(size, 0), Acceleration = accel or Vector3.zero, LightEmission = 1,
			Rotation = NumberRange.new(0, 360), RotSpeed = NumberRange.new(-(rotSpeed or 60), rotSpeed or 60),
		}
	end
	local function hazeEmitter(rate, startSize, endSize, startAlpha, emission)
		return {
			Texture = TEXTURE_SMOKE, Rate = rate, Lifetime = NumberRange.new(1.4, 2.2),
			Speed = NumberRange.new(0.5, 1.5), SpreadAngle = Vector2.new(180, 180),
			Size = fadeSequence(startSize, endSize), LightEmission = emission,
			Transparency = fadeSequence(startAlpha, 1),
		}
	end
