	local function colorAuraTarget(target, color, color2)
		local lighter = color:Lerp(Color3.new(1, 1, 1), 0.55)
		local kind = target.kind
		if kind == "emitter" then
			target.object.Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, lighter),
				ColorSequenceKeypoint.new(0.45, color),
				ColorSequenceKeypoint.new(1, color2),
			})
		elseif kind == "trail" then
			target.object.Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, lighter),
				ColorSequenceKeypoint.new(0.5, color),
				ColorSequenceKeypoint.new(1, color2),
			})
		elseif kind == "beam" then
			target.object.Color = ColorSequence.new(color, color2)
		elseif kind == "highlight" then
			target.object.FillColor = color
			target.object.OutlineColor = color2:Lerp(Color3.new(1, 1, 1), 0.35)
		elseif kind == "part" then
			target.object.Color = target.alt and color2 or color
		elseif kind == "light" then
			target.object.Color = color
		end
	end
	function setAuraColor(color, color2)
		color2 = color2 or config.auraColor2
		for _, target in ipairs(auraTargets) do
			pcall(colorAuraTarget, target, color, color2)
		end
	end
	local function clearAura()
		if auraStateConnection then
			auraStateConnection:Disconnect()
			auraStateConnection = nil
		end
		for _, target in ipairs(auraTargets) do
			pcall(function() target.object:Destroy() end)
		end
		table.clear(auraTargets)
		table.clear(auraOrbs)
		table.clear(QuickButtons.AuraProps.items)
		auraGround = nil
		auraPillar = nil
		auraLight = nil
		auraHighlight = nil
		auraRain = nil
		auraLightning = nil
		auraBurstEmitter = nil
		auraCircle = nil
		auraDefinition = nil
		if auraBloom then
			pcall(function() auraBloom:Destroy() end)
			auraBloom = nil
		end
		if auraFolder then
			pcall(function() auraFolder:Destroy() end)
			auraFolder = nil
		end
	end
	local function createAuraPart(shape, size, transparency, alt)
		local part = Instance.new("Part")
		part.Shape = shape
		part.Size = size
		part.Anchored = true
		part.CanCollide = false
		part.CanQuery = false
		part.CanTouch = false
		part.CastShadow = false
		part.Material = Enum.Material.Neon
		part.Transparency = transparency
		part.Parent = auraFolder
		table.insert(auraTargets, { object = part, kind = "part", alt = alt })
		return part
	end
	local function createEmitter(parent, layer)
		local scale = auraScaleApplied
		local emitter = Instance.new("ParticleEmitter")
		for property, value in pairs(layer) do
			if property == "Size" and scale ~= 1 and typeof(value) == "NumberSequence" then
				value = scaleNumberSequence(value, scale)
			elseif property == "Rate" then
				value = value * config.auraIntensity
			end
			local ok, err = pcall(function() emitter[property] = value end)
			if not ok then
				warn("Zenith: aura ignorou '" .. property .. "' -> " .. tostring(err))
			end
		end
		emitter.Enabled = true
		emitter.Parent = parent
		table.insert(auraTargets, { object = emitter, kind = "emitter" })
		return emitter
	end
	local function createAuraOrb(group, orbData)
		local scale = auraScaleApplied
		local size = (orbData.size or group.size) * scale
		local part = createAuraPart(Enum.PartType.Ball, Vector3.one * size, 0, orbData.alt)
		local trailWidth = (group.trailWidth and group.trailWidth * scale) or size * 1.4
		local topAttachment = Instance.new("Attachment")
		topAttachment.Position = Vector3.new(0, trailWidth / 2, 0)
		topAttachment.Parent = part
		local bottomAttachment = Instance.new("Attachment")
		bottomAttachment.Position = Vector3.new(0, -trailWidth / 2, 0)
		bottomAttachment.Parent = part
		local trail = Instance.new("Trail")
		trail.Attachment0 = topAttachment
		trail.Attachment1 = bottomAttachment
		trail.Lifetime = group.trailLife or 0.5
		trail.LightEmission = 1
		trail.FaceCamera = true
		trail.MinLength = 0.02
		trail.Transparency = fadeSequence(0.1, 1)
		trail.WidthScale = fadeSequence(1, 0)
		trail.Parent = part
		table.insert(auraTargets, { object = trail, kind = "trail" })
		orbData.part = part
		orbData.top = topAttachment
		orbData.size = size
		orbData.group = group
		orbData.phase = math.random() * 10
		table.insert(auraOrbs, orbData)
	end
	local function createLinkBeam(orbA, orbB, link)
		local scale = auraScaleApplied
		local beam = Instance.new("Beam")
		beam.Attachment0 = orbA.top
		beam.Attachment1 = orbB.top
		if link.fromSize then
			beam.Width0 = orbA.size * 0.8
			beam.Width1 = orbB.size * 0.8
		else
			beam.Width0 = link.width * scale
			beam.Width1 = link.width * scale
		end
		beam.LightEmission = 1
		beam.FaceCamera = true
		beam.Segments = 12
		beam.CurveSize0 = (link.curve or 0) * scale
		beam.CurveSize1 = -(link.curve or 0) * scale
		beam.Transparency = NumberSequence.new(0.2)
		beam.Parent = orbA.part
		table.insert(auraTargets, { object = beam, kind = "beam" })
	end
	local function linkGroup(group, firstIndex)
		if not group.link then return end
		local lastIndex = #auraOrbs
		for index = firstIndex, lastIndex - 1 do
			local current, following = auraOrbs[index], auraOrbs[index + 1]
			if group.mode ~= "wing" or current.side == following.side then
				createLinkBeam(current, following, group.link)
			end
		end
		if (group.mode == nil or group.mode == "orbit") and lastIndex - firstIndex >= 2 then
			createLinkBeam(auraOrbs[lastIndex], auraOrbs[firstIndex], group.link)
		end
	end
	local function buildGroupOrbs(group)
		if group.mode == "wing" then
			for _, side in ipairs({ -1, 1 }) do
				for index = 1, group.feathers do
					createAuraOrb(group, { side = side, featherIndex = index, alt = index % 2 == 0 })
				end
			end
			return
		end
		if group.mode == "chain" then
			for index = 1, group.count do
				local ratio = (index - 1) / group.count
				createAuraOrb(group, {
					chainIndex = index - 1,
					size = group.size * (1 - (group.shrink or 0.6) * ratio),
					alt = ratio > 0.5,
				})
			end
			return
		end
		for index = 1, group.count do
			local rotation
			if group.plane then
				rotation = CFrame.Angles(math.rad(group.plane.pitch or 0), math.rad(group.plane.yaw or 0), 0)
			else
				local tiltAngle = math.rad(group.tilt or 0) * (index % 2 == 0 and 1 or -1)
				rotation = CFrame.Angles(tiltAngle, math.rad(index * 47), 0)
			end
			createAuraOrb(group, {
				offset = (index - 1) / group.count * math.pi * 2 + (group.phaseShift or 0),
				fraction = (index - 1) / group.count + (group.phaseShift and 0.5 or 0),
				rotation = rotation,
				alt = index % 2 == 0,
			})
		end
	end
	local function createAuraGroup(group)
		local firstIndex = #auraOrbs + 1
		buildGroupOrbs(group)
		linkGroup(group, firstIndex)
	end
	local function createAnchorPart(size)
		local part = Instance.new("Part")
		part.Anchored = true
		part.CanCollide = false
		part.CanQuery = false
		part.CanTouch = false
		part.CastShadow = false
		part.Transparency = 1
		part.Size = size
		part.Parent = auraFolder
		table.insert(auraTargets, { object = part, kind = "none" })
		return part
	end
