	function QuickButtons.AuraProps.build(name, scale)
		table.clear(QuickButtons.AuraProps.items)
		local layers = QuickButtons.AuraProps.defs[name]
		if not layers then return end
		for _, layer in ipairs(layers) do
			local shapeFn = QuickButtons.AuraProps.shapes[layer.kind]
			if shapeFn then
				local itemScale = (layer.size or 1) * scale
				local orient = CFrame.Angles(math.rad(layer.pitch or 0), math.rad(layer.yaw or 0), math.rad(layer.roll or 0))
				local itemCount = layer.count
				if config.lightMode then itemCount = math.max(1, math.ceil(itemCount * 0.5)) end
				for index = 1, itemCount do
					local parts = {}
					for _, spec in ipairs(shapeFn()) do
						local part = createAuraPart(spec.shape, spec.size * itemScale, spec.tr, spec.alt)
						if spec.sphere then
							local mesh = Instance.new("SpecialMesh")
							mesh.MeshType = Enum.MeshType.Sphere
							mesh.Parent = part
						end
						table.insert(parts, { part = part, cf = CFrame.new(spec.cf.Position * itemScale) * spec.cf.Rotation })
					end
					table.insert(QuickButtons.AuraProps.items, { layer = layer, index = index, count = itemCount, parts = parts, orient = orient })
				end
			end
		end
	end
	function QuickButtons.AuraProps.update(origin, clock, scale)
		for _, prop in ipairs(QuickButtons.AuraProps.items) do
			local layer = prop.layer
			local index = prop.index
			local phase = index / prop.count
			local mode = layer.mode
			local speed = layer.speed or 1
			local radius = (layer.radius or 0) * scale
			local rootCF
			if mode == "orbit" then
				local angle = clock * speed + phase * math.pi * 2
				local y = ((layer.height or 0) + math.sin(clock * 1.5 + index) * (layer.bob or 0)) * scale
				local position = origin + Vector3.new(math.cos(angle) * radius, y, math.sin(angle) * radius)
				local direction = Vector3.new(-math.sin(angle), 0, math.cos(angle)) * (speed >= 0 and 1 or -1)
				rootCF = CFrame.lookAt(position, position + direction)
			elseif mode == "rise" or mode == "fall" then
				local t = (clock * speed * 0.15 + phase + (index * 0.37) % 1) % 1
				if mode == "fall" then t = 1 - t end
				local angle = phase * math.pi * 7.3 + clock * 0.4
				local spread = radius * (0.55 + 0.45 * ((index * 0.618) % 1))
				local y = ((layer.floor or -2.5) + t * (layer.height or 6)) * scale
				rootCF = CFrame.new(origin + Vector3.new(math.cos(angle) * spread, y, math.sin(angle) * spread))
			elseif mode == "spiral" then
				local t = (clock * 0.22 * math.abs(speed) + phase) % 1
				local angle = clock * speed + phase * math.pi * 2
				local spread = radius * (1 - 0.45 * t)
				local y = ((layer.floor or -2.5) + t * (layer.height or 6)) * scale
				rootCF = CFrame.new(origin + Vector3.new(math.cos(angle) * spread, y, math.sin(angle) * spread))
			elseif mode == "gyro" then
				rootCF = CFrame.new(origin)
					* CFrame.Angles(0, clock * speed * (index % 2 == 0 and -1 or 1), (index - 1) * math.rad(60))
					* CFrame.Angles(math.rad(layer.tilt or 0), 0, 0)
			else
				local angle = clock * speed + phase * math.pi * 2
				local bob = mode == "hover" and math.sin(clock * 1.6 + index) * 0.25 or 0
				local y = ((layer.height or 4) + bob) * scale
				rootCF = CFrame.new(origin + Vector3.new(math.cos(angle) * radius, y, math.sin(angle) * radius))
			end
			if layer.spin then
				rootCF = rootCF * CFrame.Angles(0, clock * layer.spin + index, 0)
			end
			rootCF = rootCF * prop.orient
			for _, item in ipairs(prop.parts) do
				item.part.CFrame = rootCF * item.cf
			end
		end
	end
	function applyAura(silent)
		clearAura()
		local definition = AURAS[config.auraName]
		if not definition then return end
		local character = localPlayer.Character
		local hrp = character and character:FindFirstChild("HumanoidRootPart")
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		if not hrp then
			warn("Zenith: aura sem personagem/HumanoidRootPart")
			return
		end
		local scale = config.auraScale
		auraScaleApplied = scale
		auraFolder = Instance.new("Folder")
		auraFolder.Name = "TCSHubMiniAura"
		auraFolder.Parent = workspace.CurrentCamera or workspace
		for _, layer in ipairs(definition.emitters or {}) do
			createEmitter(hrp, layer)
		end
		for kind, layer in pairs(definition.limbs or {}) do
			for _, names in ipairs(LIMB_NAMES[kind] or {}) do
				for _, name in ipairs(names) do
					local limb = character:FindFirstChild(name)
					if limb then
						createEmitter(limb, layer)
						break
					end
				end
			end
		end
		if config.auraMotes and not config.lightMode then
			createEmitter(hrp, {
				Texture = TEXTURE_SPARKLE, Rate = 16, Lifetime = NumberRange.new(2.5, 4),
				Speed = NumberRange.new(0.6, 1.8), SpreadAngle = Vector2.new(180, 180),
				Size = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(0.2, 0.45), NumberSequenceKeypoint.new(1, 0),
				}),
				LightEmission = 1, Acceleration = Vector3.new(0, 0.9, 0), Drag = 1.2,
				Transparency = fadeSequence(0.1, 1), Rotation = NumberRange.new(0, 360), RotSpeed = NumberRange.new(-40, 40),
			})
		end
		auraBurstEmitter = createEmitter(hrp, burstLayer)
		if humanoid then
			auraStateConnection = humanoid.StateChanged:Connect(function(_, newState)
				if newState == Enum.HumanoidStateType.Jumping or newState == Enum.HumanoidStateType.Landed then
					auraBurstStart = os.clock()
					if auraBurstEmitter then
						auraBurstEmitter:Emit(newState == Enum.HumanoidStateType.Landed and 28 or 16)
					end
				end
			end)
		end
		local lightConfig = definition.light or {}
		auraLight = Instance.new("PointLight")
