	function scheduleAuraReapply()
		auraApplyToken = auraApplyToken + 1
		local token = auraApplyToken
		task.delay(0.3, function()
			if token == auraApplyToken and not scriptDestroyed then applyAura(true) end
		end)
	end
	local function orbitPosition(orb, group, origin, clock, scale)
		local angle = clock * group.speed + orb.offset
		local phase = 1
		local height
		if group.helix then
			phase = (clock * group.helix + orb.fraction) % 1
			height = ((group.height or 0) + phase * group.helixRange - group.helixRange / 2) * scale
		else
			height = ((group.height or 0) + math.sin(clock * (group.bobSpeed or 2) + orb.phase) * (group.bob or 0)) * scale
		end
		local radius = group.radius * scale
		if group.helix and group.radiusMin then
			radius = radius * (group.radiusMin + (1 - group.radiusMin) * phase)
		end
		radius = radius + math.sin(clock * (group.wobbleSpeed or 3) + orb.phase) * (group.wobble or 0) * scale
		local flat = Vector3.new(math.cos(angle) * radius, 0, math.sin(angle) * radius * (group.ellipse or 1))
		local rotation = orb.rotation
		if group.plane and group.plane.spin then
			rotation = CFrame.Angles(0, math.rad(group.plane.spin) * clock, 0) * rotation
		end
		return origin + rotation * flat + Vector3.new(0, height, 0)
	end
	local function wingPosition(orb, group, hrp, clock, scale)
		local ratio = (orb.featherIndex - 1) / math.max(group.feathers - 1, 1)
		local flap = math.sin(clock * group.flapSpeed - ratio * 0.6) * math.rad(group.flapRange)
		local angle = math.rad(group.baseAngle + group.spread * ratio) + flap
		local reach = group.length * scale * (0.5 + 0.5 * ratio)
		local localPoint = Vector3.new(
			orb.side * (scale + reach * math.cos(angle)),
			group.baseHeight * scale + reach * math.sin(angle),
			group.backOffset * scale
		)
		return hrp.CFrame:PointToWorldSpace(localPoint)
	end
	local function chainPosition(orb, group, origin, clock, scale)
		local angle = clock * group.speed - orb.chainIndex * group.step
		local radius = group.radius * scale
		local height = ((group.height or 0) + math.sin(clock * group.vSpeed - orb.chainIndex * group.vStep) * group.heightRange) * scale
		return origin + Vector3.new(math.cos(angle) * radius, height, math.sin(angle) * radius)
	end
	local auraUpdateConnection = safeConnect(runService.RenderStepped, "auraUpdate", function(dt)
		if scriptDestroyed or not auraDefinition then return end
		local character = localPlayer.Character
		local hrp = character and character:FindFirstChild("HumanoidRootPart")
		if not hrp then return end
		auraClock = auraClock + dt * config.auraSpeed
		local now = os.clock()
		local scale = auraScaleApplied
		local origin = hrp.Position
		for _, orb in ipairs(auraOrbs) do
			local group = orb.group
			local position
			if group.mode == "wing" then
				position = wingPosition(orb, group, hrp, auraClock, scale)
			elseif group.mode == "chain" then
				position = chainPosition(orb, group, origin, auraClock, scale)
			else
				position = orbitPosition(orb, group, origin, auraClock, scale)
			end
			orb.part.CFrame = CFrame.new(position)
		end
		QuickButtons.AuraProps.update(origin, auraClock, scale)
		if auraLight then
			auraLight.Brightness = ((auraDefinition.light and auraDefinition.light.brightness) or 2) + math.sin(now * 3) * 0.5
		end
		if auraBloom then
			auraBloom.Intensity = 0.5 + 0.12 * math.sin(now * 1.5)
		end
		if auraHighlight and auraDefinition.glow then
			auraHighlight.FillTransparency = math.clamp(auraDefinition.glow.fill + math.sin(now * 2) * 0.05, 0, 1)
		end
		if auraRain then
			auraRain.part.CFrame = CFrame.new(origin + Vector3.new(0, auraRain.config.height * scale, 0))
		end
		if auraGround or auraPillar or auraLightning or auraCircle then
			if auraRayCharacter ~= character then
				auraRayCharacter = character
				auraRayParams.FilterDescendantsInstances = { character }
			end
			local result = workspace:Raycast(origin, Vector3.new(0, -12, 0), auraRayParams)
			local groundY = result and result.Position.Y + 0.05 or origin.Y - 3
			if auraGround then
				local radius = auraGround.config.radius * scale
				auraGround.disc.CFrame = CFrame.new(origin.X, groundY, origin.Z) * FLAT_ROTATION
				for index, ripple in ipairs({ auraGround.ripple, auraGround.ripple2 }) do
					local pulse = (now * 0.7 + (index - 1) * 0.5) % 1
					local rippleSize = radius * 2 * (0.15 + 0.85 * pulse)
					ripple.Size = Vector3.new(0.14, rippleSize, rippleSize)
					ripple.Transparency = 0.3 + 0.7 * pulse
					ripple.CFrame = CFrame.new(origin.X, groundY + 0.02 * index, origin.Z) * FLAT_ROTATION
				end
				local burstProgress = math.clamp((now - auraBurstStart) / 0.55, 0, 1)
				if burstProgress < 1 then
					local burstSize = radius * 2 * (0.3 + 1.1 * burstProgress)
					auraGround.burst.Size = Vector3.new(0.16, burstSize, burstSize)
					auraGround.burst.CFrame = CFrame.new(origin.X, groundY + 0.05, origin.Z) * FLAT_ROTATION
					auraGround.burst.Transparency = 0.2 + 0.8 * burstProgress
				else
					auraGround.burst.Transparency = 1
				end
			end
			if auraCircle then
				local cx, cy, cz = origin.X, groundY + 0.07, origin.Z
				for _, dot in ipairs(auraCircle.dots) do
					local angle = dot.angle + now * dot.speed
					dot.part.CFrame = CFrame.new(cx + math.cos(angle) * dot.ring, cy, cz + math.sin(angle) * dot.ring)
					local chase = 0.5 + 0.5 * math.sin(angle * 3 - now * 3 + dot.phase)
					dot.part.Transparency = 0.1 + 0.6 * chase
				end
				local star = auraCircle.radius * 0.8
				for _, line in ipairs(auraCircle.lines) do
					local spin = now * 0.28 + (line.triangle == 2 and math.pi / 3 or 0)
					local angleA = spin + (line.side - 1) * (math.pi * 2 / 3)
					local angleB = spin + line.side * (math.pi * 2 / 3)
					local pointA = Vector3.new(cx + math.cos(angleA) * star, cy, cz + math.sin(angleA) * star)
					local pointB = Vector3.new(cx + math.cos(angleB) * star, cy, cz + math.sin(angleB) * star)
					line.part.Size = Vector3.new(0.1, 0.06, (pointB - pointA).Magnitude)
					line.part.CFrame = CFrame.lookAt(pointA:Lerp(pointB, 0.5), pointB)
				end
			end
			if auraPillar then
				local height = auraPillar.config.height * scale
				auraPillar.part.CFrame = CFrame.new(origin.X, groundY + height / 2, origin.Z) * FLAT_ROTATION
				auraPillar.part.Transparency = math.clamp(auraPillar.config.transparency + math.sin(now * 3) * 0.04, 0, 1)
			end
			if auraLightning and now >= auraLightning.nextStrike then
				local strike = auraLightning
				local angle = math.random() * math.pi * 2
				local distance = math.random() * strike.config.radius * scale
				local ground = Vector3.new(origin.X + math.cos(angle) * distance, groundY, origin.Z + math.sin(angle) * distance)
				strike.bottom.CFrame = CFrame.new(ground)
				strike.top.CFrame = CFrame.new(ground + Vector3.new(math.random(-3, 3), strike.config.height * scale, math.random(-3, 3)))
				strike.beam.CurveSize0 = (math.random() - 0.5) * 8 * scale
				strike.beam.CurveSize1 = (math.random() - 0.5) * 8 * scale
				strike.beam.Enabled = true
				local beam = strike.beam
				task.delay(0.12, function()
					if beam.Parent then beam.Enabled = false end
				end)
				strike.nextStrike = now + strike.config.interval * (0.6 + math.random() * 0.8)
			end
		end
	end)
	local auraRainbowConnection = safeConnect(runService.Heartbeat, "auraRainbow", function()
		if scriptDestroyed or not config.auraRainbow or #auraTargets == 0 then return end
		local hue = (tick() % 3) / 3
		setAuraColor(Color3.fromHSV(hue, 1, 1), Color3.fromHSV((hue + 0.2) % 1, 1, 1))
	end)
	registerCleanup(function()
		auraUpdateConnection:Disconnect()
		auraRainbowConnection:Disconnect()
		clearAura()
	end)
end
local HALO_MODES, setHaloEnabled
do
	HALO_MODES = { "Rainbow", "Angel", "Fire", "Custom" }
	local HALO_ANGEL_COLOR = Color3.fromRGB(255, 235, 140)
	local haloModel = nil
	local haloCenter = nil
	local haloParts = {}
	local haloJoints = {}
	local haloPositions = {}
	local haloColors = {}
	local haloRotation = 0
	local function createHaloPart(shape)
		local part = Instance.new("Part")
		part.Material = Enum.Material.Neon
		part.Shape = shape
		part.CanCollide = false
		part.CanQuery = false
		part.CanTouch = false
		part.CastShadow = false
		part.Anchored = true
		part.Parent = haloModel
		return part
	end
	local function adjustHaloSegments(targetCount)
		while #haloParts < targetCount do
			table.insert(haloParts, createHaloPart(Enum.PartType.Cylinder))
			table.insert(haloJoints, createHaloPart(Enum.PartType.Ball))
		end
		while #haloParts > targetCount do
			table.remove(haloParts):Destroy()
			table.remove(haloJoints):Destroy()
		end
	end
	local function destroyHalo()
		if haloModel then haloModel:Destroy() end
		haloModel = nil
		haloCenter = nil
		table.clear(haloParts)
		table.clear(haloJoints)
	end
	local function createHalo()
		destroyHalo()
		haloModel = Instance.new("Model")
		haloModel.Name = "TCSHubMiniHalo"
		haloModel.Parent = workspace.CurrentCamera or workspace
		haloCenter = Instance.new("Part")
		haloCenter.Size = Vector3.new(0.1, 0.1, 0.1)
		haloCenter.Transparency = 1
		haloCenter.CanCollide = false
		haloCenter.CanQuery = false
		haloCenter.CanTouch = false
		haloCenter.Anchored = true
		haloCenter.Parent = haloModel
		haloModel.PrimaryPart = haloCenter
		adjustHaloSegments(config.haloSegments)
	end
	function setHaloEnabled(state)
		config.haloEnabled = state
		if state then createHalo() else destroyHalo() end
	end
	local function haloSegmentColor(mode, ratio, angle, now)
		if mode == "Rainbow" then
			return Color3.fromHSV((now * 0.15 + ratio) % 1, 1, 1), math.sin(now * 3 + angle * 2) * 0.05
		elseif mode == "Angel" then
			return HALO_ANGEL_COLOR, math.sin(now * 1.2 + angle) * 0.02
		elseif mode == "Fire" then
			local hue = 0.02 + math.sin(now * 4 + angle * config.haloPoints) * 0.04
			return Color3.fromHSV(hue, 0.95, 1), math.sin(now * 6 + angle * config.haloPoints) * 0.14
		end
		return config.haloColor, math.sin(now * 2 + angle * 2) * 0.03
	end
	local haloConnection = safeConnect(runService.RenderStepped, "haloConnection", function(dt)
		if scriptDestroyed or not config.haloEnabled or not haloModel or not haloModel.Parent then return end
		local character = localPlayer.Character
		local head = character and character:FindFirstChild("Head")
		if not head then return end
		adjustHaloSegments(config.haloSegments)
		local segmentCount = #haloParts
		local now = tick()
		haloRotation = (haloRotation + dt * config.haloSpeed) % (math.pi * 2)
		local yOffset = config.haloHeight + math.sin(now * 2.5) * 0.08
		haloCenter.CFrame = head.CFrame * CFrame.new(0, yOffset, 0) * CFrame.Angles(0, haloRotation, 0)
		for index = 1, segmentCount + 1 do
			local ratio = index / segmentCount
			local angle = ratio * math.pi * 2
			local color, wave = haloSegmentColor(config.haloMode, ratio, angle, now)
			haloPositions[index] = haloCenter.CFrame * Vector3.new(
				math.cos(angle) * config.haloRadius, wave, math.sin(angle) * config.haloRadius
			)
			haloColors[index] = color
		end
		local ballSize = config.haloThickness + 0.04
		for index = 1, segmentCount do
			local pointA = haloPositions[index]
			local pointB = haloPositions[index + 1]
			local color = haloColors[index]
			local joint = haloJoints[index]
			joint.Size = Vector3.one * ballSize
			joint.CFrame = CFrame.new(pointA)
			joint.Color = color
			local cylinder = haloParts[index]
			cylinder.Size = Vector3.new((pointB - pointA).Magnitude + 0.01, config.haloThickness, config.haloThickness)
			cylinder.CFrame = CFrame.lookAt(pointA:Lerp(pointB, 0.5), pointB) * CFrame.Angles(0, math.rad(90), 0)
			cylinder.Color = color
		end
	end)
	registerCleanup(function()
		haloConnection:Disconnect()
		destroyHalo()
	end)
end
