		end
		for handle, transparency in pairs(accessoryBackup) do
			if handle.Parent then handle.Transparency = transparency end
		end
		table.clear(bodyBackup)
		table.clear(accessoryBackup)
	end
	local skinConnection = safeConnect(runService.Heartbeat, "skin", function()
		if scriptDestroyed or not config.skinEnabled then return end
		local now = tick()
		local interval = config.skinRainbow and 0.05 or 1
		if now - lastBodyApply < interval then return end
		lastBodyApply = now
		applyBodyLook()
	end)
	registerCleanup(function()
		skinConnection:Disconnect()
		restoreBodyLook()
	end)
	local marketplaceService = game:GetService("MarketplaceService")
	local ASSET_TYPE_PROPERTIES = {
		[8] = "HatAccessory", [41] = "HairAccessory", [42] = "FaceAccessory", [43] = "NeckAccessory",
		[44] = "ShouldersAccessory", [45] = "FrontAccessory", [46] = "BackAccessory", [47] = "WaistAccessory",
		[11] = "Shirt", [12] = "Pants", [2] = "GraphicTShirt", [18] = "Face", [17] = "Head",
		[27] = "Torso", [28] = "RightArm", [29] = "LeftArm", [30] = "LeftLeg", [31] = "RightLeg",
	}
	local ASSET_TYPE_NAMES = {
		[8] = "Chapeu", [41] = "Cabelo", [42] = "Acessorio de rosto", [43] = "Acessorio de pescoco",
		[44] = "Acessorio de ombro", [45] = "Acessorio da frente", [46] = "Acessorio das costas",
		[47] = "Acessorio da cintura", [11] = "Camisa", [12] = "Calca", [2] = "Camiseta", [18] = "Rosto",
		[17] = "Cabeca", [27] = "Torso", [28] = "Braco direito", [29] = "Braco esquerdo",
		[30] = "Perna esquerda", [31] = "Perna direita",
	}
	function extractAssetIds(input)
		local ids = {}
		local text = tostring(input or "")
		if text:find("roblox.com", 1, true) then
			local id = text:match("/catalog/(%d+)") or text:match("/library/(%d+)") or text:match("[?&]id=(%d+)")
			if id then table.insert(ids, id) end
			return ids
		end
		for id in text:gmatch("%d%d%d%d+") do
			table.insert(ids, id)
			if #ids >= 10 then break end
		end
		return ids
	end
	local function getAssetInfo(assetId)
		local ok, info = pcall(function()
			return marketplaceService:GetProductInfo(tonumber(assetId), Enum.InfoType.Asset)
		end)
		if ok and type(info) == "table" then return info end
		return nil
	end
	local function loadAssetObjects(assetId)
		local assetUrl = "rbxassetid://" .. assetId
		local ok, result = pcall(function() return game:GetObjects(assetUrl) end)
		if ok and type(result) == "table" and #result > 0 then return result end
		if getobjects then
			ok, result = pcall(getobjects, game, assetUrl)
			if ok and type(result) == "table" and #result > 0 then return result end
		end
		return nil
	end
	local function attachAccessory(character, humanoid, accessory)
		pcall(function() humanoid:AddAccessory(accessory) end)
		local handle = accessory:FindFirstChild("Handle")
		if not (handle and handle:IsA("BasePart")) then
			accessory.Parent = character
			return
		end
		handle.Anchored = false
		handle.CanCollide = false
		local isAttached = accessory.Parent == character and (
			handle:FindFirstChild("AccessoryWeld")
			or handle:FindFirstChildWhichIsA("JointInstance")
			or handle:FindFirstChildWhichIsA("WeldConstraint")
		)
		if isAttached then return end
		accessory.Parent = character
		local attachment = handle:FindFirstChildOfClass("Attachment")
		local target = attachment and character:FindFirstChild(attachment.Name, true)
		local weld = Instance.new("Weld")
		weld.Name = "AccessoryWeld"
		weld.Part1 = handle
		weld.Parent = handle
		if target and target:IsA("Attachment") then
			handle.CFrame = target.WorldCFrame * (attachment and attachment.CFrame:Inverse() or CFrame.new())
			weld.Part0 = target.Parent
			weld.C0 = target.CFrame
			weld.C1 = attachment and attachment.CFrame or CFrame.new()
		else
			local head = character:FindFirstChild("Head")
			if not head then
				weld:Destroy()
				return
			end
			handle.CFrame = head.CFrame * CFrame.new(0, head.Size.Y / 2, 0) * accessory.AttachmentPoint:Inverse()
			weld.Part0 = head
			weld.C0 = head.CFrame:ToObjectSpace(handle.CFrame)
			weld.C1 = CFrame.new()
		end
	end
	local function appearanceSignature(character)
		local parts = {}
		for _, child in ipairs(character:GetChildren()) do
			if child:IsA("Accessory") then
				table.insert(parts, "A:" .. child.Name)
			elseif child:IsA("Shirt") then
				table.insert(parts, "S:" .. tostring(child.ShirtTemplate))
			elseif child:IsA("Pants") then
				table.insert(parts, "P:" .. tostring(child.PantsTemplate))
			elseif child:IsA("ShirtGraphic") then
				table.insert(parts, "G:" .. tostring(child.Graphic))
			end
		end
		local head = character:FindFirstChild("Head")
		local face = head and head:FindFirstChildOfClass("Decal")
		if face then table.insert(parts, "F:" .. tostring(face.Texture)) end
		table.sort(parts)
		return table.concat(parts, "|")
	end
	local function waitForChange(character, before, seconds)
		local deadline = tick() + seconds
		repeat
			task.wait(0.15)
			if appearanceSignature(character) ~= before then return true end
		until tick() >= deadline
		return false
	end
	local function applyViaObjects(character, humanoid, assetId)
		local objects = loadAssetObjects(assetId)
		if not objects then return 0 end
		local items = {}
		for _, object in ipairs(objects) do
			table.insert(items, object)
			for _, descendant in ipairs(object:GetDescendants()) do
				table.insert(items, descendant)
			end
		end
		local applied = 0
		for _, item in ipairs(items) do
			if item:IsA("Shirt") or item:IsA("Pants") or item:IsA("ShirtGraphic") then
				for _, child in ipairs(character:GetChildren()) do
					if child.ClassName == item.ClassName then child:Destroy() end
				end
				item.Parent = character
				applied = applied + 1
			elseif item:IsA("Accessory") then
				attachAccessory(character, humanoid, item)
				applied = applied + 1
			elseif item:IsA("Decal") and item.Name == "face" then
				local head = character:FindFirstChild("Head")
				if head then
					local oldFace = head:FindFirstChildOfClass("Decal")
					if oldFace then oldFace:Destroy() end
					item.Parent = head
					applied = applied + 1
				end
			end
		end
		return applied
	end
	local function applyViaTemplate(character, assetId, info)
		local assetTypeId = info.AssetTypeId
		if assetTypeId ~= 11 and assetTypeId ~= 12 and assetTypeId ~= 2 then return false end
		local numericId = tonumber(assetId)
		local creatorId = info.Creator and info.Creator.Id
		local template = nil
		for _, candidate in ipairs({ numericId - 1, numericId + 1, numericId - 2, numericId + 2 }) do
			local candidateInfo = getAssetInfo(tostring(candidate))
			if candidateInfo and candidateInfo.AssetTypeId == 1
				and candidateInfo.Creator and candidateInfo.Creator.Id == creatorId then
				template = candidate
				break
			end
		end
		if not template then return false end
		local className = assetTypeId == 11 and "Shirt" or (assetTypeId == 12 and "Pants" or "ShirtGraphic")
		for _, child in ipairs(character:GetChildren()) do
			if child.ClassName == className then child:Destroy() end
		end
		local clothing = Instance.new(className)
		local url = "rbxassetid://" .. template
		if className == "Shirt" then
			clothing.ShirtTemplate = url
		elseif className == "Pants" then
			clothing.PantsTemplate = url
		else
			clothing.Graphic = url
		end
		clothing.Parent = character
		return true
	end
	local function applyViaDescription(humanoid, assetId, assetTypeId)
		local property = ASSET_TYPE_PROPERTIES[assetTypeId]
		if not property then return false end
		return (pcall(function()
			local description = humanoid:GetAppliedDescription()
			if property:find("Accessory") then
				local current = description[property]
				description[property] = (current ~= nil and current ~= "") and (current .. "," .. assetId) or tostring(assetId)
			else
				description[property] = tonumber(assetId)
			end
			humanoid:ApplyDescription(description)
		end))
	end
	function applyAssetById(input)
		local character = localPlayer.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		if not humanoid then return false, "Personagem nao encontrado" end
		local ids = extractAssetIds(input)
		if #ids == 0 then return false, "Nenhum ID valido (use o numero do item ou o link do catalogo)" end
		local results = {}
		local successCount = 0
		for _, assetId in ipairs(ids) do
			local info = getAssetInfo(assetId)
			local itemName = info and info.Name or ("ID " .. assetId)
			local typeName = info and ASSET_TYPE_NAMES[info.AssetTypeId]
			local typeText = typeName and (" (" .. typeName .. ")") or ""
			if info == nil then
				table.insert(results, itemName .. ": item nao encontrado no catalogo")
			else
				local before = appearanceSignature(character)
				local method = nil
				if applyViaObjects(character, humanoid, assetId) > 0 and waitForChange(character, before, 1) then
					method = "objeto"
				elseif applyViaTemplate(character, assetId, info) and waitForChange(character, before, 1) then
					method = "textura"
				elseif applyViaDescription(humanoid, assetId, info.AssetTypeId) and waitForChange(character, before, 2.5) then
					method = "descricao"
				end
				if method then
					successCount = successCount + 1
					table.insert(results, "Aplicado: " .. itemName .. typeText .. " [" .. method .. "]")
				else
					table.insert(results, itemName .. typeText .. ": nada mudou no personagem (o jogo pode estar bloqueando ou o tipo nao e suportado)")
				end
			end
		end
		return successCount > 0, table.concat(results, " | ")
	end
	function removeClothing()
		local character = localPlayer.Character
		if not character then return 0 end
		local removed = 0
		for _, child in ipairs(character:GetChildren()) do
			if child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then
				child:Destroy()
				removed = removed + 1
			end
		end
		return removed
	end
	function removeAccessories()
		local character = localPlayer.Character
		if not character then return 0 end
		local removed = 0
		for _, child in ipairs(character:GetChildren()) do
			if child:IsA("Accessory") then
				child:Destroy()
				removed = removed + 1
			end
		end
		return removed
	end
	function getOtherPlayerNames()
		local names = {}
		for _, otherPlayer in ipairs(players:GetPlayers()) do
			if otherPlayer ~= localPlayer then table.insert(names, otherPlayer.Name) end
		end
		table.sort(names)
		if #names == 0 then names = { "(ninguem)" } end
		return names
	end
	function applyMorph(usernameOrId)
		local character = localPlayer.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		if not (character and humanoid and usernameOrId and usernameOrId ~= "") then
			return false, "Personagem ou entrada invalida"
		end
		local targetUserId = tonumber(usernameOrId)
		if not targetUserId then
			local ok, result = pcall(function()
				return players:GetUserIdFromNameAsync(usernameOrId)
			end)
			if not ok then return false, "Usuario nao encontrado" end
			targetUserId = result
		end
		local rigType = humanoid.RigType == Enum.HumanoidRigType.R15 and Enum.HumanoidRigType.R15 or Enum.HumanoidRigType.R6
		local ok, generatedModel = pcall(function()
			local description = players:GetHumanoidDescriptionFromUserId(targetUserId)
			return players:CreateHumanoidModelFromDescription(description, rigType)
		end)
		if not (ok and generatedModel) then
			return false, "Falha ao gerar aparencia"
		end
		for _, item in ipairs(character:GetChildren()) do
			if item:IsA("Accessory") or item:IsA("Clothing") or item:IsA("ShirtGraphic") or item:IsA("BodyColors") or item:IsA("CharacterMesh") then
				item:Destroy()
			end
		end
		for _, targetPart in ipairs(generatedModel:GetChildren()) do
			local existingPart = character:FindFirstChild(targetPart.Name)
			if existingPart and existingPart:IsA("BasePart") and existingPart.Name ~= "HumanoidRootPart" then
				existingPart.Color = targetPart.Color
			end
		end
		local targetHead = generatedModel:FindFirstChild("Head")
		local currentHead = character:FindFirstChild("Head")
		if targetHead and currentHead then
			local oldFace = currentHead:FindFirstChildOfClass("Decal")
			if oldFace then oldFace:Destroy() end
			local newFace = targetHead:FindFirstChildOfClass("Decal")
			if newFace then
				newFace:Clone().Parent = currentHead
			else
				local defaultFace = Instance.new("Decal")
				defaultFace.Name = "face"
				defaultFace.Texture = "rbxasset://textures/face.png"
				defaultFace.Parent = currentHead
			end
			local oldMesh = currentHead:FindFirstChildOfClass("SpecialMesh")
			if oldMesh then oldMesh:Destroy() end
			local newMesh = targetHead:FindFirstChildOfClass("SpecialMesh")
			if newMesh then newMesh:Clone().Parent = currentHead end
		end
		for _, item in ipairs(generatedModel:GetChildren()) do
			if item:IsA("Clothing") or item:IsA("ShirtGraphic") or item:IsA("BodyColors") or item:IsA("CharacterMesh") then
				item:Clone().Parent = character
			elseif item:IsA("Accessory") then
				local clonedAccessory = item:Clone()
				local handle = clonedAccessory:FindFirstChild("Handle")
				if handle then
					local attachment = handle:FindFirstChildOfClass("Attachment")
					if attachment then
						local targetAttachment = character:FindFirstChild(attachment.Name, true)
						if targetAttachment then
							handle.CFrame = targetAttachment.WorldCFrame
							local weld = Instance.new("Weld")
							weld.Name = "AccessoryWeld"
							weld.Part0 = handle
							weld.Part1 = targetAttachment.Parent
							weld.C0 = attachment.CFrame
							weld.C1 = targetAttachment.CFrame
							weld.Parent = handle
						end
					end
				end
				clonedAccessory.Parent = character
			end
		end
		generatedModel:Destroy()
		return true, "Morph aplicado"
	end
end
