	SKY_PRESET_NAMES = {
		"Nenhum", "Dia Claro", "Por do Sol", "Amanhecer", "Noite Estrelada", "Espaco", "Neon Roxo", "Neon Vermelho",
		"Cyber", "Oceano", "Nevoeiro", "Aurora", "Nether", "The End",
		"Vaporwave (imagem)", "Cherry Blossom (imagem)", "Golden Hour (imagem)", "Neon City (imagem)",
	}
	local worldBackup = nil
	local hiddenOriginals = {}
	local currentPreset = nil
	local currentImageId = nil
	local lastLockCheck = 0
	local function isOurs(instance)
		return instance.Name:sub(1, #OUR_PREFIX) == OUR_PREFIX
	end
	local function backupWorld()
		if worldBackup then return end
		worldBackup = {}
		for _, property in ipairs(LIGHTING_PROPS) do
			pcall(function() worldBackup[property] = lighting[property] end)
		end
	end
	local function removeOurInstances()
		for _, child in ipairs(lighting:GetChildren()) do
			if isOurs(child) then child:Destroy() end
		end
	end
	local function hideOriginalSky()
		for _, child in ipairs(lighting:GetChildren()) do
			if (child:IsA("Sky") or child:IsA("Atmosphere")) and not isOurs(child) then
				hiddenOriginals[child] = true
				child.Parent = nil
			end
		end
	end
	local function setPresetLighting(preset, skipClock)
		if not skipClock then lighting.ClockTime = preset.clock or 14 end
		lighting.Brightness = preset.brightness or 2
		lighting.Ambient = preset.ambient or rgb(128, 128, 128)
		lighting.OutdoorAmbient = preset.outdoor or rgb(128, 128, 128)
		lighting.FogColor = preset.fogColor or rgb(192, 192, 192)
		lighting.FogStart = preset.fogStart or 0
		lighting.FogEnd = preset.fogEnd or 100000
		if preset.shadows ~= nil then lighting.GlobalShadows = preset.shadows end
	end
	local function buildSky(imageUrl, stars)
		local sky = Instance.new("Sky")
		sky.Name = OUR_PREFIX .. "Sky"
		if imageUrl then
			for _, face in ipairs(SKY_FACES) do
				sky[face] = imageUrl
			end
		end
		sky.StarCount = stars
		sky.CelestialBodiesShown = true
		sky.Parent = lighting
	end
	local function buildEffects(preset)
		if preset.atmosphere then
			local atmosphere = Instance.new("Atmosphere")
			atmosphere.Name = OUR_PREFIX .. "Atmosphere"
			atmosphere.Density = preset.atmosphere.density
			atmosphere.Color = preset.atmosphere.color
			atmosphere.Glare = preset.atmosphere.glare
			atmosphere.Haze = preset.atmosphere.haze
			atmosphere.Parent = lighting
		end
		if preset.correction then
			local correction = Instance.new("ColorCorrectionEffect")
			correction.Name = OUR_PREFIX .. "Correction"
			correction.TintColor = preset.correction.tint or rgb(255, 255, 255)
			correction.Saturation = preset.correction.saturation or 0
			correction.Contrast = preset.correction.contrast or 0
			correction.Parent = lighting
		end
		if preset.bloom then
			local bloom = Instance.new("BloomEffect")
			bloom.Name = OUR_PREFIX .. "Bloom"
			bloom.Intensity = preset.bloom.intensity
			bloom.Size = preset.bloom.size
			bloom.Threshold = preset.bloom.threshold
			bloom.Parent = lighting
		end
	end
	function restoreWorld()
		removeOurInstances()
		for instance in pairs(hiddenOriginals) do
			pcall(function() instance.Parent = lighting end)
		end
		table.clear(hiddenOriginals)
		if worldBackup then
			for property, value in pairs(worldBackup) do
				pcall(function() lighting[property] = value end)
			end
		end
		worldBackup = nil
		currentPreset = nil
		currentImageId = nil
	end
	function applySkyPreset(name)
		local preset = SKY_PRESETS[name]
		if not preset then
			restoreWorld()
			return
		end
		backupWorld()
		removeOurInstances()
		hideOriginalSky()
		setPresetLighting(preset, config.worldClockOn)
		buildSky(preset.image, preset.stars or config.skyStars)
		buildEffects(preset)
		currentPreset = name
		currentImageId = nil
	end
	function applySkyImageId(idText)
		local assetId = tostring(idText or ""):match("%d+")
		if not assetId then return false end
		backupWorld()
		removeOurInstances()
		hideOriginalSky()
		buildSky("rbxassetid://" .. assetId, config.skyStars)
		currentPreset = nil
		currentImageId = idText
		return true
	end
	function setSkyStars(count)
		config.skyStars = count
		local sky = lighting:FindFirstChild(OUR_PREFIX .. "Sky")
		if sky then sky.StarCount = count end
	end
	local originalShadows = nil
	function setWorldShadows(state)
		if originalShadows == nil then originalShadows = lighting.GlobalShadows end
		config.worldShadows = state
		lighting.GlobalShadows = state
	end
	local worldConnection = safeConnect(runService.Heartbeat, "world", function(dt)
		if scriptDestroyed then return end
		if config.worldClockOn then
			if config.worldCycle > 0 then
				config.worldClock = (config.worldClock + dt * config.worldCycle) % 24
			end
			lighting.ClockTime = config.worldClock
		end
		if not config.skyLock or not (currentPreset or currentImageId) then return end
		local now = tick()
		if now - lastLockCheck < 0.5 then return end
		lastLockCheck = now
		if not lighting:FindFirstChild(OUR_PREFIX .. "Sky") then
			if currentPreset then
				applySkyPreset(currentPreset)
			else
				applySkyImageId(currentImageId)
			end
			return
		end
		hideOriginalSky()
		local preset = currentPreset and SKY_PRESETS[currentPreset]
		if preset then setPresetLighting(preset, config.worldClockOn) end
	end)
	local GRASS_COLORS = {
		["Classic"] = rgb(40, 160, 60), ["Neon"] = rgb(40, 255, 80), ["Aqua"] = rgb(30, 170, 150),
		["Roxo"] = rgb(130, 60, 180), ["Rosa"] = rgb(220, 70, 140), ["Escuro"] = rgb(20, 70, 30),
		["Gelo"] = rgb(80, 190, 180),
	}
	GRASS_PRESET_NAMES = { "Original", "Classic", "Neon", "Aqua", "Roxo", "Rosa", "Escuro", "Gelo" }
	local GRASS_NAME_HINTS = { "grass", "field", "pitch", "campo", "grama" }
	local grassParts = nil
	local lastGrassScan = 0
	local grassScanning = false
	local grassBackup = setmetatable({}, { __mode = "k" })
	local function looksLikeGrass(instance)
		if not instance:IsA("BasePart") then return false end
		local lowerName = instance.Name:lower()
		for _, hint in ipairs(GRASS_NAME_HINTS) do
			if lowerName:find(hint, 1, true) then return true end
		end
		return false
	end
	local function scanGrass()
		if grassScanning then return end
		grassScanning = true
		pcall(function()
			local found = {}
			for index, descendant in ipairs(workspace:GetDescendants()) do
				if looksLikeGrass(descendant) and not descendant:IsDescendantOf(workspace.CurrentCamera) then
					table.insert(found, descendant)
				end
				if index % 300 == 0 then task.wait() end
			end
			grassParts = found
			lastGrassScan = tick()
		end)
		grassScanning = false
	end
	local function restoreGrass()
		for part, backup in pairs(grassBackup) do
			if part.Parent then
				part.Color = backup.color
				part.Material = backup.material
			end
		end
		table.clear(grassBackup)
	end
	function applyGrassPreset(name)
		local color = GRASS_COLORS[name]
		if not color then
			restoreGrass()
			return
		end
		task.spawn(function()
			if not grassParts or tick() - lastGrassScan > 60 then scanGrass() end
			for _, part in ipairs(grassParts or {}) do
				if part.Parent then
					if not grassBackup[part] then
						grassBackup[part] = { color = part.Color, material = part.Material }
					end
					part.Color = color
				end
			end
		end)
	end
	local fpsBackup = setmetatable({}, { __mode = "k" })
	local fpsOriginalQuality = nil
	local fpsBoostActive = false
	local shadowsBeforeBoost = nil
	local function isBoostTarget(instance)
		return instance:IsA("ParticleEmitter") or instance:IsA("Trail") or instance:IsA("Smoke")
			or instance:IsA("Fire") or instance:IsA("Sparkles") or instance:IsA("Beam")
	end
	local function restoreFpsBoost()
		if not fpsBoostActive then return end
		fpsBoostActive = false
		for instance, wasEnabled in pairs(fpsBackup) do
			if instance.Parent then instance.Enabled = wasEnabled end
		end
		table.clear(fpsBackup)
		pcall(function()
			if fpsOriginalQuality then settings().Rendering.QualityLevel = fpsOriginalQuality end
		end)
		fpsOriginalQuality = nil
		if shadowsBeforeBoost ~= nil then lighting.GlobalShadows = shadowsBeforeBoost end
		shadowsBeforeBoost = nil
	end
	function setFpsBoost(state)
		config.fpsBoostOn = state
		if not state then
			restoreFpsBoost()
			return
		end
		fpsBoostActive = true
		shadowsBeforeBoost = lighting.GlobalShadows
		pcall(function()
			fpsOriginalQuality = settings().Rendering.QualityLevel
			settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
		end)
		lighting.GlobalShadows = false
		task.spawn(function()
			local character = localPlayer.Character
			for index, instance in ipairs(workspace:GetDescendants()) do
				if not config.fpsBoostOn then return end
				if isBoostTarget(instance)
					and not (character and instance:IsDescendantOf(character))
					and not instance:IsDescendantOf(workspace.CurrentCamera) then
					if fpsBackup[instance] == nil then fpsBackup[instance] = instance.Enabled end
					instance.Enabled = false
				end
				if index % 300 == 0 then task.wait() end
			end
		end)
	end
	local cameraConnection = safeConnect(runService.RenderStepped, "camera", function()
		local currentCamera = workspace.CurrentCamera
		if not currentCamera or scriptDestroyed then return end
		if not (config.stretchOn or config.fovOn) then return end
		if config.stretchOn and currentCamera.FieldOfViewMode ~= Enum.FieldOfViewMode.MaxAxis then
			currentCamera.FieldOfViewMode = Enum.FieldOfViewMode.MaxAxis
		end
		if config.fovOn and currentCamera.FieldOfView ~= config.fov then
			currentCamera.FieldOfView = config.fov
		end
	end)
	function setFov(state)
		config.fovOn = state
		local currentCamera = workspace.CurrentCamera
		if not state and currentCamera then currentCamera.FieldOfView = 70 end
	end
	function setStretch(state)
		config.stretchOn = state
		local currentCamera = workspace.CurrentCamera
		if not state and currentCamera then currentCamera.FieldOfViewMode = Enum.FieldOfViewMode.Diagonal end
	end
	registerCleanup(function()
		worldConnection:Disconnect()
		cameraConnection:Disconnect()
		restoreWorld()
		restoreGrass()
		restoreFpsBoost()
		if originalShadows ~= nil then lighting.GlobalShadows = originalShadows end
		if config.fovOn then setFov(false) end
		if config.stretchOn then setStretch(false) end
	end)
end
