			meshTextures = {}, decals = {},
		}
		if ball:IsA("MeshPart") then backup.textureId = ball.TextureID end
		for _, child in ipairs(ball:GetChildren()) do
			if child:IsA("SpecialMesh") then
				backup.meshTextures[child] = child.TextureId
			elseif child:IsA("Decal") or child:IsA("Texture") then
