				bead.CastShadow = false
				bead.Parent = ballFolder
				local top = Instance.new("Attachment")
				top.Position = Vector3.new(0, 0.17, 0)
				top.Parent = bead
				local bottom = Instance.new("Attachment")
				bottom.Position = Vector3.new(0, -0.17, 0)
				bottom.Parent = bead
				local beadTrail = Instance.new("Trail")
				beadTrail.Attachment0 = top
				beadTrail.Attachment1 = bottom
				beadTrail.Lifetime = 0.45
				beadTrail.LightEmission = 1
				beadTrail.FaceCamera = true
				beadTrail.Color = ColorSequence.new(currentBallColor())
				beadTrail.Transparency = fade(0.2, 1)
				beadTrail.WidthScale = fade(1, 0)
				beadTrail.Parent = bead
				table.insert(ballObjects, bead)
				table.insert(ballOrbs, bead)
				table.insert(ballOrbTrails, beadTrail)
			end
		end
	end
	local function updateTrail(ball)
		local half = (ball and ball.Size.Y or 2) * 0.45
		trailTop.Position = Vector3.new(0, half, 0)
		trailBottom.Position = Vector3.new(0, -half, 0)
		ballTrail.Lifetime = config.ballTrailLife
		ballTrail.Color = ColorSequence.new(config.ballTrailColor)
		ballTrail.Enabled = config.ballSkinEnabled and config.ballTrailOn and ball ~= nil
	end
	function applyBallLook()
		local ball = findBall()
		if not ball or not config.ballSkinEnabled then return end
		clearBallObjects()
		backupBall(ball)
		appliedBall = ball
		applyBallColors(ball)
		applyBallTexture(ball)
		rebuildBallEffects(ball)
		updateTrail(ball)
	end
	function restoreBallLook()
		clearBallObjects()
		for ball, backup in pairs(ballBackup) do
			if ball.Parent then
				ball.Color = backup.color
				ball.Material = backup.material
				ball.Transparency = backup.transparency
				if backup.textureId ~= nil and ball:IsA("MeshPart") then ball.TextureID = backup.textureId end
				for mesh, textureId in pairs(backup.meshTextures) do
					if mesh.Parent then mesh.TextureId = textureId end
				end
				for decal, transparency in pairs(backup.decals) do
					if decal.Parent then decal.Transparency = transparency end
				end
			end
		end
		table.clear(ballBackup)
		appliedBall = nil
		ballTrail.Enabled = false
	end
	function refreshBallSkin()
		refreshToken = refreshToken + 1
		local token = refreshToken
		task.delay(0.15, function()
			if token == refreshToken and not scriptDestroyed then applyBallLook() end
		end)
	end
	function applyBallPreset(name)
		local preset = BALL_PRESETS[name]
		if not preset then
			config.ballSkinEnabled = false
			restoreBallLook()
			return
		end
		config.ballColor = preset.color
		config.ballMaterial = preset.material
		config.ballTransparency = preset.transparency or 0
		config.ballRainbow = preset.rainbow == true
		config.ballGlowOn = preset.glow ~= false
		config.ballOrbitOn = preset.orbit == true
		config.ballTextureId = ""
		config.ballEffect = preset.effect or "Nenhum"
		config.ballEffectColor = preset.effectColor or preset.color
		config.ballTrailOn = preset.trail ~= nil
		if preset.trail then
			config.ballTrailColor = preset.trail.color
			config.ballTrailLife = preset.trail.life
		end
		config.ballLightOn = preset.light ~= nil
		if preset.light then
			config.ballLightColor = preset.light.color
			config.ballLightRange = preset.light.range
		end
		config.ballSkinEnabled = true
		applyBallLook()
	end
	local ballConnection = safeConnect(runService.RenderStepped, "ballSkin", function(dt)
		if scriptDestroyed then return end
		if not config.ballSkinEnabled then
			if ballTrail.Enabled then ballTrail.Enabled = false end
			return
		end
		local ball = findBall()
		if not ball then return end
		if appliedBall ~= ball then
			applyBallLook()
			return
		end
		trailHelper.CFrame = CFrame.new(ball.Position)
		local now = os.clock()
		local velocity = ball.AssemblyLinearVelocity
		local change = (velocity - lastBallVelocity).Magnitude
		lastBallVelocity = velocity
		if change > 24 and now - lastKick > 0.12 then
			lastKick = now
			kickGlow = math.clamp(change / 60, 0.35, 1)
			if ballBurst then ballBurst:Emit(math.floor(8 + kickGlow * 28)) end
		end
		kickGlow = kickGlow * math.max(0, 1 - (dt or 0.016) * 5)
		if ballLight then ballLight.Brightness = 2 + kickGlow * 6 end
		if ballHighlight then
			ballHighlight.FillTransparency = math.clamp(0.78 + math.sin(now * 2.4) * 0.05 - kickGlow * 0.5, 0.15, 1)
		end
		if #ballOrbs > 0 then
			local orbitRadius = ball.Size.X * 0.5 + 0.9
			for index, bead in ipairs(ballOrbs) do
				local angle = now * 2.4 + index * (math.pi * 2 / #ballOrbs)
				local offset
				if index % 2 == 0 then
					offset = Vector3.new(math.cos(angle) * orbitRadius, math.sin(angle) * orbitRadius * 0.6, math.sin(angle * 0.5) * 0.3)
				else
					offset = Vector3.new(math.cos(angle) * orbitRadius, math.sin(now * 1.7 + index) * 0.4, math.sin(angle) * orbitRadius)
				end
				bead.CFrame = CFrame.new(ball.Position + offset)
			end
		end
		if config.ballRainbow then
			local color = currentBallColor()
			applyBallColors(ball)
			ballTrail.Color = ColorSequence.new(color)
			if ballEmitter then ballEmitter.Color = ColorSequence.new(color) end
			if ballLight then ballLight.Color = color end
			if ballHighlight then ballHighlight.FillColor = color end
			if ballBurst then ballBurst.Color = ColorSequence.new(color) end
			for _, bead in ipairs(ballOrbs) do bead.Color = color end
			for _, beadTrail in ipairs(ballOrbTrails) do beadTrail.Color = ColorSequence.new(color) end
		else
			local now = tick()
			if now - lastColorApply > 0.5 then
				lastColorApply = now
				applyBallColors(ball)
			end
		end
	end)
	registerCleanup(function()
		ballConnection:Disconnect()
		restoreBallLook()
		ballFolder:Destroy()
	end)
end
local characterAddedConnection = localPlayer.CharacterAdded:Connect(function(character)
	character:WaitForChild("Humanoid", 5)
	character:WaitForChild("HumanoidRootPart", 5)
	task.wait(0.3)
	applyAura()
	if config.skinEnabled then applyBodyLook() end
end)
registerCleanup(function() characterAddedConnection:Disconnect() end)
local playGoalSound, GOAL_SOUND_MODES, GOAL_EFFECT_STYLES, testGoalEffect
do
	local SCORE_PATTERN = "^%s*(%d+)%s*[%-\226\128\147]%s*(%d+)%s*$"
	local GOAL_FOLDER = "TCSHubMini/goal"
	local CLIP_NAMES = {
		"First Blood",
		"Double Kill",
		"Triple Kill",
		"Killing Spree",
		"Rampage",
		"Wicked Sick",
		"Ownage",
		"Unstoppable",
		"Dominating",
		"Mega Kill",
		"Godlike",
		"Monsterkill",
		"Ludacris Kill",
	}
	GOAL_SOUND_MODES = { "Sequencia", "Aleatorio" }
	for _, name in ipairs(CLIP_NAMES) do
		table.insert(GOAL_SOUND_MODES, name)
	end
	table.insert(GOAL_SOUND_MODES, "ID personalizado")
	local CLIP_DATA = {
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
	}
	local goalSound = Instance.new("Sound")
	goalSound.Name = "TCSHubGoalSound"
	goalSound.Parent = hubGui
	local clipAssets = {}
	local scoreLabel = nil
	local lastTotal = nil
	local lastScan = 0
	local lastRandom = 0
	local function getClipAsset(index)
		if clipAssets[index] then return clipAssets[index] end
		local decode = (crypt and crypt.base64decode) or base64decode
		local getAsset = getcustomasset or getsynasset
		if not (decode and getAsset and writefile and isfile) then return nil end
		local ok, asset = pcall(function()
			if not (isfolder and isfolder("TCSHubMini")) then pcall(makefolder, "TCSHubMini") end
			if not (isfolder and isfolder(GOAL_FOLDER)) then pcall(makefolder, GOAL_FOLDER) end
			local path = string.format("%s/%02d.mp3", GOAL_FOLDER, index)
			if not isfile(path) then writefile(path, decode(CLIP_DATA[index])) end
			return getAsset(path)
		end)
		if ok and asset then
			clipAssets[index] = asset
			return asset
		end
		return nil
	end
	local function pickClip(goalNumber)
		local mode = config.goalSoundMode
		local fixed = table.find(CLIP_NAMES, mode)
		if fixed then return fixed end
		if mode == "Aleatorio" then
			local index = math.random(1, #CLIP_NAMES)
			if index == lastRandom then index = index % #CLIP_NAMES + 1 end
			lastRandom = index
			return index
		end
		if mode == "ID personalizado" then return nil end
		return math.clamp(goalNumber or 1, 1, #CLIP_NAMES)
	end
	function playGoalSound(goalNumber)
		local soundId
		local index = pickClip(goalNumber)
		if index then
			soundId = getClipAsset(index)
			if not soundId then
				return false, "Seu executor nao suporta arquivos de audio (getcustomasset/writefile)."
			end
		else
			local id = tostring(config.goalSoundId or ""):gsub("%s", "")
			if id == "" then return false, "Digite o ID do som." end
			soundId = tonumber(id) and ("rbxassetid://" .. id) or id
		end
		goalSound.SoundId = soundId
		goalSound.Volume = config.goalSoundVolume
		goalSound:Stop()
		goalSound:Play()
		return true
	end
	local goalEffectBusy = false
	GOAL_EFFECT_STYLES = { "Completo", "Lendario", "Fogos", "Neon", "Minimo" }
	local function playGoalWorld(style)
		local tweens = game:GetService("TweenService")
		local lightingService = game:GetService("Lighting")
		local camera = workspace.CurrentCamera
		local gold = Color3.fromRGB(255, 214, 90)
		local created = {}
		local function track(instance)
			table.insert(created, instance)
			return instance
		end
		local function tween(object, time, goal, easing, direction)
			local item = tweens:Create(object, TweenInfo.new(time, easing or Enum.EasingStyle.Quad, direction or Enum.EasingDirection.Out), goal)
			item:Play()
			return item
		end
		local bloom = track(Instance.new("BloomEffect"))
		bloom.Intensity = 0
		bloom.Size = 40
		bloom.Threshold = 0.6
		bloom.Parent = lightingService
		local color = track(Instance.new("ColorCorrectionEffect"))
		color.Parent = lightingService
		local blur = track(Instance.new("BlurEffect"))
		blur.Size = 0
		blur.Parent = lightingService
		if style ~= "Minimo" then
			local sunRays = track(Instance.new("SunRaysEffect"))
			sunRays.Intensity = 0.4
			sunRays.Spread = 1
			sunRays.Parent = lightingService
			tween(sunRays, 2, { Intensity = 0 })
		end
		bloom.Intensity = 2.2
		color.Saturation = 0.55
		color.Contrast = 0.18
		color.Brightness = 0.12
		color.TintColor = Color3.fromRGB(255, 244, 220)
		blur.Size = 22
		tween(bloom, 1.8, { Intensity = 0 })
		tween(color, 1.8, { Saturation = 0, Contrast = 0, Brightness = 0, TintColor = Color3.new(1, 1, 1) })
		tween(blur, 0.7, { Size = 0 })
		if camera and style ~= "Minimo" then
			pcall(function()
				local baseFov = camera.FieldOfView
				camera.FieldOfView = baseFov - 10
				tween(camera, 0.7, { FieldOfView = baseFov }, Enum.EasingStyle.Quint)
			end)
		end
		local origin
		local ball = findBall and findBall()
		if ball and ball.Parent then
			origin = ball.Position
		else
			local character = localPlayer.Character
			local root = character and character:FindFirstChild("HumanoidRootPart")
			if root then origin = root.Position end
		end
		if origin and style ~= "Minimo" then
			local function newPart(size, shape)
				local part = track(Instance.new("Part"))
				part.Anchored = true
				part.CanCollide = false
				part.CanQuery = false
				part.CanTouch = false
				part.CastShadow = false
				part.Material = Enum.Material.Neon
				part.Size = size
				if shape then part.Shape = shape end
				part.Parent = camera or workspace
				return part
			end
			if ball and ball.Parent then
				local highlight = track(Instance.new("Highlight"))
				highlight.FillColor = gold
				highlight.OutlineColor = Color3.new(1, 1, 1)
				highlight.FillTransparency = 0.2
				highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
				highlight.Adornee = ball
				highlight.Parent = camera or workspace
				tween(highlight, 1.6, { FillTransparency = 1, OutlineTransparency = 1 })
			end
			if style == "Completo" or style == "Neon" or style == "Lendario" then
				local pillar = newPart(Vector3.new(6, 260, 6), Enum.PartType.Cylinder)
				pillar.Color = gold
				pillar.Transparency = 0.25
				pillar.CFrame = CFrame.new(origin + Vector3.new(0, 120, 0)) * CFrame.Angles(0, 0, math.rad(90))
				pillar.Size = Vector3.new(260, 7, 7)
				local light = Instance.new("PointLight")
				light.Color = gold
				light.Range = 60
				light.Brightness = 12
				light.Parent = pillar
				tween(pillar, 1.3, { Transparency = 1, Size = Vector3.new(260, 0.5, 0.5) }, Enum.EasingStyle.Quad)
				tween(light, 1.3, { Brightness = 0 })
			end
			local rings = (style == "Lendario") and 6 or ((style == "Neon") and 5 or 3)
			for index = 1, rings do
				task.delay((index - 1) * 0.12, function()
					local ring = newPart(Vector3.new(0.4, 4, 4), Enum.PartType.Cylinder)
					ring.Color = index % 2 == 0 and gold or ACCENT
					ring.Transparency = 0.15
					ring.CFrame = CFrame.new(origin) * CFrame.Angles(0, 0, math.rad(90))
					local final = 70 + index * 22
					tween(ring, 1, { Size = Vector3.new(0.4, final, final), Transparency = 1 }, Enum.EasingStyle.Quart)
				end)
			end
			local function firework(position)
				local anchor = newPart(Vector3.one, Enum.PartType.Ball)
				anchor.Transparency = 1
				anchor.Position = position
				local emitter = Instance.new("ParticleEmitter")
				emitter.Enabled = false
				emitter.Texture = "rbxasset://textures/particles/sparkles_main.dds"
				emitter.LightEmission = 1
				emitter.Lifetime = NumberRange.new(1.1, 1.8)
				emitter.Speed = NumberRange.new(25, 70)
				emitter.SpreadAngle = Vector2.new(180, 180)
				emitter.Acceleration = Vector3.new(0, -26, 0)
				emitter.Drag = 1.5
				emitter.Size = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 2.6), NumberSequenceKeypoint.new(1, 0),
				})
				emitter.Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(0.7, 0.2), NumberSequenceKeypoint.new(1, 1),
				})
				local hue = math.random()
				emitter.Color = ColorSequence.new(Color3.fromHSV(hue, 0.85, 1), Color3.fromHSV((hue + 0.12) % 1, 0.7, 1))
				emitter.Parent = anchor
				emitter:Emit(70)
				local flare = Instance.new("PointLight")
				flare.Color = Color3.fromHSV(hue, 0.6, 1)
