					beads[index] = bead
				end
				local spiralStart = os.clock()
				local spiralConnection
				spiralConnection = runService.Heartbeat:Connect(function()
					local elapsed = os.clock() - spiralStart
					if elapsed > 2.2 then
						spiralConnection:Disconnect()
						return
					end
					for index, bead in ipairs(beads) do
						local angle = elapsed * 5 + index * 0.75
						local height = (elapsed * 55 + index * 6) % 160
						local radius = 5 + height * 0.04
						bead.Position = origin + Vector3.new(math.cos(angle) * radius, height, math.sin(angle) * radius)
						bead.Transparency = math.clamp(0.1 + elapsed / 2.2 * 0.9, 0, 1)
					end
