					ColorSequenceKeypoint.new(1, Color3.new(1, 1, 1)),
				})
				confettiEmitter.Parent = rainPart
				confettiEmitter:Emit(160)
				task.delay(0.5, function()
					if confettiEmitter.Parent then confettiEmitter:Emit(110) end
