			{ AnchorPoint = Vector2.new(0, 0), Position = UDim2.fromScale(0, 0), Size = UDim2.fromScale(1, 0.22), Rotation = 90 },
			{ AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 1), Size = UDim2.fromScale(1, 0.22), Rotation = 270 },
		}
		for _, side in ipairs(sides) do
			local edge = Instance.new("Frame")
			edge.AnchorPoint = side.AnchorPoint
			edge.Position = side.Position
			edge.Size = side.Size
			edge.BackgroundColor3 = ACCENT
			edge.BackgroundTransparency = 0.15
			edge.BorderSizePixel = 0
			edge.ZIndex = 50
			edge.Parent = layer
			local gradient = Instance.new("UIGradient")
			gradient.Rotation = side.Rotation
			gradient.Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.2), NumberSequenceKeypoint.new(1, 1),
