		local flash = Instance.new("Frame")
		flash.Size = UDim2.fromScale(1, 1)
		flash.BackgroundColor3 = Color3.new(1, 1, 1)
		flash.BackgroundTransparency = 0.4
		flash.BorderSizePixel = 0
		flash.ZIndex = 50
		flash.Parent = layer
		tween(flash, 0.55, { BackgroundTransparency = 1 })
		local centerY = 0.3
		local band = Instance.new("Frame")
		band.AnchorPoint = Vector2.new(0.5, 0.5)
		band.Position = UDim2.fromScale(0.5, centerY)
		band.Size = UDim2.new(1, 0, 0, 0)
		band.BackgroundColor3 = Color3.fromRGB(8, 10, 16)
		band.BackgroundTransparency = 0.18
		band.BorderSizePixel = 0
		band.ZIndex = 52
		band.Parent = layer
		local bandFade = Instance.new("UIGradient")
		bandFade.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.2, 0),
			NumberSequenceKeypoint.new(0.8, 0), NumberSequenceKeypoint.new(1, 1),
		})
		bandFade.Parent = band
		local bandHeight = math.floor(140 * uiScale)
		tween(band, 0.4, { Size = UDim2.new(1, 0, 0, bandHeight) }, Enum.EasingStyle.Quint)
		for _, anchorY in ipairs({ 0, 1 }) do
			local line = Instance.new("Frame")
			line.AnchorPoint = Vector2.new(0.5, anchorY)
			line.Position = UDim2.fromScale(0.5, anchorY)
			line.Size = UDim2.new(1, 0, 0, 3)
			line.BackgroundColor3 = gold
			line.BorderSizePixel = 0
			line.ZIndex = 53
			line.Parent = band
			local lineFade = Instance.new("UIGradient")
			lineFade.Transparency = bandFade.Transparency
			lineFade.Parent = line
		end
		local label = Instance.new("TextLabel")
		label.AnchorPoint = Vector2.new(0.5, 0.5)
		label.Position = UDim2.fromScale(0.5, 0.5)
		label.Size = UDim2.new(1, 0, 1, -16)
		label.BackgroundTransparency = 1
		label.Font = Enum.Font.GothamBlack
		label.Text = tostring(config.goalEffectText or "GOL!")
		label.TextColor3 = Color3.new(1, 1, 1)
		label.TextScaled = true
		label.TextTransparency = 1
		label.TextStrokeColor3 = ACCENT
		label.TextStrokeTransparency = 1
		label.ZIndex = 54
		label.Parent = band
		local labelLimit = Instance.new("UITextSizeConstraint")
		labelLimit.MaxTextSize = 110
		labelLimit.Parent = label
		local labelGradient = Instance.new("UIGradient")
		labelGradient.Color = ColorSequence.new(Color3.new(1, 1, 1), gold)
		labelGradient.Rotation = 90
		labelGradient.Parent = label
		local labelScale = Instance.new("UIScale")
		labelScale.Scale = 2.6
		labelScale.Parent = label
		local sweep = Instance.new("Frame")
		sweep.AnchorPoint = Vector2.new(0.5, 0.5)
		sweep.Position = UDim2.fromScale(-0.2, 0.5)
		sweep.Size = UDim2.new(0.1, 0, 1, 0)
		sweep.BackgroundColor3 = Color3.new(1, 1, 1)
		sweep.BorderSizePixel = 0
		sweep.ZIndex = 56
		sweep.Parent = band
		local sweepGradient = Instance.new("UIGradient")
		sweepGradient.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0.35), NumberSequenceKeypoint.new(1, 1),
		})
		sweepGradient.Parent = sweep
		task.delay(0.5, function()
			if sweep.Parent then
				tween(sweep, 0.9, { Position = UDim2.fromScale(1.2, 0.5) }, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut)
			end
		end)
		task.delay(0.12, function()
			if not label.Parent then return end
			tween(labelScale, 0.5, { Scale = 1 }, Enum.EasingStyle.Back)
			tween(label, 0.3, { TextTransparency = 0, TextStrokeTransparency = 0.2 })
		end)
		local subtitle
		if scoreText then
			subtitle = Instance.new("TextLabel")
			subtitle.AnchorPoint = Vector2.new(0.5, 0)
			subtitle.Position = UDim2.new(0.5, 0, centerY, math.floor(bandHeight / 2) + 8)
			subtitle.Size = UDim2.fromOffset(400, math.floor(30 * uiScale))
			subtitle.BackgroundTransparency = 1
			subtitle.Font = Enum.Font.GothamBold
			subtitle.Text = "PLACAR   " .. scoreText
			subtitle.TextColor3 = Color3.new(1, 1, 1)
			subtitle.TextStrokeTransparency = 0.5
			subtitle.TextScaled = true
			subtitle.TextTransparency = 1
			subtitle.ZIndex = 54
			subtitle.Parent = layer
			task.delay(0.45, function()
				if subtitle.Parent then tween(subtitle, 0.35, { TextTransparency = 0 }) end
			end)
		end
		local ringCount = (style == "Minimo") and 0 or (style == "Lendario" and 6 or (style == "Neon" and 5 or 3))
		for index = 1, ringCount do
			task.delay(index * 0.1, function()
				if not layer.Parent then return end
				local ring = Instance.new("Frame")
				ring.AnchorPoint = Vector2.new(0.5, 0.5)
				ring.Position = UDim2.fromScale(0.5, centerY)
				ring.Size = UDim2.fromOffset(20, 20)
				ring.BackgroundTransparency = 1
				ring.ZIndex = 51
				ring.Parent = layer
				local corner = Instance.new("UICorner")
				corner.CornerRadius = UDim.new(1, 0)
				corner.Parent = ring
				local stroke = Instance.new("UIStroke")
				stroke.Color = index % 2 == 0 and gold or ACCENT
				stroke.Thickness = 6
				stroke.Parent = ring
				local reach = math.floor(900 * uiScale)
				tween(ring, 0.9, { Size = UDim2.fromOffset(reach, reach) }, Enum.EasingStyle.Quart)
				tween(stroke, 0.9, { Transparency = 1, Thickness = 1 })
			end)
		end
		local particles = {}
		local function addParticle(data)
			local piece = Instance.new("Frame")
			piece.AnchorPoint = Vector2.new(0.5, 0.5)
			piece.BackgroundColor3 = data.color
			piece.BorderSizePixel = 0
			piece.ZIndex = 55
			piece.Size = UDim2.fromOffset(data.w, data.h)
			piece.Parent = layer
			if data.round then
				local corner = Instance.new("UICorner")
				corner.CornerRadius = UDim.new(1, 0)
				corner.Parent = piece
			end
			data.frame = piece
			data.age = 0
			table.insert(particles, data)
		end
		local function burst(x, y, amount)
			for _ = 1, amount do
				local angle = math.random() * math.pi * 2
				local speed = math.random(180, 560) * uiScale
				local size = math.random(4, 9)
				addParticle({
					x = x, y = y, vx = math.cos(angle) * speed, vy = math.sin(angle) * speed,
					gravity = 420, drag = 1.4, life = 0.9 + math.random() * 0.7,
					w = size, h = size, round = true, color = colors[math.random(1, #colors)],
					spin = 0, rot = 0, flip = 0,
				})
			end
		end
		local function confetti(fromX, towardsRight, amount)
			for _ = 1, amount do
				local speed = math.random(500, 1250) * uiScale
				local angle = math.rad(math.random(52, 82))
				local direction = towardsRight and 1 or -1
				addParticle({
					x = fromX, y = view.Y + 10,
					vx = math.cos(angle) * speed * direction, vy = -math.sin(angle) * speed,
					gravity = 1100, drag = 0.9, life = 2 + math.random() * 1.3,
					w = math.random(7, 13), h = math.random(4, 8), round = false,
					color = colors[math.random(1, #colors)],
					spin = math.random(-540, 540), rot = math.random(0, 360), flip = math.random(6, 14),
				})
			end
		end
		local function rain(amount)
			for _ = 1, amount do
				addParticle({
					x = math.random() * view.X, y = -20 - math.random() * 200,
					vx = math.random(-60, 60), vy = math.random(80, 260),
					gravity = 220, drag = 0.3, life = 2.6 + math.random() * 1.2,
					w = math.random(7, 12), h = math.random(4, 7), round = false,
					color = colors[math.random(1, #colors)],
					spin = math.random(-360, 360), rot = math.random(0, 360), flip = math.random(5, 10),
				})
			end
		end
		if style == "Completo" then
			confetti(0, true, 70)
			confetti(view.X, false, 70)
			task.delay(0.35, function() if layer.Parent then rain(45) end end)
			burst(view.X / 2, view.Y * centerY, 40)
		elseif style == "Fogos" then
			for index = 1, 5 do
				task.delay(index * 0.28, function()
					if not layer.Parent then return end
					burst(view.X * (0.15 + math.random() * 0.7), view.Y * (0.12 + math.random() * 0.4), 46)
				end)
			end
		elseif style == "Neon" then
			burst(view.X / 2, view.Y * centerY, 90)
		elseif style == "Lendario" then
			confetti(0, true, 90)
			confetti(view.X, false, 90)
			task.delay(0.3, function() if layer.Parent then rain(60) end end)
			burst(view.X / 2, view.Y * centerY, 110)
			for index = 1, 6 do
				task.delay(index * 0.25, function()
					if not layer.Parent then return end
					burst(view.X * (0.1 + math.random() * 0.8), view.Y * (0.1 + math.random() * 0.45), 50)
				end)
			end
		end
		local particleConnection
		particleConnection = runService.RenderStepped:Connect(function(dt)
			dt = math.min(dt, 0.05)
			for index = #particles, 1, -1 do
				local p = particles[index]
				p.age = p.age + dt
				if p.age >= p.life or not p.frame.Parent then
					p.frame:Destroy()
					table.remove(particles, index)
				else
					local damping = math.max(0, 1 - p.drag * dt)
					p.vx = p.vx * damping
					p.vy = p.vy * damping + p.gravity * dt
					p.x = p.x + p.vx * dt
					p.y = p.y + p.vy * dt
					p.frame.Position = UDim2.fromOffset(p.x, p.y)
					if p.flip > 0 then
						p.frame.Size = UDim2.fromOffset(p.w, math.max(1, p.h * math.abs(math.cos(p.age * p.flip))))
						p.frame.Rotation = p.rot + p.spin * p.age
					end
					local fadeStart = p.life * 0.65
					if p.age > fadeStart then
						p.frame.BackgroundTransparency = (p.age - fadeStart) / (p.life - fadeStart)
					end
				end
			end
		end)
		if config.goalEffectShake and camera then
			local shakeStart = os.clock()
			pcall(function()
				runService:BindToRenderStep("TCSHubGoalShake", Enum.RenderPriority.Camera.Value + 1, function()
					local elapsed = os.clock() - shakeStart
					if elapsed > 0.45 then
						runService:UnbindFromRenderStep("TCSHubGoalShake")
						return
					end
					local power = (1 - elapsed / 0.45) * 0.012
					camera.CFrame = camera.CFrame * CFrame.Angles(
						(math.random() - 0.5) * power, (math.random() - 0.5) * power, (math.random() - 0.5) * power * 0.5
					)
				end)
			end)
		end
		task.delay(2.6, function()
			if not layer.Parent then return end
			tween(label, 0.45, { TextTransparency = 1, TextStrokeTransparency = 1 })
			tween(labelScale, 0.45, { Scale = 1.25 })
			tween(band, 0.45, { Size = UDim2.new(1, 0, 0, 0), BackgroundTransparency = 1 })
			if subtitle then tween(subtitle, 0.4, { TextTransparency = 1, TextStrokeTransparency = 1 }) end
		end)
		task.delay(4.4, function()
			particleConnection:Disconnect()
			pcall(function() runService:UnbindFromRenderStep("TCSHubGoalShake") end)
			layer:Destroy()
			goalEffectBusy = false
		end)
	end
	local function findScoreLabel()
		for index, descendant in ipairs(playerGui:GetDescendants()) do
			if descendant:IsA("TextLabel") and not descendant:IsDescendantOf(hubGui)
				and descendant.Text:match(SCORE_PATTERN) then
				return descendant
			end
			if index % 300 == 0 then task.wait() end
		end
		return nil
	end
	testGoalEffect = function() playGoalEffect("1 - 0") end
	task.spawn(function()
		while not scriptDestroyed do
			task.wait(0.4)
			if not (config.goalSoundEnabled or config.goalEffectEnabled) then
				lastTotal = nil
			else
				if not (scoreLabel and scoreLabel.Parent) then
					scoreLabel = nil
					if os.clock() - lastScan > 4 then
						lastScan = os.clock()
						scoreLabel = findScoreLabel()
					end
				end
				if scoreLabel then
					local home, away = scoreLabel.Text:match(SCORE_PATTERN)
					if home then
						local total = tonumber(home) + tonumber(away)
						if lastTotal and total > lastTotal then
							if config.goalSoundEnabled then playGoalSound(total) end
							if config.goalEffectEnabled then pcall(playGoalEffect, home .. " - " .. away) end
							if config.auraGoalBurst and triggerAuraBurst then triggerAuraBurst() end
						end
						lastTotal = total
					end
				end
			end
		end
	end)
end
