		{ "NiceTheme", "106767299215726" },
		{ "ANOTHER CLOUDY DAY", "84292991678085" },
		{ "Shady", "84738994204225" },
		{ "Pumpdafight", "71995582569283" },
	}
	if config.musicPlaylist:find("Phonk Gigachad=", 1, true) or config.musicPlaylist:find("God's Plan=", 1, true) then
		config.musicPlaylist = ""
	end
	local tracks = {}
	local currentIndex = 0
	local playToken = 0
	function Music.refresh()
		table.clear(tracks)
		for index, builtin in ipairs(BUILTIN_TRACKS) do
			table.insert(tracks, { name = builtin.name, builtin = index })
		end
		for _, preset in ipairs(PRESET_TRACKS) do
			table.insert(tracks, { name = preset[1], id = preset[2] })
		end
		for entry in string.gmatch(config.musicPlaylist, "[^;]+") do
			local name, id = entry:match("^(.-)=(%d+)$")
			if name and id then
				table.insert(tracks, { name = name, id = id })
			end
		end
		if listfiles and isfolder and isfolder(MUSIC_FOLDER) then
			pcall(function()
				for _, path in ipairs(listfiles(MUSIC_FOLDER)) do
					local extension = tostring(path):match("%.(%w+)$")
					if extension and AUDIO_EXTENSIONS[extension:lower()] then
						local fileName = tostring(path):match("([^/\\]+)$") or path
						table.insert(tracks, { name = fileName:gsub("%.%w+$", ""), path = path })
					end
				end
			end)
		end
		return tracks
	end
	function Music.names()
		local names = {}
		for _, track in ipairs(tracks) do
			table.insert(names, track.name)
		end
		if #names == 0 then names[1] = "(playlist vazia)" end
		return names
	end
	function Music.currentName()
		local track = tracks[currentIndex]
		return track and track.name
	end
	function Music.play(index)
		local track = tracks[index]
		if not track then return false, "Faixa nao encontrada. Adicione um ID ou coloque um arquivo na pasta " .. MUSIC_FOLDER end
		local soundId
		if track.builtin then
			local getAsset = getcustomasset or getsynasset
			local decode = (crypt and crypt.base64decode) or base64decode
			if not (getAsset and writefile and decode) then return false, "Seu executor nao suporta arquivos locais." end
			local builtin = BUILTIN_TRACKS[track.builtin]
			local path = MUSIC_FOLDER .. "/cache/" .. builtin.file
			local ok, asset = pcall(function()
				if makefolder then
					if not isfolder("TCSHubMini") then makefolder("TCSHubMini") end
					if not isfolder(MUSIC_FOLDER) then makefolder(MUSIC_FOLDER) end
					if not isfolder(MUSIC_FOLDER .. "/cache") then makefolder(MUSIC_FOLDER .. "/cache") end
				end
				if not (isfile and isfile(path)) then writefile(path, decode(builtin.data)) end
				return getAsset(path)
			end)
			if not (ok and asset) then return false, "Nao consegui abrir a faixa embutida." end
			soundId = asset
		elseif track.id then
			soundId = "rbxassetid://" .. track.id
		else
			local getAsset = getcustomasset or getsynasset
			if not getAsset then return false, "Seu executor nao suporta arquivos locais (getcustomasset)." end
			local ok, asset = pcall(getAsset, track.path)
			if not (ok and asset) then return false, "Nao consegui abrir o arquivo." end
			soundId = asset
		end
		currentIndex = index
		playToken += 1
		local token = playToken
		musicSound:Stop()
		musicSound.SoundId = soundId
		musicSound.Volume = config.musicVolume
		musicSound.Looped = config.musicLoop
		musicSound:Play()
		task.delay(5, function()
			if token == playToken and not scriptDestroyed and musicSound.TimeLength == 0 then
				pcall(function()
					WindUI:Notify({ Title = "Musica", Content = "O audio nao carregou. Teste outro ID ou um arquivo local.", Duration = 5 })
				end)
			end
		end)
		return true
	end
	function Music.toggle()
		if musicSound.IsPlaying then
			musicSound:Pause()
			return true
		end
		if currentIndex > 0 and musicSound.TimePosition > 0 then
			musicSound:Resume()
			return true
		end
		return Music.play(math.max(currentIndex, 1))
	end
	function Music.skip(step)
		if #tracks == 0 then return false, "Playlist vazia." end
		local index
		if config.musicShuffle and #tracks > 1 then
			repeat index = math.random(1, #tracks) until index ~= currentIndex
		else
			index = (currentIndex - 1 + step) % #tracks + 1
		end
		return Music.play(index)
	end
	function Music.stop()
		musicSound:Stop()
	end
	function Music.setVolume(value)
		config.musicVolume = value
		musicSound.Volume = value
	end
	function Music.setLoop(value)
		config.musicLoop = value
		musicSound.Looped = value
	end
	function Music.add(name, id)
		id = tostring(id or ""):match("%d+")
		if not id then return false, "ID invalido (use so o numero do audio)." end
		name = tostring(name or ""):gsub("[;=]", ""):gsub("^%s+", ""):gsub("%s+$", "")
		if name == "" then name = "Faixa " .. (#tracks + 1) end
		local entry = name .. "=" .. id
		config.musicPlaylist = config.musicPlaylist == "" and entry or (config.musicPlaylist .. ";" .. entry)
		Music.refresh()
		return true, name
	end
	function Music.remove(name)
		local kept, removed = {}, false
		for entry in string.gmatch(config.musicPlaylist, "[^;]+") do
			local entryName = entry:match("^(.-)=")
			if not removed and entryName == name then
				removed = true
			else
				table.insert(kept, entry)
			end
		end
		config.musicPlaylist = table.concat(kept, ";")
		Music.refresh()
		return removed
	end
	local endedConnection = musicSound.Ended:Connect(function()
		if scriptDestroyed or config.musicLoop then return end
		if config.musicAutoNext then Music.skip(1) end
	end)
	registerCleanup(function()
		endedConnection:Disconnect()
		musicSound:Stop()
	end)
	Music.refresh()
end
do
	local function ensureOption(key, options)
		if not table.find(options, config[key]) then config[key] = options[1] end
	end
	ensureOption("reachMode", REACH_MODES)
	ensureOption("reachActivation", REACH_ACTIVATIONS)
	ensureOption("reachMethod", REACH_METHODS)
	ensureOption("platform", { "Automatico", "Mobile", "PC", "Console" })
	ensureOption("deviceSpoof", { "Real", "Mobile", "PC", "Console" })
