	local uiControls = {}
	local function addElement(tab, method, options)
		if not tab then return nil end
		local ok, result = pcall(function()
			return tab[method](tab, options)
		end)
		if not ok then
			warn("Zenith: falha em " .. method .. " '" .. tostring(options.Title) .. "' -> " .. tostring(result))
			return nil
		end
		if method == "Toggle" or method == "Dropdown" then
			uiControls[options.Title] = result
		end
		return result
	end
	local function setToggle(title, value)
