	do
		local DEVICE_PROFILES = {
			Mobile = {
				touch = true, keyboard = false, mouse = false, gamepad = false, tenFoot = false,
				platform = Enum.Platform.Android, lastInput = Enum.UserInputType.Touch,
			},
			PC = {
				touch = false, keyboard = true, mouse = true, gamepad = false, tenFoot = false,
				platform = Enum.Platform.Windows, lastInput = Enum.UserInputType.Keyboard,
			},
			Console = {
				touch = false, keyboard = false, mouse = false, gamepad = true, tenFoot = true,
				platform = Enum.Platform.XBoxOne, lastInput = Enum.UserInputType.Gamepad1,
			},
		}
		QuickButtons.deviceNames = { "Real", "Mobile", "PC", "Console" }
		local deviceHooked = false
		local deviceLoop = 0
		local deviceGuiService = game:GetService("GuiService")
		local realInputService = userInputService
		local function activeProfile()
			return DEVICE_PROFILES[config.deviceSpoof]
		end
		local function installDeviceHooks()
			if deviceHooked then return end
			deviceHooked = true
			local oldIndex
			oldIndex = hookmetamethod(game, "__index", newcclosure(function(self, key)
				local profile = activeProfile()
				if profile and not checkcaller() and (self == realInputService) then
					if key == "TouchEnabled" then return profile.touch end
					if key == "KeyboardEnabled" then return profile.keyboard end
					if key == "MouseEnabled" then return profile.mouse end
					if key == "GamepadEnabled" then return profile.gamepad end
				end
				return oldIndex(self, key)
			end))
			local oldNamecall
			oldNamecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
				local profile = activeProfile()
				if profile and not checkcaller() then
					local method = getnamecallmethod()
					if self == realInputService then
						if method == "GetPlatform" then return profile.platform end
						if method == "GetLastInputType" then return profile.lastInput end
					elseif self == deviceGuiService and method == "IsTenFootInterface" then
						return profile.tenFoot
					end
				end
				return oldNamecall(self, ...)
			end))
		end
		local function pulseInputType(profile)
			pcall(function() firesignal(realInputService.LastInputTypeChanged, profile.lastInput) end)
		end
		local DEVICE_EMOJI = { Mobile = "\u{1F4F1}", PC = "\u{1F4BB}", Console = "\u{1F3AE}" }
		local iconOriginals = setmetatable({}, { __mode = "k" })
		local function isOwnName(text)
			return text == localPlayer.Name or text == localPlayer.DisplayName or text == "@" .. localPlayer.Name
		end
		local function findDeviceIcons()
			local found = {}
			local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui")
			if not playerGui then return found end
			for _, label in ipairs(playerGui:GetDescendants()) do
				if (label:IsA("TextLabel") or label:IsA("TextButton")) and isOwnName(label.Text) and label.AbsoluteSize.X > 0 then
					local screen = label:FindFirstAncestorOfClass("ScreenGui")
					if not screen or screen.Enabled then
						local labelCenter = label.AbsolutePosition + label.AbsoluteSize / 2
						local best, bestX = nil, math.huge
						local container = label.Parent
						for _ = 1, 2 do
							if not container or container:IsA("LayerCollector") then break end
							for _, object in ipairs(container:GetDescendants()) do
								if object:IsA("ImageLabel") or object:IsA("ImageButton") then
									local size = object.AbsoluteSize
									if size.X >= 8 and size.X <= 48 and size.Y >= 8 and size.Y <= 48 then
										local center = object.AbsolutePosition + size / 2
										if (center - labelCenter).Magnitude <= 150 and center.X < bestX then
											best, bestX = object, center.X
										end
									end
								end
							end
							container = container.Parent
						end
						if best then table.insert(found, best) end
					end
				end
			end
			return found
		end
		local function restoreDeviceIcons()
			for icon, data in pairs(iconOriginals) do
				pcall(function()
					icon.ImageTransparency = data.transparency
					local overlay = icon:FindFirstChild("TCSDeviceIcon")
					if overlay then overlay:Destroy() end
				end)
			end
			table.clear(iconOriginals)
		end
		local function applyDeviceIcons()
			local emoji = DEVICE_EMOJI[config.deviceSpoof]
			if not emoji then
				restoreDeviceIcons()
				return
			end
			for _, icon in ipairs(findDeviceIcons()) do
				if not iconOriginals[icon] then iconOriginals[icon] = { transparency = icon.ImageTransparency } end
				icon.ImageTransparency = 1
				local overlay = icon:FindFirstChild("TCSDeviceIcon")
				if not overlay then
					overlay = Instance.new("TextLabel")
					overlay.Name = "TCSDeviceIcon"
					overlay.BackgroundTransparency = 1
					overlay.Size = UDim2.fromScale(1, 1)
					overlay.TextScaled = true
					overlay.Font = Enum.Font.GothamBold
					overlay.ZIndex = icon.ZIndex + 1
					overlay.Parent = icon
				end
				overlay.Text = emoji
			end
		end
		function QuickButtons.applyDeviceSpoof()
			deviceLoop = deviceLoop + 1
			local token = deviceLoop
			local profile = activeProfile()
			if not profile then
				restoreDeviceIcons()
				return
			end
			local hooked, hookError = pcall(installDeviceHooks)
			if not hooked then warn("Zenith: dispositivo -> " .. tostring(hookError)) end
			pulseInputType(profile)
			task.spawn(function()
				local ticks = 0
				while token == deviceLoop and not scriptDestroyed do
					pcall(applyDeviceIcons)
					task.wait(1)
					ticks = ticks + 1
					if token == deviceLoop and ticks % 3 == 0 then pulseInputType(profile) end
				end
			end)
		end
		registerCleanup(function()
			config.deviceSpoof = "Real"
			deviceLoop = deviceLoop + 1
			restoreDeviceIcons()
		end)
	end
	do
		local SKILL_NAMES = {
			"Dominar", "Aleatorio", "Conduzir", "Parar Bola", "Lambreta", "Chapéu", "Calcanhar", "Voleio",
			"Bicicleta", "Cabeceio", "Chute Baixo", "Alto", "Esquerda", "Direita",
			"Esquerda Atrás", "Direita Atrás", "Arraste Para Trás",
		}
		local RANDOM_POOL = { "Dominar", "Lambreta", "Chapéu", "Calcanhar", "Conduzir" }
		local SKILL_TEXT = {}
		for _, name in ipairs(SKILL_NAMES) do
			if name ~= "Aleatorio" then SKILL_TEXT[name:lower()] = name end
		end
		SKILL_TEXT["chapeu"] = "Chapéu"
		SKILL_TEXT["esquerda atras"] = "Esquerda Atrás"
		SKILL_TEXT["direita atras"] = "Direita Atrás"
		SKILL_TEXT["arraste para tras"] = "Arraste Para Trás"
		QuickButtons.skillNames = SKILL_NAMES
		local skillButtons = {}
		local skillScanning = false
		local lastSkillScan = 0
		local lastSkillUse = 0
		local lastSkillWarn = 0
		local skillConnection = nil
		local skillGuiService = game:GetService("GuiService")
		local skillInputManager = game:GetService("VirtualInputManager")
		local SKILL_SIGNALS = { "MouseButton1Down", "Activated", "MouseButton1Click", "TouchTap", "MouseButton1Up" }
		local function scanSkillButtons()
			if skillScanning then return end
			skillScanning = true
			lastSkillScan = tick()
			pcall(function()
				local found = {}
				for index, descendant in ipairs(playerGui:GetDescendants()) do
					if descendant.Parent and (descendant:IsA("TextButton") or descendant:IsA("TextLabel"))
						and not descendant:IsDescendantOf(hubGui) then
						local name = SKILL_TEXT[descendant.Text:lower():match("^%s*(.-)%s*$")]
						if name then
							local button = descendant:IsA("GuiButton") and descendant
								or descendant:FindFirstAncestorWhichIsA("GuiButton") or descendant
							if not found[name] or button:IsA("GuiButton") then found[name] = button end
						end
					end
					if index % 150 == 0 then task.wait() end
				end
				skillButtons = found
			end)
			skillScanning = false
		end
		local function pressSkill(button)
			local hasConnections = false
			for _, signalName in ipairs(SKILL_SIGNALS) do
				local ok, connections = pcall(function() return getconnections(button[signalName]) end)
				if ok and connections and #connections > 0 then hasConnections = true break end
			end
			if hasConnections then
				for _, signalName in ipairs(SKILL_SIGNALS) do
					pcall(function() firesignal(button[signalName]) end)
				end
				return
			end
			pcall(function()
				local inset = skillGuiService:GetGuiInset()
				local center = button.AbsolutePosition + button.AbsoluteSize / 2 + inset
				skillInputManager:SendMouseButtonEvent(center.X, center.Y, 0, true, game, 0)
				task.wait(0.05)
				skillInputManager:SendMouseButtonEvent(center.X, center.Y, 0, false, game, 0)
			end)
			pcall(function()
				local inset = skillGuiService:GetGuiInset()
				local center = button.AbsolutePosition + button.AbsoluteSize / 2 + inset
				skillInputManager:SendTouchEvent(77, 0, center.X, center.Y)
				task.wait(0.05)
				skillInputManager:SendTouchEvent(77, 2, center.X, center.Y)
			end)
		end
		function QuickButtons.testSkill()
			scanSkillButtons()
			local name = config.autoSkillName == "Aleatorio" and RANDOM_POOL[1] or config.autoSkillName
			local button = skillButtons[name]
			if not (button and button.Parent) then
				return false, "Botao '" .. tostring(name) .. "' nao encontrado na tela."
			end
			task.spawn(pressSkill, button)
			return true, "Apertei '" .. name .. "' (" .. button.ClassName .. ")."
		end
		local function chooseSkill()
			if config.autoSkillName ~= "Aleatorio" then return config.autoSkillName end
			return RANDOM_POOL[math.random(1, #RANDOM_POOL)]
		end
		function QuickButtons.applyAutoSkill()
			if skillConnection then
				skillConnection:Disconnect()
				skillConnection = nil
			end
			if not config.autoSkillEnabled then return end
			task.spawn(scanSkillButtons)
			skillConnection = safeConnect(runService.Heartbeat, "autoSkill", function()
				if scriptDestroyed then return end
				local now = tick()
				if now - lastSkillUse < config.autoSkillCooldown then return end
				local character = localPlayer.Character
				local hrp = character and character:FindFirstChild("HumanoidRootPart")
				local ball = findBall()
				if not (hrp and ball and ball.Parent) then return end
				local toPlayer = hrp.Position - ball.Position
				local distance = toPlayer.Magnitude
				if distance > config.autoSkillRange then return end
				if config.autoSkillMode == "Bola chegando" and distance > 1.5 then
					local approach = ball.AssemblyLinearVelocity:Dot(toPlayer.Unit)
					if approach < 3 then return end
				end
				local name = chooseSkill()
				local button = skillButtons[name]
				if not (button and button.Parent) then
					if not skillScanning and now - lastSkillScan > 3 then task.spawn(scanSkillButtons) end
					if now - lastSkillWarn > 10 then
						lastSkillWarn = now
						warn("Zenith: Auto Skill nao achou o botao '" .. tostring(name) .. "' na tela.")
					end
					return
				end
				lastSkillUse = now
				print("Zenith: Auto Skill -> " .. name .. " (" .. button.ClassName .. ")")
				task.spawn(pressSkill, button)
			end)
		end
		registerCleanup(function()
			config.autoSkillEnabled = false
			QuickButtons.applyAutoSkill()
		end)
	end
	do
		local PLATFORM_GUI = game:GetService("GuiService")
		local platformConnection = nil
		function QuickButtons.detectPlatform()
			local touch = userInputService.TouchEnabled
			local keyboard = userInputService.KeyboardEnabled
			local gamepad = userInputService.GamepadEnabled
			local tenFoot = false
			pcall(function() tenFoot = PLATFORM_GUI:IsTenFootInterface() end)
			if tenFoot or (gamepad and not touch and not keyboard) then return "Console" end
			if touch and not keyboard then return "Mobile" end
			return "PC"
		end
		function QuickButtons.currentPlatform()
			if config.platform == "Automatico" then return QuickButtons.detectPlatform() end
			return config.platform
		end
		function QuickButtons.applyPlatform(force)
			local show = QuickButtons.currentPlatform() == "Mobile"
			if show and not force then return end
			QuickButtons.setHudVisible(show)
		end
		local HOTKEYS_PC = {
			[Enum.KeyCode.Z] = "multiReachEnabled",
			[Enum.KeyCode.X] = "silentAimEnabled",
			[Enum.KeyCode.C] = "ballControlEnabled",
			[Enum.KeyCode.V] = "perfectAngleEnabled",
			[Enum.KeyCode.B] = "autoSkillEnabled",
		}
		local HOTKEYS_CONSOLE = {
			[Enum.KeyCode.DPadUp] = "multiReachEnabled",
			[Enum.KeyCode.DPadRight] = "silentAimEnabled",
			[Enum.KeyCode.DPadDown] = "ballControlEnabled",
			[Enum.KeyCode.DPadLeft] = "autoSkillEnabled",
		}
		local HOTKEY_LABELS = {
			multiReachEnabled = "Reach", silentAimEnabled = "Silent Aim", ballControlEnabled = "Controle",
			perfectAngleEnabled = "Perfect Angle", autoSkillEnabled = "Auto Skill",
		}
		local function applyFeature(key, state)
			if key == "multiReachEnabled" then
				applyMultiReach(state)
			elseif key == "autoSkillEnabled" then
				QuickButtons.applyAutoSkill()
			else
				applyBallAssist()
			end
		end
		local function toggleFeature(key)
			local state = not config[key]
			config[key] = state
			applyFeature(key, state)
			local quick = QuickButtons.buttons[key]
			if quick then quick.refresh(state) end
			local toggle = QuickButtons.toggles[key]
			if toggle then pcall(function() toggle:Set(state) end) end
			uiNotify(HOTKEY_LABELS[key], state and "Ligado" or "Desligado", 1.5)
		end
		if platformConnection then platformConnection:Disconnect() end
		platformConnection = safeConnect(userInputService.InputBegan, "platformHotkeys", function(input, processed)
			if processed or scriptDestroyed then return end
			local platform = QuickButtons.currentPlatform()
			local key
			if platform == "PC" then
				key = HOTKEYS_PC[input.KeyCode]
			elseif platform == "Console" then
				key = HOTKEYS_CONSOLE[input.KeyCode]
			end
			if key then toggleFeature(key) end
		end)
		registerCleanup(function() platformConnection:Disconnect() end)
		QuickButtons.applyPlatform(false)
	end
	do
		local GOAL_CENTERS = { Vector3.new(-32.18, -28.94, -203.58), Vector3.new(-19, -28.94, 386.3) }
		local GOAL_RADIUS = 16
		local GOAL_ESP_HINTS = { "goal", "gol", "trave", "poste" }
		local GOAL_SKIP_HINTS = { "grass", "field", "campo", "ground", "floor", "wall", "fence", "baseplate", "line", "stand", "net", "rede", "magnet" }
		local GOAL_ESP_COLOR = Color3.fromRGB(0, 255, 40)
		local goalBoxes = {}
		local goalScanToken = 0
		local goalFolder = Instance.new("Folder")
		goalFolder.Name = "TCSHubMiniGoalEsp"
		goalFolder.Parent = espFolder
		local function nameHas(name, hints)
			for _, hint in ipairs(hints) do
				if name:find(hint, 1, true) then return true end
			end
			return false
		end
		local function isGoalPart(part)
			if not part:IsA("BasePart") then return false end
			local size = part.Size
			if math.max(size.X, size.Y, size.Z) > 45 then return false end
			local name = part.Name:lower()
			if nameHas(name, GOAL_SKIP_HINTS) then return false end
			if name == "tps" or name:find("ball", 1, true) or name:find("bola", 1, true) then return false end
			local ballNow = findBall and findBall() or nil
			if ballNow and (part == ballNow or part:IsDescendantOf(ballNow) or ballNow:IsDescendantOf(part)) then return false end
			if ballNow and (part.Position - ballNow.Position).Magnitude < 7 and part.Size.Magnitude > 6 then return false end
			if math.min(size.X, size.Y, size.Z) > 3 then return false end
			if part.Transparency >= 1 and not part.CanCollide then return false end
			local model = part:FindFirstAncestorOfClass("Model")
			if model and model:FindFirstChildOfClass("Humanoid") then return false end
			if nameHas(name, GOAL_ESP_HINTS) then return true end
			local parent = part.Parent
			if parent and parent ~= workspace and nameHas(parent.Name:lower(), GOAL_ESP_HINTS)
				and not nameHas(parent.Name:lower(), GOAL_SKIP_HINTS) then
				return true
			end
			if not part.Anchored then return false end
			for _, center in ipairs(GOAL_CENTERS) do
				if (part.Position - center).Magnitude <= GOAL_RADIUS then return true end
			end
			return false
		end
		local function addGoalBox(part)
			local box = Instance.new("SelectionBox")
			box.Name = "GoalEsp"
			box.Adornee = part
			box.Color3 = GOAL_ESP_COLOR
			box.LineThickness = 0.06
			box.SurfaceTransparency = 1
			box.Parent = goalFolder
			goalBoxes[part] = box
		end
		function QuickButtons.applyGoalEsp()
			goalScanToken = goalScanToken + 1
			local token = goalScanToken
			goalFolder:ClearAllChildren()
			table.clear(goalBoxes)
			if not config.goalEspEnabled then return end
			task.spawn(function()
				while token == goalScanToken and not scriptDestroyed do
					local added = 0
					for index, descendant in ipairs(workspace:GetDescendants()) do
						if token ~= goalScanToken then return end
						if index % 1500 == 0 then task.wait() end
						local box = goalBoxes[descendant]
						if not (box and box.Parent) and added < 60 and isGoalPart(descendant) then
							addGoalBox(descendant)
							added = added + 1
						end
					end
					task.wait(15)
				end
			end)
		end
		registerCleanup(function()
			config.goalEspEnabled = false
			QuickButtons.applyGoalEsp()
		end)
	end
	do
		local FEET_ONLY = { ["LeftFoot"] = true, ["RightFoot"] = true }
		local LEGS_AND_FEET = {
			["LeftFoot"] = true, ["RightFoot"] = true, ["Left Leg"] = true, ["Right Leg"] = true,
			["LeftLowerLeg"] = true, ["RightLowerLeg"] = true, ["LeftUpperLeg"] = true, ["RightUpperLeg"] = true,
		}
		QuickButtons.footPartNames = { "Pernas e pes", "So os pes" }
		local footOriginals = setmetatable({}, { __mode = "k" })
		local footAdornments = setmetatable({}, { __mode = "k" })
		local footFolder = nil
		local footConnection = nil
		local function clearAdornments()
			for part, adornment in pairs(footAdornments) do
				pcall(function() adornment:Destroy() end)
				footAdornments[part] = nil
			end
			if footFolder then
				footFolder:Destroy()
				footFolder = nil
			end
		end
		local function restorePart(part, data)
			if not part.Parent then return end
			pcall(function()
				part.Size = data.size
				part.Transparency = data.transparency
				part.CanCollide = data.canCollide
				part.CanQuery = data.canQuery
				part.Massless = data.massless
			end)
		end
		local function restoreFeet()
			for part, data in pairs(footOriginals) do
				restorePart(part, data)
				footOriginals[part] = nil
			end
			clearAdornments()
		end
		function QuickButtons.applyFootHitbox()
			if footConnection then
				footConnection:Disconnect()
				footConnection = nil
			end
			if not config.footHitboxEnabled then
				restoreFeet()
				return
			end
			footConnection = safeConnect(runService.Heartbeat, "footHitbox", function(dt)
				if scriptDestroyed then return end
				local character = localPlayer.Character
				local hrp = character and character:FindFirstChild("HumanoidRootPart")
				if not (character and hrp) then return end
				local names = config.footHitboxParts == "So os pes" and FEET_ONLY or LEGS_AND_FEET
				local wanted = config.footHitboxSize
				local active = true
				local ball = findBall()
				if config.footHitboxNearBall ~= false then
					if ball then
						local distance = (ball.Position - hrp.Position).Magnitude
						active = distance <= config.footHitboxActiveRange
						if active and config.footHitboxAuto then
							wanted = math.clamp(distance * 1.4, 3, config.footHitboxSize)
						end
					else
						active = false
					end
				end
				local blend = math.clamp((dt or 0.016) * 14, 0, 1)
				for _, part in ipairs(character:GetChildren()) do
					if part:IsA("BasePart") and names[part.Name] then
						local data = footOriginals[part]
						if not data then
							data = {
								size = part.Size, transparency = part.Transparency, canCollide = part.CanCollide,
								canQuery = part.CanQuery, massless = part.Massless,
							}
							footOriginals[part] = data
						end
						local target = active and Vector3.new(wanted, wanted, wanted) or data.size
						local size = part.Size:Lerp(target, blend)
						if (size - target).Magnitude < 0.05 then size = target end
						if part.Size ~= size then part.Size = size end
						local grown = (size - data.size).Magnitude > 0.2
						part.Transparency = grown and 1 or data.transparency
						part.CanCollide = grown and false or data.canCollide
						part.CanQuery = grown and false or data.canQuery
						part.Massless = grown and true or data.massless
						if config.footHitboxShow and grown then
							if not (footFolder and footFolder.Parent) then
								footFolder = Instance.new("Folder")
								footFolder.Name = "TCSHubMiniFoot"
								footFolder.Parent = workspace.CurrentCamera or workspace
							end
							local adornment = footAdornments[part]
							if not (adornment and adornment.Parent) then
								adornment = Instance.new("BoxHandleAdornment")
								adornment.Adornee = part
								adornment.AlwaysOnTop = true
								adornment.ZIndex = 1
								adornment.Transparency = 0.8
								adornment.Color3 = Color3.fromRGB(0, 255, 120)
								adornment.Parent = footFolder
								footAdornments[part] = adornment
							end
							adornment.Size = part.Size
						elseif footAdornments[part] then
							footAdornments[part]:Destroy()
							footAdornments[part] = nil
						end
					end
				end
			end)
		end
		registerCleanup(function()
			config.footHitboxEnabled = false
			QuickButtons.applyFootHitbox()
		end)
	end
	local function disableEverything()
		setFollow(false)
		config.multiReachEnabled = false
		applyMultiReach(false)
		config.footHitboxEnabled = false
		QuickButtons.applyFootHitbox()
