		for _, quick in pairs(QuickButtons.buttons) do quick.refresh(false) end
		config.ballEspEnabled = false
		config.reachVisualEnabled = false
		config.worldClockOn = false
		setHaloEnabled(false)
		config.skinEnabled = false
		restoreBodyLook()
		config.ballSkinEnabled = false
		restoreBallLook()
		restoreWorld()
		config.skyPreset = "Nenhum"
		applyGrassPreset("Original")
		config.grassPreset = "Original"
		if config.fpsBoostOn then setFpsBoost(false) end
		if config.fovOn then setFov(false) end
		if config.stretchOn then setStretch(false) end
		config.auraName = "Nenhuma"
		applyAura()
		for _, title in ipairs(MASTER_TOGGLES) do
			setToggle(title, false)
		end
		selectOption("Aura", "Nenhuma")
		selectOption("Skybox", "Nenhum")
		selectOption("Cor do gramado", "Original")
		notifyUi("Tudo desligado.")
	end
