		do
			local trailObjects = {}
			local trailTrails = {}
			local trailEmitter = nil
			local trailRoot = nil
			local trailClock = 0

			local TRAIL_STYLES = {
				Neon = { a = Color3.fromRGB(165, 105, 255), b = Color3.fromRGB(80, 200, 255), emission = 1, spark = Color3.fromRGB(200, 170, 255) },
				Fogo = { a = Color3.fromRGB(255, 240, 120), b = Color3.fromRGB(255, 60, 20), emission = 1, spark = Color3.fromRGB(255, 150, 40) },
				Gelo = { a = Color3.fromRGB(235, 250, 255), b = Color3.fromRGB(70, 160, 255), emission = 0.9, spark = Color3.fromRGB(190, 230, 255) },
				Galaxia = { a = Color3.fromRGB(255, 120, 230), b = Color3.fromRGB(60, 40, 200), emission = 1, spark = Color3.fromRGB(255, 255, 255) },
				Toxico = { a = Color3.fromRGB(190, 255, 80), b = Color3.fromRGB(20, 140, 60), emission = 0.9, spark = Color3.fromRGB(150, 255, 120) },
				Ouro = { a = Color3.fromRGB(255, 235, 150), b = Color3.fromRGB(255, 160, 30), emission = 0.9, spark = Color3.fromRGB(255, 220, 100) },
				Fantasma = { a = Color3.fromRGB(255, 255, 255), b = Color3.fromRGB(160, 170, 200), emission = 0.3, spark = Color3.fromRGB(230, 235, 255) },
			}
			local TRAIL_STYLE_NAMES = { "Neon", "Fogo", "Gelo", "Galaxia", "Toxico", "Ouro", "Fantasma", "Arco-iris", "Personalizada" }
			local TRAIL_POSITIONS = { "Corpo", "Chao (pes)", "Cintura", "Dupla (corpo + chao)" }

			local function destroyTrail()
				for _, object in ipairs(trailObjects) do pcall(function() object:Destroy() end) end
				table.clear(trailObjects)
				table.clear(trailTrails)
				trailEmitter = nil
				trailRoot = nil
			end

			local function styleColors()
				local style = config.trailStyle
				if style == "Personalizada" then return config.trailColor, config.trailColor2, config.trailColor end
				local preset = TRAIL_STYLES[style]
				if preset then return preset.a, preset.b, preset.spark end
				return config.trailColor, config.trailColor2, config.trailColor
			end

			local function buildSequence(hueShift)
				if config.trailStyle == "Arco-iris" or config.trailCycle then
					local points = {}
					local count = 7
					for index = 0, count - 1 do
						local hue = (hueShift + index / count) % 1
						table.insert(points, ColorSequenceKeypoint.new(index / (count - 1), Color3.fromHSV(hue, 0.85, 1)))
					end
					return ColorSequence.new(points)
				end
				local colorA, colorB = styleColors()
				return ColorSequence.new(colorA, colorB)
			end

			local function emissionValue()
				local preset = TRAIL_STYLES[config.trailStyle]
				local base = preset and preset.emission or 1
				return math.clamp(base * config.trailGlow, 0, 1)
			end

			local function addTrail(root, name, offsetA, offsetB, faceCamera)
				local attachA = Instance.new("Attachment")
				attachA.Name = name .. "A"
				attachA.Position = offsetA
				attachA.Parent = root
				local attachB = Instance.new("Attachment")
				attachB.Name = name .. "B"
				attachB.Position = offsetB
				attachB.Parent = root

				local trail = Instance.new("Trail")
				trail.Name = name
				trail.Attachment0 = attachA
				trail.Attachment1 = attachB
				trail.Lifetime = config.trailLifetime
				trail.MinLength = 0.04
				trail.MaxLength = 400
				trail.FaceCamera = faceCamera
				trail.LightEmission = emissionValue()
				trail.LightInfluence = 0
				trail.Color = buildSequence(0)
				trail.Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, config.trailTransparency),
					NumberSequenceKeypoint.new(0.6, math.clamp(config.trailTransparency + 0.35, 0, 1)),
					NumberSequenceKeypoint.new(1, 1),
				})
				trail.WidthScale = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 1),
					NumberSequenceKeypoint.new(1, config.trailTaper and 0 or 0.9),
				})
				trail.Parent = root

				table.insert(trailObjects, attachA)
				table.insert(trailObjects, attachB)
				table.insert(trailObjects, trail)
				table.insert(trailTrails, trail)
			end

			local function applyTrail()
				destroyTrail()
				if not config.trailEnabled or scriptDestroyed then return end
				local character = localPlayer.Character
				local root = character and character:FindFirstChild("HumanoidRootPart")
				if not root then return end
				trailRoot = root

				local width = config.trailWidth
				local position = config.trailPosition
				if position == "Corpo" or position == "Dupla (corpo + chao)" then
					addTrail(root, "ZenithTrailBody", Vector3.new(0, 0.9, 0), Vector3.new(0, 0.9 - width * 1.6, 0), true)
				end
				if position == "Cintura" then
					addTrail(root, "ZenithTrailWaist", Vector3.new(-width * 0.5, -0.3, 0.4), Vector3.new(width * 0.5, -0.3, 0.4), true)
				end
				if position == "Chao (pes)" or position == "Dupla (corpo + chao)" then
					addTrail(root, "ZenithTrailFloorL", Vector3.new(-0.75, -2.7, 0), Vector3.new(-0.75 + width * 0.5, -2.7, 0), false)
					addTrail(root, "ZenithTrailFloorR", Vector3.new(0.75, -2.7, 0), Vector3.new(0.75 - width * 0.5, -2.7, 0), false)
				end

				if config.trailSparks then
					local _, _, sparkColor = styleColors()
					local emitter = Instance.new("ParticleEmitter")
					emitter.Name = "ZenithTrailSparks"
					emitter.Rate = 0
					emitter.Lifetime = NumberRange.new(0.6, 1.2)
					emitter.Speed = NumberRange.new(0.5, 2.5)
					emitter.SpreadAngle = Vector2.new(180, 180)
					emitter.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.28), NumberSequenceKeypoint.new(1, 0) })
					emitter.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.1), NumberSequenceKeypoint.new(1, 1) })
					emitter.LightEmission = 1
					emitter.LightInfluence = 0
					emitter.Color = ColorSequence.new(sparkColor)
					emitter.Drag = 2
					emitter.Parent = root
					table.insert(trailObjects, emitter)
					trailEmitter = emitter
				end
			end

			-- Anima cor em ciclo, liga so em movimento e solta faiscas.
			local trailStep = runService.Heartbeat:Connect(function(delta)
				if #trailTrails == 0 or not trailRoot or not trailRoot.Parent then return end
				trailClock += delta

				local speed = trailRoot.AssemblyLinearVelocity.Magnitude
				local moving = speed > 2
				local visible = (not config.trailOnlyMoving) or moving
				for _, trail in ipairs(trailTrails) do
					if trail.Enabled ~= visible then trail.Enabled = visible end
				end

				if trailEmitter then
					trailEmitter.Rate = (visible and moving) and math.clamp(speed * 0.9, 6, 40) or 0
				end

				if config.trailCycle or config.trailStyle == "Arco-iris" then
					local shift = (trailClock * config.trailCycleSpeed * 0.2) % 1
					local sequence = buildSequence(shift)
					for _, trail in ipairs(trailTrails) do trail.Color = sequence end
				end
			end)

			local trailRespawn = localPlayer.CharacterAdded:Connect(function()
				task.wait(0.5)
				applyTrail()
			end)
			registerCleanup(function()
				trailStep:Disconnect()
				trailRespawn:Disconnect()
				destroyTrail()
			end)

			local function refreshTrail()
				if config.trailEnabled then applyTrail() end
			end

			addElement(VisualsTab, "Toggle", {
				Title = "Trilha de caminhada",
				Desc = "Rastro atras de voce, so voce ve.",
				Default = config.trailEnabled,
				Callback = function(v)
					config.trailEnabled = v
					applyTrail()
				end,
			})
			addElement(VisualsTab, "Dropdown", {
				Title = "Estilo da trilha",
				Values = TRAIL_STYLE_NAMES,
				Value = config.trailStyle,
				Callback = function(option)
					local name = normalizeOption(option)
					if not name then return end
					config.trailStyle = name
					refreshTrail()
				end,
			})
			addElement(VisualsTab, "Dropdown", {
				Title = "Posicao da trilha",
				Values = TRAIL_POSITIONS,
				Value = config.trailPosition,
				Callback = function(option)
					local name = normalizeOption(option)
					if not name then return end
					config.trailPosition = name
					refreshTrail()
				end,
			})
			addElement(VisualsTab, "Toggle", {
				Title = "Ciclo de cores",
				Desc = "As cores giram sozinhas pelo arco-iris.",
				Default = config.trailCycle,
				Callback = function(v)
					config.trailCycle = v
					refreshTrail()
				end,
			})
			addElement(VisualsTab, "Slider", {
				Title = "Velocidade do ciclo",
				Step = 0.1,
				Value = { Min = 0.2, Max = 5, Default = config.trailCycleSpeed },
				Callback = function(v) config.trailCycleSpeed = v end,
			})
			addElement(VisualsTab, "Toggle", {
				Title = "Faiscas",
				Desc = "Particulas que saem enquanto voce corre.",
				Default = config.trailSparks,
				Callback = function(v)
					config.trailSparks = v
					refreshTrail()
				end,
			})
			addElement(VisualsTab, "Toggle", {
				Title = "So em movimento",
				Default = config.trailOnlyMoving,
				Callback = function(v) config.trailOnlyMoving = v end,
			})
			addElement(VisualsTab, "Toggle", {
				Title = "Afinar na ponta",
				Default = config.trailTaper,
				Callback = function(v)
					config.trailTaper = v
					refreshTrail()
				end,
			})
			addElement(VisualsTab, "Colorpicker", {
				Title = "Cor inicial (Personalizada)",
				Default = config.trailColor,
				Callback = function(color)
					if typeof(color) ~= "Color3" then return end
					config.trailColor = color
					refreshTrail()
				end,
			})
			addElement(VisualsTab, "Colorpicker", {
				Title = "Cor final (Personalizada)",
				Default = config.trailColor2,
				Callback = function(color)
					if typeof(color) ~= "Color3" then return end
					config.trailColor2 = color
					refreshTrail()
				end,
			})
			addElement(VisualsTab, "Slider", {
				Title = "Duracao (s)",
				Step = 0.1,
				Value = { Min = 0.2, Max = 5, Default = config.trailLifetime },
				Callback = function(v)
					config.trailLifetime = v
					refreshTrail()
				end,
			})
			addElement(VisualsTab, "Slider", {
				Title = "Largura",
				Step = 0.1,
				Value = { Min = 0.3, Max = 4, Default = config.trailWidth },
				Callback = function(v)
					config.trailWidth = v
					refreshTrail()
				end,
			})
			addElement(VisualsTab, "Slider", {
				Title = "Brilho",
				Step = 0.05,
				Value = { Min = 0, Max = 1, Default = config.trailGlow },
				Callback = function(v)
					config.trailGlow = v
					refreshTrail()
				end,
			})
			addElement(VisualsTab, "Slider", {
				Title = "Transparencia",
				Step = 0.05,
				Value = { Min = 0, Max = 0.9, Default = config.trailTransparency },
				Callback = function(v)
					config.trailTransparency = v
					refreshTrail()
				end,
			})
			if config.trailEnabled then task.spawn(applyTrail) end
		end

		addElement(VisualsTab, "Section", { Title = "Chapeu da China" })
		do
			local hatFolder = nil
			local hatParts = {}

			local function destroyHat()
				if hatFolder then pcall(function() hatFolder:Destroy() end) end
				hatFolder = nil
				table.clear(hatParts)
			end

			local function applyHat()
				destroyHat()
				if not config.hatEnabled or scriptDestroyed then return end
				local character = localPlayer.Character
				local head = character and character:FindFirstChild("Head")
				if not head then return end

				hatFolder = Instance.new("Folder")
				hatFolder.Name = "ZenithHat"
				hatFolder.Parent = character

				local layers = 9
				local layerHeight = config.hatHeight / layers
				for index = 1, layers do
					local progress = (index - 1) / (layers - 1)
					local radius = math.max(config.hatRadius * (1 - progress * 0.94), 0.05)
					local layer = Instance.new("Part")
					layer.Name = "HatLayer"
					layer.Shape = Enum.PartType.Cylinder
					layer.Size = Vector3.new(layerHeight * 1.15, radius * 2, radius * 2)
					layer.Material = Enum.Material.Neon
					layer.Color = config.hatColor
					layer.Transparency = config.hatTransparency
					layer.CanCollide = false
					layer.CanQuery = false
					layer.CanTouch = false
					layer.CastShadow = false
					layer.Massless = true
					layer.Parent = hatFolder

					local weld = Instance.new("Weld")
					weld.Part0 = head
					weld.Part1 = layer
					weld.C0 = CFrame.new(0, head.Size.Y / 2 + config.hatOffset + layerHeight * (index - 0.5), 0) * CFrame.Angles(0, 0, math.rad(90))
					weld.Parent = layer
					table.insert(hatParts, layer)
				end
			end

			local hatClock = 0
			local hatStep = runService.Heartbeat:Connect(function(delta)
				if #hatParts == 0 then return end
				hatClock += delta
				local color = config.hatColor
				if config.hatRainbow then color = Color3.fromHSV((hatClock * 0.25) % 1, 0.8, 1) end
				for index, layer in ipairs(hatParts) do
					if layer.Parent then
						if config.hatRainbow then
							layer.Color = Color3.fromHSV((hatClock * 0.25 + index * 0.03) % 1, 0.8, 1)
						else
							layer.Color = color
						end
					end
				end
			end)
			local hatRespawn = localPlayer.CharacterAdded:Connect(function()
				task.wait(0.6)
				applyHat()
			end)
			registerCleanup(function()
				hatStep:Disconnect()
				hatRespawn:Disconnect()
				destroyHat()
			end)

			addElement(VisualsTab, "Toggle", {
				Title = "Chapeu da China",
				Desc = "Chapeu neon em cone na sua cabeca, so voce ve.",
				Default = config.hatEnabled,
				Callback = function(v)
					config.hatEnabled = v
					applyHat()
				end,
			})
			addElement(VisualsTab, "Toggle", {
				Title = "Chapeu arco-iris",
				Default = config.hatRainbow,
				Callback = function(v) config.hatRainbow = v end,
			})
			addElement(VisualsTab, "Colorpicker", {
				Title = "Cor do chapeu",
				Default = config.hatColor,
				Callback = function(color)
					if typeof(color) == "Color3" then config.hatColor = color end
				end,
			})
			addElement(VisualsTab, "Slider", {
				Title = "Largura do chapeu",
				Step = 0.1,
				Value = { Min = 0.8, Max = 4.5, Default = config.hatRadius },
				Callback = function(v)
					config.hatRadius = v
					if config.hatEnabled then applyHat() end
				end,
			})
			addElement(VisualsTab, "Slider", {
				Title = "Altura do chapeu",
				Step = 0.1,
				Value = { Min = 0.3, Max = 3, Default = config.hatHeight },
				Callback = function(v)
					config.hatHeight = v
					if config.hatEnabled then applyHat() end
				end,
			})
			addElement(VisualsTab, "Slider", {
				Title = "Transparencia do chapeu",
				Step = 0.05,
				Value = { Min = 0, Max = 0.9, Default = config.hatTransparency },
				Callback = function(v)
					config.hatTransparency = v
					if config.hatEnabled then applyHat() end
				end,
			})
			if config.hatEnabled then task.spawn(applyHat) end
		end

		addElement(VisualsTab, "Section", { Title = "Particulas" })
		do
			local PARTICLE_STYLES = {
				Brilho = { texture = "rbxasset://textures/particles/sparkles_main.dds", glow = 1, lift = 0, speed = 3 },
				Fogo = { texture = "rbxasset://textures/particles/fire_main.dds", glow = 1, lift = 6, speed = 2 },
				Fumaca = { texture = "rbxasset://textures/particles/smoke_main.dds", glow = 0, lift = 3, speed = 1.5 },
				Cometa = { texture = "rbxasset://textures/particles/sparkles_main.dds", glow = 1, lift = 0, speed = 0 },
			}
			local PARTICLE_STYLE_NAMES = { "Brilho", "Fogo", "Fumaca", "Cometa" }
			local PARTICLE_MODES = { "Sempre", "Andando", "Parado" }

			local emitter = nil
			local emitterRoot = nil
			local particleClock = 0

			local function destroyEmitter()
				if emitter then pcall(function() emitter:Destroy() end) end
				emitter = nil
				emitterRoot = nil
			end

			local function applyEmitter()
				destroyEmitter()
				if not config.particlesEnabled or scriptDestroyed then return end
				local character = localPlayer.Character
				local root = character and character:FindFirstChild("HumanoidRootPart")
				if not root then return end
				local style = PARTICLE_STYLES[config.particleStyle] or PARTICLE_STYLES.Brilho

				emitter = Instance.new("ParticleEmitter")
				emitter.Name = "ZenithParticles"
				emitter.Texture = style.texture
				emitter.Rate = 0
				emitter.Lifetime = NumberRange.new(0.8, 1.6)
				emitter.Speed = NumberRange.new(style.speed * config.particleSpeed * 0.6, style.speed * config.particleSpeed)
				emitter.SpreadAngle = Vector2.new(180, 180)
				emitter.Acceleration = Vector3.new(0, style.lift, 0)
				emitter.Rotation = NumberRange.new(0, 360)
				emitter.RotSpeed = NumberRange.new(-120, 120)
				emitter.LightEmission = style.glow
				emitter.LightInfluence = 0
				emitter.Drag = 1
				emitter.Size = NumberSequence.new({
					NumberSequenceKeypoint.new(0, config.particleSize),
					NumberSequenceKeypoint.new(1, 0),
				})
				emitter.Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0.1),
					NumberSequenceKeypoint.new(1, 1),
				})
				emitter.Color = ColorSequence.new(config.particleColor)
				emitter.Parent = root
				emitterRoot = root
			end

			local particleStep = runService.Heartbeat:Connect(function(delta)
				if not emitter or not emitterRoot or not emitterRoot.Parent then return end
				particleClock += delta
				local speed = emitterRoot.AssemblyLinearVelocity.Magnitude
				local moving = speed > 2
				local active = config.particleMode == "Sempre"
					or (config.particleMode == "Andando" and moving)
					or (config.particleMode == "Parado" and not moving)
				emitter.Rate = active and config.particleRate or 0
				if config.particleRainbow then
					emitter.Color = ColorSequence.new(Color3.fromHSV((particleClock * 0.3) % 1, 0.8, 1))
				end
			end)
			local particleRespawn = localPlayer.CharacterAdded:Connect(function()
				task.wait(0.6)
				applyEmitter()
			end)
			registerCleanup(function()
				particleStep:Disconnect()
				particleRespawn:Disconnect()
				destroyEmitter()
			end)

			local function refreshEmitter()
				if config.particlesEnabled then applyEmitter() end
			end

			addElement(VisualsTab, "Toggle", {
				Title = "Particulas",
				Desc = "Efeito de particulas em volta de voce, so voce ve.",
				Default = config.particlesEnabled,
				Callback = function(v)
					config.particlesEnabled = v
					applyEmitter()
				end,
			})
			addElement(VisualsTab, "Dropdown", {
				Title = "Estilo das particulas",
				Values = PARTICLE_STYLE_NAMES,
				Value = config.particleStyle,
				Callback = function(option)
					local name = normalizeOption(option)
					if not name then return end
					config.particleStyle = name
					refreshEmitter()
				end,
			})
			addElement(VisualsTab, "Dropdown", {
				Title = "Quando aparecem",
				Values = PARTICLE_MODES,
				Value = config.particleMode,
				Callback = function(option)
					local name = normalizeOption(option)
					if name then config.particleMode = name end
				end,
			})
			addElement(VisualsTab, "Toggle", {
				Title = "Particulas arco-iris",
				Default = config.particleRainbow,
				Callback = function(v)
					config.particleRainbow = v
					refreshEmitter()
				end,
			})
			addElement(VisualsTab, "Colorpicker", {
				Title = "Cor das particulas",
				Default = config.particleColor,
				Callback = function(color)
					if typeof(color) ~= "Color3" then return end
					config.particleColor = color
					refreshEmitter()
				end,
			})
			addElement(VisualsTab, "Slider", {
				Title = "Quantidade",
				Step = 1,
				Value = { Min = 2, Max = 60, Default = config.particleRate },
				Callback = function(v) config.particleRate = v end,
			})
			addElement(VisualsTab, "Slider", {
				Title = "Tamanho",
				Step = 0.1,
				Value = { Min = 0.2, Max = 4, Default = config.particleSize },
				Callback = function(v)
					config.particleSize = v
					refreshEmitter()
				end,
			})
			addElement(VisualsTab, "Slider", {
				Title = "Velocidade",
				Step = 0.1,
				Value = { Min = 0.2, Max = 5, Default = config.particleSpeed },
				Callback = function(v)
					config.particleSpeed = v
					refreshEmitter()
				end,
			})
			if config.particlesEnabled then task.spawn(applyEmitter) end
		end

		addElement(VisualsTab, "Section", { Title = "Auras" })
		addElement(VisualsTab, "Dropdown", {
			Title = "Aura",
			Desc = "Efeito visual em volta do personagem.",
			Values = AURA_NAMES,
			Value = config.auraName,
			Callback = function(option)
				local name = normalizeOption(option)
				if not name then return end
				config.auraName = name
				local definition = AURAS[name]
