						pcall(function() auraColorpicker:Set(config.auraColor) end)
					end
					if auraColorpicker2 then
						pcall(function() auraColorpicker2:Set(config.auraColor2) end)
					end
				end
				applyAura()
			end,
		})
		auraColorpicker = addElement(VisualsTab, "Colorpicker", {
			Title = "Cor Principal da Aura",
