		addElement(VisualsTab, "Slider", {
			Title = "Intensidade da Aura",
			Desc = "Quantidade de particulas.",
			Value = { Min = 0.25, Max = 2, Default = config.auraIntensity },
			Step = 0.05,
			Callback = function(v)
				config.auraIntensity = v
				scheduleAuraReapply()
			end,
		})
		addElement(VisualsTab, "Toggle", {
			Title = "Circulo magico no chao",
			Desc = "Aneis de luz e hexagrama girando embaixo de voce.",
			Default = config.auraCircle,
			Callback = function(v)
				config.auraCircle = v
				scheduleAuraReapply()
			end,
		})
		addElement(VisualsTab, "Toggle", {
			Title = "Brilho (bloom)",
			Desc = "Faz as luzes da aura brilharem mais na tela.",
			Default = config.auraBloom,
			Callback = function(v)
				config.auraBloom = v
				scheduleAuraReapply()
			end,
		})
		addElement(VisualsTab, "Toggle", {
			Title = "Poeira de luz",
			Desc = "Particulas lentas flutuando em volta do corpo.",
			Default = config.auraMotes,
			Callback = function(v)
				config.auraMotes = v
				scheduleAuraReapply()
			end,
		})
		addElement(VisualsTab, "Toggle", {
			Title = "Modo leve (menos lag)",
			Desc = "Aura com metade dos itens, sem poeira de luz e sem bloom. Bom para celular fraco.",
			Default = config.lightMode,
			Callback = function(v)
				config.lightMode = v
				scheduleAuraReapply()
