		local function chooseAura(name)
			config.auraName = name
			local definition = AURAS[name]
			if definition then
				config.auraColor = definition.color
				config.auraColor2 = definition.color2 or definition.color
				if auraColorpicker then pcall(function() auraColorpicker:Set(config.auraColor) end) end
				if auraColorpicker2 then pcall(function() auraColorpicker2:Set(config.auraColor2) end) end
			end
			applyAura()
			selectOption("Aura", name)
		end
		local function randomAuraName()
			local names = {}
			for _, name in ipairs(AURA_NAMES) do
				if name ~= "Nenhuma" and name ~= config.auraName then table.insert(names, name) end
			end
			return names[math.random(1, #names)]
		end
