			local function runMorph(userText)
				local callOk, ok, message = pcall(applyMorph, userText)
				if not callOk then
					warn("Zenith: erro no Morph -> " .. tostring(ok))
					uiNotify("Morph", "Erro: " .. tostring(ok), 5)
