					}
					for entry in string.gmatch(config.skinFavorites, "[^;]+") do
						local name, ids = entry:match("^(.-)=(.+)$")
						local duplicated = false
						for _, existing in ipairs(list) do
							if existing.name == name then duplicated = true break end
						end
						if name and ids and not duplicated then table.insert(list, { name = name, ids = ids }) end
