				end
				local function favoriteNames()
					local names = {}
					for _, favorite in ipairs(parseFavorites()) do
						table.insert(names, favorite.name)
					end
					if #names == 0 then names[1] = "(nenhum favorito)" end
					return names
				end
				local function writeFavorites(list)
					local parts = {}
					for _, favorite in ipairs(list) do
						table.insert(parts, favorite.name .. "=" .. favorite.ids)
					end
					config.skinFavorites = table.concat(parts, ";")
					if favoriteDropdown then
						pcall(function() favoriteDropdown:Refresh(favoriteNames()) end)
					end
				end
				local function applyIds(ids)
					uiNotify("Item", "Carregando...", 2)
