				local hooked = setmetatable({}, { __mode = "k" })
				local applying = false
				local addedConnection = nil
				local NAME_HINTS = { "kick", "ball", "bola", "chute", "shoot", "pass", "bounce", "tps" }
				function module.resolveId()
					local raw = (tostring(config.ballSoundId or ""):gsub("%s", ""))
					if raw == "" then return nil end
					if tonumber(raw) then return "rbxassetid://" .. raw end
					if raw:match("^rbxassetid://") or raw:match("^rbxasset://") then return raw end
					if raw:find("roblox.com", 1, true) then
						local digits = raw:match("%d+")
						return digits and ("rbxassetid://" .. digits) or nil
					end
					if isfile and getcustomasset and isfile(raw) then
						local ok, asset = pcall(getcustomasset, raw)
						if ok then return asset end
					end
					return nil
				end
				local function nameMatches(name)
					local lowered = string.lower(name)
					for _, hint in ipairs(NAME_HINTS) do
						if lowered:find(hint, 1, true) then return true end
					end
					return false
				end
				local function isBallSound(sound)
					if string.sub(sound.Name, 1, 3) == "TCS" then return false end
					if sound.IsLoaded and sound.TimeLength > 8 then return false end
					local ball = findBall()
					if ball and sound:IsDescendantOf(ball) then return true end
					local model = sound:FindFirstAncestorOfClass("Model")
					if model and model:FindFirstChildOfClass("Humanoid") then return nameMatches(sound.Name) end
					local parent = sound.Parent
					if ball and parent and parent:IsA("BasePart") and parent:IsDescendantOf(workspace)
						and (parent.Position - ball.Position).Magnitude <= 20 then
						return true
					end
					return nameMatches(sound.Name)
				end
local POOL_SIZE = 6
local pool, poolIndex, poolId = {}, 0, nil
local lastTrigger = setmetatable({}, { __mode = "k" })
local function destroyPool()
	for _, item in ipairs(pool) do pcall(function() item:Destroy() end) end
	table.clear(pool)
	poolId = nil
end
-- Pool de sons proprios: cada chute toca um som novo, mesmo em cliques rapidos.
local function warmPool()
	local id = module.resolveId()
	if not id or poolId == id then return id end
	destroyPool()
	poolId = id
	for index = 1, POOL_SIZE do
		local item = Instance.new("Sound")
		item.Name = "TCSBallPool"
		item.SoundId = id
		item.Volume = config.ballSoundVolume
		item.Parent = soundService
		pool[index] = item
	end
	task.spawn(function()
		pcall(function() game:GetService("ContentProvider"):PreloadAsync(pool) end)
	end)
	return id
end
local function playCustom()
	if not warmPool() then return end
	poolIndex = poolIndex % POOL_SIZE + 1
	local item = pool[poolIndex]
	if not item then return end
	pcall(function()
		item.Volume = config.ballSoundVolume
		item.TimePosition = 0
		item:Play()
	end)
end
-- Silencia o som original da bola (o som novo toca pelo pool).
local function applySound(sound)
	if not config.ballSoundEnabled then return false end
	if not originals[sound] then originals[sound] = { id = sound.SoundId, volume = sound.Volume } end
	if not (config.ballSoundMute or module.resolveId()) then return false end
	applying = true
	pcall(function() sound.Volume = 0 end)
	applying = false
	return true
end
local function hook(sound)
	if hooked[sound] then return end
	hooked[sound] = {
		sound:GetPropertyChangedSignal("Volume"):Connect(function()
			if applying or not config.ballSoundEnabled or sound.Volume == 0 then return end
			if isBallSound(sound) then applySound(sound) end
		end),
		sound.Played:Connect(function()
			if not config.ballSoundEnabled or not isBallSound(sound) then return end
			if not applySound(sound) then return end
			if config.ballSoundMute then return end
			local now = os.clock()
			if lastTrigger[sound] and now - lastTrigger[sound] < 0.03 then return end
			lastTrigger[sound] = now
			playCustom()
		end),
	}
	if config.ballSoundEnabled and isBallSound(sound) then applySound(sound) end
end
				local function scan(root)
					local count = 0
					for _, descendant in ipairs(root:GetDescendants()) do
						if descendant:IsA("Sound") then hook(descendant) end
						count = count + 1
						if count % 300 == 0 then task.wait() end
					end
				end
				function module.refresh()
if config.ballSoundEnabled and not config.ballSoundMute then warmPool() end
					for sound in pairs(hooked) do
						if sound.Parent and isBallSound(sound) then applySound(sound) end
					end
				end
				function module.enable()
					if addedConnection then return end
					addedConnection = game.DescendantAdded:Connect(function(instance)
						if instance:IsA("Sound") then hook(instance) end
					end)
					task.spawn(function()
						scan(workspace)
						scan(soundService)
						module.refresh()
					end)
				end
				function module.disable()
destroyPool()
					if addedConnection then
						addedConnection:Disconnect()
						addedConnection = nil
					end
					applying = true
					for sound, original in pairs(originals) do
						if sound.Parent then
							pcall(function()
								sound.SoundId = original.id
								sound.Volume = original.volume
							end)
						end
					end
					applying = false
					table.clear(originals)
					for sound, connections in pairs(hooked) do
						for _, connection in ipairs(connections) do connection:Disconnect() end
					end
					table.clear(hooked)
				end
				function module.test()
					local id = module.resolveId()
					if not id then return false, "Digite o ID do som primeiro." end
					local sound = Instance.new("Sound")
					sound.Name = "TCSBallTest"
					sound.SoundId = id
					sound.Volume = config.ballSoundVolume
					sound.Parent = soundService
					sound:Play()
					task.delay(8, function() sound:Destroy() end)
					return true
				end
				registerCleanup(module.disable)
				return module
			end)()
