			ballTrailToggle = addElement(BallTab, "Toggle", {
				Title = "Rastro",
				Desc = "Fita de luz atras da bola.",
				Default = config.ballTrailOn,
				Callback = function(v)
					config.ballTrailOn = v
					if config.ballSkinEnabled then refreshBallSkin() end
				end,
			})
			ballTrailColorpicker = addElement(BallTab, "Colorpicker", {
				Title = "Cor do rastro",
				Default = config.ballTrailColor,
				Callback = function(color)
					if typeof(color) ~= "Color3" then return end
					config.ballTrailColor = color
					if config.ballSkinEnabled then refreshBallSkin() end
				end,
			})
			addElement(BallTab, "Slider", {
				Title = "Duracao do rastro (s)",
				Value = { Min = 0.1, Max = 2, Default = config.ballTrailLife },
				Step = 0.05,
				Callback = function(v)
					config.ballTrailLife = v
					if config.ballSkinEnabled then refreshBallSkin() end
				end,
			})
			ballLightToggle = addElement(BallTab, "Toggle", {
				Title = "Luz na bola",
				Default = config.ballLightOn,
				Callback = function(v)
					config.ballLightOn = v
					if config.ballSkinEnabled then refreshBallSkin() end
				end,
			})
			ballLightColorpicker = addElement(BallTab, "Colorpicker", {
				Title = "Cor da luz",
				Default = config.ballLightColor,
				Callback = function(color)
					if typeof(color) ~= "Color3" then return end
					config.ballLightColor = color
					if config.ballSkinEnabled then refreshBallSkin() end
				end,
			})
			addElement(BallTab, "Slider", {
				Title = "Alcance da luz",
				Value = { Min = 4, Max = 30, Default = config.ballLightRange },
				Step = 1,
				Callback = function(v)
					config.ballLightRange = v
					if config.ballSkinEnabled then refreshBallSkin() end
				end,
			})
			ballGlowToggle = addElement(BallTab, "Toggle", {
				Title = "Brilho em volta da bola",
				Desc = "Aura suave que pulsa e acende quando a bola leva um chute.",
				Default = config.ballGlowOn,
				Callback = function(v)
					config.ballGlowOn = v
					if config.ballSkinEnabled then refreshBallSkin() end
				end,
			})
			ballOrbitToggle = addElement(BallTab, "Toggle", {
				Title = "Esferas orbitando",
				Desc = "Quatro esferas de luz com rastro girando em volta da bola.",
				Default = config.ballOrbitOn,
				Callback = function(v)
					config.ballOrbitOn = v
					if config.ballSkinEnabled then refreshBallSkin() end
				end,
			})
			ballBurstToggle = addElement(BallTab, "Toggle", {
				Title = "Faiscas no chute",
				Desc = "Explosao de faiscas quando a bola leva uma pancada.",
				Default = config.ballBurstOn,
				Callback = function(v)
					config.ballBurstOn = v
					if config.ballSkinEnabled then refreshBallSkin() end
				end,
			})
			addElement(BallTab, "Button", {
				Title = "Restaurar bola original",
				Callback = function()
					config.ballSkinEnabled = false
					restoreBallLook()
					if ballToggle then pcall(function() ballToggle:Set(false) end) end
				end,
			})
		end
		local skyIdValue = config.skyCustomId
		addElement(WorldTab, "Section", { Title = "Efeito de gol" })
		addElement(WorldTab, "Toggle", {
			Title = "Efeito de gol",
			Desc = "Flash, faixa GOL! e confete na tela quando o placar sobe.",
			Default = config.goalEffectEnabled,
			Callback = function(v) config.goalEffectEnabled = v end,
		})
		addElement(WorldTab, "Dropdown", {
			Title = "Estilo do efeito",
			Desc = "Completo: confete + ondas. Fogos: explosoes. Neon: ondas fortes. Minimo: so a faixa.",
			Values = GOAL_EFFECT_STYLES,
			Value = config.goalEffectStyle,
			Callback = function(option)
				local style = normalizeOption(option)
				if style then config.goalEffectStyle = style end
			end,
		})
		addElement(WorldTab, "Toggle", {
			Title = "Efeitos no mundo (pilar, fogos, bloom)",
			Desc = "Pilar de luz, ondas, fogos e brilho na bola, so voce ve.",
			Default = config.goalEffectWorld,
			Callback = function(v) config.goalEffectWorld = v end,
		})
		addElement(WorldTab, "Toggle", {
			Title = "Tremer a camera",
			Default = config.goalEffectShake,
			Callback = function(v) config.goalEffectShake = v end,
		})
		addElement(WorldTab, "Input", {
			Title = "Texto do efeito",
			Placeholder = "GOL!",
			Callback = function(text)
				if text and text ~= "" then config.goalEffectText = tostring(text) end
			end,
		})
		addElement(WorldTab, "Button", {
			Title = "Testar efeito de gol",
			Callback = function() if testGoalEffect then testGoalEffect() end end,
		})
		addElement(WorldTab, "Section", { Title = "Som de gol" })
		addElement(WorldTab, "Toggle", {
			Title = "Som de gol",
			Desc = "Toca um som do narrador quando o placar sobe (qualquer time).",
			Default = config.goalSoundEnabled,
			Callback = function(v) config.goalSoundEnabled = v end,
		})
		addElement(WorldTab, "Dropdown", {
			Title = "Som do gol",
			Desc = "Sequencia: First Blood no 1o gol, Double Kill no 2o... Ou escolha um fixo.",
			Values = GOAL_SOUND_MODES,
			Value = config.goalSoundMode,
			Callback = function(option)
				local mode = normalizeOption(option)
				if mode then config.goalSoundMode = mode end
			end,
		})
		addElement(WorldTab, "Input", {
			Title = "ID do som (modo ID personalizado)",
			Desc = "Numero de um audio do Roblox. So vale no modo ID personalizado.",
			Placeholder = "ID do audio",
			Callback = function(text)
				config.goalSoundId = tostring(text or "")
			end,
		})
		addElement(WorldTab, "Slider", {
			Title = "Volume do som de gol",
			Value = { Min = 0, Max = 3, Default = config.goalSoundVolume },
			Step = 0.1,
			Callback = function(v) config.goalSoundVolume = v end,
		})
		addElement(WorldTab, "Button", {
			Title = "Testar som de gol",
			Callback = function()
				local ok, reason = playGoalSound(1)
				if not ok then uiNotify("Som de gol", reason or "Nao foi possivel tocar.", 5) end
			end,
		})
		addElement(WorldTab, "Section", { Title = "Skybox" })
		addElement(WorldTab, "Dropdown", {
			Title = "Skybox",
			Desc = "Os com (imagem) usam skybox por imagem; os outros so mudam a iluminacao.",
			Values = SKY_PRESET_NAMES,
			Value = config.skyPreset,
			Callback = function(option)
				local name = normalizeOption(option)
				if not name then return end
				config.skyPreset = name
				applySkyPreset(name)
			end,
		})
		addElement(WorldTab, "Toggle", {
			Title = "Travar skybox",
			Desc = "Reaplica se o jogo mudar o ceu ou a iluminacao.",
			Default = config.skyLock,
			Callback = function(v) config.skyLock = v end,
		})
		addElement(WorldTab, "Slider", {
			Title = "Estrelas",
			Value = { Min = 0, Max = 5000, Default = config.skyStars },
			Step = 100,
			Callback = function(v) setSkyStars(v) end,
		})
		addElement(WorldTab, "Input", {
			Title = "Sky ID personalizado",
			Placeholder = "ID da imagem do skybox",
			Callback = function(text) skyIdValue = text end,
		})
		addElement(WorldTab, "Button", {
			Title = "Aplicar Sky ID",
			Callback = function()
				local ok = applySkyImageId(skyIdValue)
				if ok then config.skyCustomId = skyIdValue end
				uiNotify("Skybox", ok and "Sky aplicado." or "ID invalido.", 3)
			end,
		})
		addElement(WorldTab, "Button", {
			Title = "Restaurar mundo",
			Desc = "Volta ceu, iluminacao e atmosfera do jogo.",
			Callback = function()
				config.skyPreset = "Nenhum"
				restoreWorld()
			end,
		})
		addElement(WorldTab, "Section", { Title = "Hora do dia" })
		addElement(WorldTab, "Toggle", {
			Title = "Controlar hora",
			Default = config.worldClockOn,
			Callback = function(v) config.worldClockOn = v end,
		})
		addElement(WorldTab, "Slider", {
			Title = "Hora do dia",
			Desc = "Hora usada quando 'Controlar hora' esta ligado.",
			Value = { Min = 0, Max = 24, Default = config.worldClock },
			Step = 0.1,
			Callback = function(v) config.worldClock = v end,
		})
		addElement(WorldTab, "Slider", {
			Title = "Velocidade do ciclo (horas por segundo)",
			Desc = "0 = hora parada.",
			Value = { Min = 0, Max = 2, Default = config.worldCycle },
			Step = 0.05,
			Callback = function(v) config.worldCycle = v end,
		})
		addElement(WorldTab, "Section", { Title = "Iluminacao e Gramado" })
		addElement(WorldTab, "Toggle", {
			Title = "Sombras",
			Default = config.worldShadows,
			Callback = function(v) setWorldShadows(v) end,
		})
		addElement(WorldTab, "Dropdown", {
			Title = "Cor do gramado",
			Values = GRASS_PRESET_NAMES,
			Value = config.grassPreset,
			Callback = function(option)
				local name = normalizeOption(option)
				if not name then return end
				config.grassPreset = name
				applyGrassPreset(name)
			end,
		})
		addElement(WorldTab, "Section", { Title = "Camera" })
		addElement(WorldTab, "Toggle", {
			Title = "FOV fixo",
			Default = config.fovOn,
			Callback = function(v) setFov(v) end,
		})
		addElement(WorldTab, "Slider", {
			Title = "FOV",
			Desc = "Campo de visao da camera.",
			Value = { Min = 40, Max = 120, Default = config.fov },
			Step = 1,
			Callback = function(v) config.fov = v end,
		})
		addElement(WorldTab, "Toggle", {
			Title = "Tela esticada",
			Desc = "Mais campo de visao nas laterais (FieldOfViewMode MaxAxis).",
			Default = config.stretchOn,
			Callback = function(v) setStretch(v) end,
		})
		addElement(WorldTab, "Section", { Title = "Desempenho" })
		addElement(WorldTab, "Toggle", {
			Title = "FPS Boost",
			Desc = "Sombras e qualidade no minimo, particulas do mapa desligadas.",
			Default = config.fpsBoostOn,
			Callback = function(v) setFpsBoost(v) end,
		})
	end
	local insertConnection = userInputService.InputBegan:Connect(function(input, processed)
		if input.KeyCode == Enum.KeyCode.Insert then
			destroyEverything()
		elseif input.KeyCode == Enum.KeyCode.End and not processed then
			disableEverything()
		end
	end)
	registerCleanup(function() insertConnection:Disconnect() end)
end
print("Zenith: carregado - versao " .. tostring(QuickButtons.version))
